import React, { useState, useEffect } from 'react';
import { TelegramGroup, GeminiInsight } from '../types';
import { Icons } from '../constants';
import { getGroupInsights, generateLinkDescription } from '../services/geminiService';

interface InviteModalProps {
  group: TelegramGroup;
  onClose: () => void;
}

const InviteModal: React.FC<InviteModalProps> = ({ group, onClose }) => {
  const [link, setLink] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [insight, setInsight] = useState<GeminiInsight | null>(null);
  const [aiDescription, setAiDescription] = useState<string>('');
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    const fetchAI = async () => {
      const res = await getGroupInsights(group);
      setInsight(res);
      const desc = await generateLinkDescription(group.name);
      setAiDescription(desc);
    };
    fetchAI();
  }, [group]);

  const handleGenerateLink = () => {
    setIsGenerating(true);
    // Simulate Telegram API call
    setTimeout(() => {
      const randomString = Math.random().toString(36).substring(7);
      setLink(`https://t.me/joinchat/${randomString}`);
      setIsGenerating(false);
    }, 1200);
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(link);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={onClose} />

      <div className="relative bg-slate-900 border border-slate-800 w-full max-w-2xl rounded-[32px] overflow-hidden shadow-2xl flex flex-col md:flex-row">
        {/* Left Side: Info & AI Insights */}
        <div className="md:w-1/2 p-8 border-r border-slate-800">
          <div className="mb-6">
            <h2 className="text-2xl font-bold text-white mb-2">{group.name}</h2>
            <div className="flex items-center gap-2 text-slate-400 text-sm">
              <Icons.Users size={14} />
              <span>{group.memberCount} members</span>
            </div>
          </div>

          <div className="space-y-4">
            <h4 className="text-xs font-bold text-blue-400 uppercase tracking-widest flex items-center gap-2">
              <Icons.Zap size={14} /> AI Admin Insight
            </h4>
            {!insight ? (
              <div className="space-y-2 animate-pulse">
                <div className="h-4 bg-slate-800 rounded w-full" />
                <div className="h-4 bg-slate-800 rounded w-3/4" />
                <div className="h-20 bg-slate-800 rounded w-full" />
              </div>
            ) : (
              <div className="bg-slate-800/40 p-4 rounded-2xl border border-slate-700/50">
                <h5 className="text-slate-200 font-semibold mb-1 text-sm">{insight.title}</h5>
                <p className="text-slate-400 text-xs leading-relaxed mb-3">{insight.summary}</p>
                <div className="p-2 bg-blue-500/10 rounded-lg border border-blue-500/20">
                  <p className="text-blue-300 text-[11px] italic">" {insight.suggestion} "</p>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Right Side: Link Generation */}
        <div className="md:w-1/2 p-8 bg-slate-800/20 flex flex-col justify-center">
          <div className="text-center mb-8">
            <div className="w-16 h-16 bg-blue-600/10 text-blue-500 rounded-full flex items-center justify-center mx-auto mb-4 border border-blue-500/20">
              <Icons.Link size={32} />
            </div>
            <h3 className="text-xl font-bold text-white mb-2">Single-Use Link</h3>
            <p className="text-slate-400 text-sm">This link will expire automatically after one person joins.</p>
          </div>

          {!link ? (
            <button
              disabled={isGenerating}
              onClick={handleGenerateLink}
              className={`w-full py-4 rounded-2xl font-bold text-white flex items-center justify-center gap-2 transition-all duration-300 ${
                isGenerating ? 'bg-slate-700 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-500 hover:scale-[1.02] shadow-xl shadow-blue-500/20'
              }`}
            >
              {isGenerating ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                  Generating...
                </>
              ) : (
                'Generate Exclusive Link'
              )}
            </button>
          ) : (
            <div className="space-y-4">
              <div className="bg-slate-950 p-4 rounded-2xl border border-slate-700 relative group overflow-hidden">
                <div className="text-blue-400 font-mono text-xs truncate pr-10">{link}</div>
                <button 
                  onClick={copyToClipboard}
                  className="absolute right-3 top-1/2 -translate-y-1/2 p-2 hover:bg-slate-800 rounded-lg text-slate-400 transition-colors"
                >
                  {copied ? <Icons.Check size={18} className="text-emerald-500" /> : <Icons.Copy size={18} />}
                </button>
              </div>
              <div className="p-4 bg-emerald-500/10 border border-emerald-500/20 rounded-2xl">
                <p className="text-[11px] text-emerald-300 leading-tight">
                  <span className="font-bold">Pro Tip:</span> {aiDescription || "Sending this to your high-value lead."}
                </p>
              </div>
              <button 
                onClick={onClose}
                className="w-full py-3 text-slate-400 hover:text-white transition-colors text-sm font-medium"
              >
                Done
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

