const BASE_URL = 'https://api.telegram.org/bot';

export interface TelegramBotInfo {
  id: number;
  is_bot: boolean;
  first_name: string;
  username: string;
}

export interface TelegramChat {
  id: number;
  title: string;
  type: string;
  description?: string;
}

export async function verifyBotToken(token: string): Promise<TelegramBotInfo> {
  const response = await fetch(`${BASE_URL}${token}/getMe`);
  const data = await response.json();
  if (!data.ok) throw new Error(data.description || 'Invalid Token');
  return data.result;
}

export async function getChatDetails(token: string, chatId: string | number): Promise<TelegramChat> {
  const response = await fetch(`${BASE_URL}${token}/getChat?chat_id=${chatId}`);
  const data = await response.json();
  if (!data.ok) throw new Error(data.description || 'Could not find chat. Make sure the bot is an admin in the group.');
  return data.result;
}

export async function createInviteLink(
  token: string, 
  chatId: string | number, 
  limit: number, 
  expireMinutes: number
): Promise<string> {
  let url = `${BASE_URL}${token}/createChatInviteLink?chat_id=${chatId}&member_limit=${limit}`;

  if (expireMinutes > 0) {
    const expireDate = Math.floor(Date.now() / 1000) + (expireMinutes * 60);
    url += `&expire_date=${expireDate}`;
  }

  const response = await fetch(url);
  const data = await response.json();
  if (!data.ok) throw new Error(data.description || 'Failed to create invite link');
  return data.result.invite_link;
}

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import GroupCard from './components/GroupCard';
import InviteModal from './components/InviteModal';
import { Icons } from './constants';
import { TelegramGroup } from './types';
import { verifyBotToken, getChatDetails, TelegramBotInfo } from './services/telegramService';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Real State
  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [groups, setGroups] = useState<TelegramGroup[]>(JSON.parse(localStorage.getItem('tg_groups') || '[]'));
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  const handleVerify = async (testToken: string) => {
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const handleAddGroup = async () => {
    if (!token || !newChatId) return;
    setIsAddingGroup(true);
    setError(null);
    try {
      const chat = await getChatDetails(token, newChatId);
      const newGroup: TelegramGroup = {
        id: chat.id.toString(),
        name: chat.title,
        memberCount: 0, // getChat doesn't always return member count for bots unless they are admins and it's a supergroup
        description: chat.description || 'Synced via TeleBridge',
        category: 'Telegram Group',
        image: `https://picsum.photos/seed/${chat.id}/200`
      };

      const updatedGroups = [...groups.filter(g => g.id !== newGroup.id), newGroup];
      setGroups(updatedGroups);
      localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
      setNewChatId('');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAddingGroup(false);
    }
  };

  const filteredGroups = groups.filter(g => 
    g.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col md:flex-row">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />

      <main className="flex-1 md:ml-64 p-5 md:p-10 pb-24 md:pb-10">
        <header className="flex flex-col gap-6 mb-10">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl md:text-5xl font-black text-white tracking-tight mb-2 capitalize">
                {activeTab}
              </h1>
              <div className="flex items-center gap-2">
                <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.6)]' : 'bg-rose-500'}`} />
                <p className="text-slate-500 text-sm font-medium">
                  {botInfo ? `Connected as @${botInfo.username}` : 'Disconnected'}
                </p>
              </div>
            </div>

            <button 
              onClick={() => handleVerify(token)}
              className="hidden md:flex items-center gap-2 px-6 py-3 bg-slate-900 border border-slate-800 hover:border-slate-700 text-white font-bold rounded-2xl transition-all active:scale-95"
            >
              <Icons.Zap size={18} className={isVerifying ? 'animate-spin' : ''} />
              Refresh Bot
            </button>
          </div>

          {(activeTab === 'dashboard' || activeTab === 'groups') && (
            <div className="flex flex-col md:flex-row items-center gap-4">
              <div className="relative group w-full md:flex-1">
                <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none text-slate-500 group-focus-within:text-blue-500 transition-colors">
                  <Icons.Home size={20} />
                </div>
                <input 
                  type="text" 
                  placeholder="Search your groups..." 
                  className="bg-slate-900 border border-slate-800 text-white pl-12 pr-6 py-4 rounded-2xl w-full focus:ring-2 focus:ring-blue-500/50 outline-none transition-all shadow-inner"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex w-full md:w-auto gap-2">
                <input 
                  type="text" 
                  placeholder="Group Chat ID (e.g. -100...)" 
                  className="flex-1 md:w-64 bg-slate-900 border border-slate-800 px-4 py-4 rounded-2xl text-sm focus:ring-2 focus:ring-emerald-500/50 outline-none"
                  value={newChatId}
                  onChange={(e) => setNewChatId(e.target.value)}
                />
                <button 
                  onClick={handleAddGroup}
                  disabled={isAddingGroup || !botInfo}
                  className="px-6 py-4 bg-emerald-600 hover:bg-emerald-500 disabled:bg-slate-800 disabled:text-slate-500 text-white font-bold rounded-2xl transition-all whitespace-nowrap"
                >
                  {isAddingGroup ? 'Syncing...' : 'Sync Group'}
                </button>
              </div>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-2xl text-sm flex items-center gap-3">
             <div className="p-1 bg-rose-500/20 rounded-lg">!</div>
             {error}
          </div>
        )}

        {activeTab === 'dashboard' || activeTab === 'groups' ? (
          <div className="space-y-12">
            {activeTab === 'dashboard' && (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5 md:gap-8">
                {[
                  { label: 'Connected Groups', value: groups.length.toString(), trend: 'Realtime', icon: Icons.Users, color: 'text-blue-400' },
                  { label: 'Bot Identity', value: botInfo ? `@${botInfo.username}` : 'None', trend: botInfo ? 'Online' : 'Offline', icon: Icons.Zap, color: 'text-amber-400' },
                  { label: 'System Health', value: 'Active', trend: '100%', icon: Icons.Check, color: 'text-emerald-400' },
                ].map((stat, i) => (
                  <div key={i} className="bg-slate-900 border border-slate-800 p-6 rounded-[28px]">
                    <div className="flex items-center justify-between mb-4">
                      <div className={`p-3 bg-slate-800 rounded-2xl ${stat.color}`}>
                        <stat.icon size={24} />
                      </div>
                      <span className="text-[10px] font-black text-emerald-400 bg-emerald-400/10 px-2.5 py-1 rounded-full uppercase tracking-widest border border-emerald-500/20">
                        {stat.trend}
                      </span>
                    </div>
                    <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mb-1">{stat.label}</p>
                    <p className="text-xl md:text-2xl font-black text-white truncate">{stat.value}</p>
                  </div>
                ))}
              </div>
            )}

            <section>
              <div className="flex items-center justify-between mb-8">
                <h2 className="text-xl md:text-2xl font-bold text-white flex items-center gap-3">
                  <div className="w-1.5 h-6 bg-blue-600 rounded-full" />
                  Live Groups
                </h2>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 md:gap-8">
                {filteredGroups.length > 0 ? (
                  filteredGroups.map(group => (
                    <GroupCard 
                      key={group.id} 
                      group={group} 
                      onClick={(g) => setSelectedGroup(g)} 
                    />
                  ))
                ) : (
                  <div className="col-span-full py-20 text-center bg-slate-900/40 rounded-[40px] border-2 border-dashed border-slate-800">
                    <div className="w-24 h-24 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-600">
                      <Icons.Users size={48} />
                    </div>
                    <h3 className="text-2xl font-bold text-slate-300">No Groups Connected</h3>
                    <p className="text-slate-500 max-w-sm mx-auto mt-3 px-6">
                      1. Add your bot to a group.<br/>
                      2. Make it an Admin.<br/>
                      3. Paste the Group's Chat ID above to sync it.
                    </p>
                  </div>
                )}
              </div>
            </section>
          </div>
        ) : activeTab === 'settings' ? (
          <div className="max-w-4xl space-y-8">
            <div className="bg-slate-900 border border-slate-800 rounded-[32px] overflow-hidden shadow-2xl">
              <div className="p-8 md:p-12 space-y-10">
                <div>
                   <h2 className="text-2xl md:text-3xl font-black text-white mb-2">Bot API Connection</h2>
                   <p className="text-slate-500 font-medium">Use your Telegram Bot Token from @BotFather to establish a real connection.</p>
