                <div className="space-y-6">
                  <div className="space-y-3">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                      <Icons.Zap size={14} className="text-blue-500" /> Bot Token
                    </label>
                    <input 
                      type="password" 
                      placeholder="123456789:ABCDEF..."
                      className="w-full bg-slate-950 border border-slate-800 px-5 py-4 rounded-2xl text-slate-300 focus:ring-2 focus:ring-blue-500/50 outline-none transition-all font-mono"
                      value={token}
                      onChange={(e) => setToken(e.target.value)}
