                  </div>
                </div>

                <div className="pt-4 flex flex-col md:flex-row gap-4">
                  <button 
                    onClick={() => handleVerify(token)}
                    disabled={isVerifying}
                    className="flex-1 px-10 py-4 bg-blue-600 hover:bg-blue-500 text-white font-bold rounded-2xl transition-all shadow-xl shadow-blue-500/20 active:scale-95"
                  >
                    {isVerifying ? 'Connecting...' : 'Connect & Save'}
