import React, { useState, useEffect } from 'react';
import { TelegramGroup, GeminiInsight } from '../types';
import { Icons } from '../constants';
import { getGroupInsights, generateLinkDescription } from '../services/geminiService';
import { createInviteLink } from '../services/telegramService';

interface InviteModalProps {
  group: TelegramGroup;
  onClose: () => void;
  botToken: string;
}

const InviteModal: React.FC<InviteModalProps> = ({ group, onClose, botToken }) => {
  const [link, setLink] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [insight, setInsight] = useState<GeminiInsight | null>(null);
  const [aiDescription, setAiDescription] = useState<string>('');
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const [useLimit, setUseLimit] = useState(1);
  const [expiration, setExpiration] = useState('0'); 

  useEffect(() => {
    const fetchAI = async () => {
      const res = await getGroupInsights(group);
      setInsight(res);
      const desc = await generateLinkDescription(group.name);
      setAiDescription(desc);
    };
    fetchAI();
  }, [group]);

  const handleGenerateLink = async () => {
    if (!botToken) {
      setError("Connect your bot in settings first!");
      return;
    }

    setIsGenerating(true);
    setError(null);
    try {
      const realLink = await createInviteLink(
        botToken, 
        group.id, 
        useLimit, 
        parseInt(expiration)
      );
      setLink(realLink);
    } catch (err: any) {
      setError(err.message || 'Failed to generate link. Is the bot an admin?');
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(link);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md" onClick={onClose} />

      <div className="relative bg-slate-900 border border-slate-800 w-full max-w-4xl rounded-[32px] overflow-hidden shadow-2xl flex flex-col md:flex-row max-h-[90vh] md:max-h-none overflow-y-auto">
        <div className="md:w-1/2 p-6 md:p-10 border-b md:border-b-0 md:border-r border-slate-800">
          <div className="mb-6">
            <h2 className="text-2xl md:text-3xl font-bold text-white mb-2">{group.name}</h2>
            <div className="flex items-center gap-3 text-slate-400 text-sm">
              <span className="text-blue-400 font-medium">Chat ID: {group.id}</span>
            </div>
          </div>

          <div className="space-y-6">
            <h4 className="text-xs font-bold text-blue-400 uppercase tracking-widest flex items-center gap-2">
              <Icons.Zap size={14} /> AI Analysis
            </h4>
            {!insight ? (
              <div className="space-y-3 animate-pulse">
                <div className="h-6 bg-slate-800 rounded-lg w-full" />
                <div className="h-24 bg-slate-800 rounded-2xl w-full" />
              </div>
            ) : (
              <div className="space-y-4">
                <div className="bg-slate-800/40 p-5 rounded-2xl border border-slate-700/50">
                  <h5 className="text-slate-200 font-bold mb-2 text-base">{insight.title}</h5>
                  <p className="text-slate-400 text-sm leading-relaxed mb-4">{insight.summary}</p>
                  <div className="p-3 bg-blue-500/10 rounded-xl border border-blue-500/20">
                    <p className="text-blue-300 text-xs italic font-medium leading-tight">
                      {insight.suggestion}
                    </p>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="md:w-1/2 p-6 md:p-10 bg-slate-800/10 flex flex-col justify-start">
          <div className="text-left mb-8">
             <div className="flex items-center gap-3 mb-2">
                <div className="p-2 bg-blue-600/20 text-blue-500 rounded-lg border border-blue-500/20">
                  <Icons.Link size={20} />
                </div>
                <h3 className="text-xl font-bold text-white">Invite Settings</h3>
             </div>
            <p className="text-slate-400 text-sm">Configure real Telegram invite parameters.</p>
          </div>

          {error && (
            <div className="mb-6 p-4 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl text-xs">
              {error}
            </div>
          )}

          {!link ? (
            <div className="space-y-8">
              <div className="space-y-6">
                <div className="space-y-3">
                  <div className="flex justify-between items-center">
                    <label className="text-xs font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                      <Icons.Users size={14} /> Usage Limit
                    </label>
                    <span className="text-blue-400 font-bold text-sm bg-blue-400/10 px-2 py-0.5 rounded-md">
                      {useLimit === 1 ? 'Single Use' : `${useLimit} People`}
                    </span>
                  </div>
                  <input 
                    type="range" 
                    min="1" 
                    max="100" 
                    step="1"
                    value={useLimit}
                    onChange={(e) => setUseLimit(parseInt(e.target.value))}
                    className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-600"
                  />
                </div>

                <div className="space-y-3">
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <Icons.Clock size={14} /> Expiration
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {[
                      { label: '30 Min', value: '30' },
                      { label: '1 Hour', value: '60' },
                      { label: '1 Day', value: '1440' },
                      { label: 'Never', value: '0' },
                    ].map((opt) => (
                      <button
                        key={opt.value}
                        onClick={() => setExpiration(opt.value)}
                        className={`py-2.5 px-4 rounded-xl text-sm font-semibold transition-all border ${
                          expiration === opt.value 
                            ? 'bg-blue-600 border-blue-500 text-white' 
                            : 'bg-slate-900 border-slate-700 text-slate-400'
                        }`}
                      >
                        {opt.label}
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <button
                disabled={isGenerating}
                onClick={handleGenerateLink}
                className={`w-full py-4 rounded-2xl font-bold text-white flex items-center justify-center gap-2 transition-all ${
                  isGenerating ? 'bg-slate-700 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-500 shadow-xl shadow-blue-500/20'
                }`}
              >
                {isGenerating ? 'Creating Link...' : 'Generate Real Link'}
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="text-center mb-6">
                <div className="w-16 h-16 bg-emerald-500/10 text-emerald-500 rounded-full flex items-center justify-center mx-auto mb-4 border border-emerald-500/20">
                  <Icons.Check size={32} />
                </div>
                <h4 className="text-lg font-bold text-white">Live Telegram Link</h4>
              </div>

              <div className="bg-slate-950 p-5 rounded-2xl border border-slate-700 relative group overflow-hidden">
                <div className="text-blue-400 font-mono text-sm truncate pr-12">{link}</div>
                <button 
                  onClick={copyToClipboard}
                  className="absolute right-3 top-1/2 -translate-y-1/2 p-2.5 bg-slate-800 hover:bg-slate-700 rounded-xl text-slate-200 transition-all active:scale-90"
                >
                  {copied ? <Icons.Check size={20} className="text-emerald-500" /> : <Icons.Copy size={20} />}
                </button>
              </div>

              <div className="p-4 bg-blue-500/5 border border-blue-500/20 rounded-2xl">
                <p className="text-xs text-slate-400 leading-relaxed italic">
                  "{aiDescription}"
                </p>
              </div>

              <div className="flex gap-3">
                <button onClick={() => setLink('')} className="flex-1 py-3 bg-slate-800 rounded-xl text-slate-300 text-sm font-bold">New Link</button>
                <button onClick={onClose} className="flex-1 py-3 bg-blue-600/10 text-blue-400 rounded-xl text-sm font-bold">Close</button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

