import React, { useState, useEffect } from 'react';
import { TelegramGroup, GeminiInsight } from '../types';
import { Icons } from '../constants';
import { getGroupInsights, generateLinkDescription } from '../services/geminiService';
import { createInviteLink } from '../services/telegramService';

interface InviteModalProps {
  group: TelegramGroup;
  onClose: () => void;
  botToken: string;
}

const InviteModal: React.FC<InviteModalProps> = ({ group, onClose, botToken }) => {
  const [link, setLink] = useState<string>('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [aiDescription, setAiDescription] = useState<string>('');
  const [copied, setCopied] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Default values for "Default: One person, No limit"
  const [useLimit, setUseLimit] = useState(1);
  const [expiration, setExpiration] = useState('0'); 

  // Auto-generate on open
  useEffect(() => {
    if (botToken && group) {
      handleGenerateLink();
    }
    const fetchAI = async () => {
      const desc = await generateLinkDescription(group.name);
      setAiDescription(desc);
    };
    fetchAI();
  }, [group, botToken]);

  const handleGenerateLink = async () => {
    if (!botToken) {
      setError("Connect your bot in settings first!");
      return;
    }

    setIsGenerating(true);
    setError(null);
    try {
      const realLink = await createInviteLink(
        botToken, 
        group.id, 
        useLimit, 
        parseInt(expiration)
      );
      setLink(realLink);
    } catch (err: any) {
      setError(err.message || 'Failed to generate link. Is the bot an admin?');
    } finally {
      setIsGenerating(false);
    }
  };

  const copyToClipboard = () => {
    if (!link) return;
    navigator.clipboard.writeText(link);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-sm" onClick={onClose} />

      <div className="relative bg-slate-900 border border-slate-800 w-full max-w-md rounded-3xl overflow-hidden shadow-2xl flex flex-col p-6">
        <div className="flex justify-between items-center mb-6">
           <div>
             <h2 className="text-xl font-bold text-white truncate pr-4">{group.name}</h2>
             <p className="text-xs text-slate-500">Single-use Invite Link</p>
           </div>
           <button onClick={onClose} className="text-slate-500 hover:text-white transition-colors p-1">
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" /></svg>
           </button>
        </div>

        {error && (
          <div className="mb-4 p-3 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl text-xs">
            {error}
          </div>
        )}

        <div className="space-y-6">
          <div className="bg-slate-950 p-4 rounded-2xl border border-slate-800 relative group min-h-[60px] flex items-center justify-between">
            {isGenerating ? (
              <div className="flex items-center gap-3 text-slate-500 text-sm animate-pulse">
                <div className="w-4 h-4 border-2 border-blue-500 border-t-transparent rounded-full animate-spin" />
                Generating...
              </div>
            ) : link ? (
              <>
                <div className="text-blue-400 font-mono text-sm truncate mr-10">{link}</div>
                <button 
                  onClick={copyToClipboard}
                  className="absolute right-3 p-2 bg-slate-800 hover:bg-slate-700 rounded-lg text-slate-200 transition-all active:scale-90"
                >
                  {copied ? <Icons.Check size={18} className="text-emerald-500" /> : <Icons.Copy size={18} />}
                </button>
              </>
            ) : (
              <span className="text-slate-600 italic text-sm">Waiting for generation...</span>
            )}
          </div>

          <div className="flex gap-2">
            <button 
              onClick={handleGenerateLink}
              className="flex-1 py-3 bg-blue-600 hover:bg-blue-500 text-white rounded-xl text-xs font-bold transition-all shadow-lg shadow-blue-600/20"
            >
              Regenerate
            </button>
            <button 
              onClick={copyToClipboard}
              className={`flex-1 py-3 rounded-xl text-xs font-bold transition-all ${copied ? 'bg-emerald-600 text-white' : 'bg-slate-800 text-slate-200'}`}
            >
              {copied ? 'Copied!' : 'Copy Link'}
            </button>
          </div>

          <div className="pt-4 border-t border-slate-800 space-y-4">
            <div className="flex justify-between items-center text-[10px] text-slate-500 font-bold uppercase tracking-widest">
              <span>Limit: 1 Person</span>
              <span>Expires: Never</span>
            </div>

            <div className="p-3 bg-slate-800/30 rounded-xl">
               <p className="text-[10px] text-slate-400 leading-relaxed italic">
                 "{aiDescription}"
               </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

