                  disabled={isAddingGroup || !botInfo}
                  className="px-5 py-3 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg shadow-emerald-600/10"
                >
                  {isAddingGroup ? '...' : '+ Sync'}
                </button>
              </div>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-4 p-3 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl text-[10px] font-bold uppercase tracking-wider">
             {error}
          </div>
        )}

        <div className="space-y-8">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
               <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-800">
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Active Bot</p>
                  <p className="text-sm font-bold text-white mt-1 truncate">{botInfo?.username || 'None'}</p>
               </div>
               <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-800">
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Groups</p>
                  <p className="text-sm font-bold text-white mt-1">{groups.length}</p>
               </div>
               {/* Install Card in Dashboard */}
               <button 
                  onClick={handleInstallApp}
                  className="bg-gradient-to-br from-blue-700 to-blue-900 p-4 rounded-2xl border border-blue-400/20 shadow-xl shadow-blue-950 text-left transition-all active:scale-95 group relative overflow-hidden"
               >
                  <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity">
                     <Icons.Download size={64} />
                  </div>
                  <div className="flex items-center justify-between mb-2">
                    <p className="text-[10px] font-bold text-blue-100 uppercase tracking-widest">Official TeleBridge</p>
                    <Icons.Download size={14} className="text-white animate-bounce" />
                  </div>
                  <p className="text-sm font-bold text-white">Get Official App</p>
                  <p className="text-[10px] text-blue-200/60 mt-0.5">Faster access from home screen</p>
               </button>
            </div>
          )}

          <section>
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-sm font-bold text-slate-400 uppercase tracking-widest">Managed Groups</h2>
              <Icons.Download size={14} className="text-blue-500 md:hidden animate-pulse cursor-pointer" onClick={handleInstallApp}/>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
              {filteredGroups.length > 0 ? (
                filteredGroups.map(group => (
                  <GroupCard 
                    key={group.id} 
                    group={group} 
                    onClick={(g) => setSelectedGroup(g)} 
                  />
                ))
              ) : (
                <div className="col-span-full py-16 text-center bg-slate-900/30 rounded-3xl border border-dashed border-slate-800">
                  <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-700">
                    <Icons.Users size={32} />
                  </div>
                  <h3 className="text-lg font-bold text-slate-400">Add Bot & Group</h3>
                  <p className="text-slate-600 text-xs max-w-[240px] mx-auto mt-2 leading-relaxed">
                    Set your token in Settings, add bot as admin to group, then sync using Chat ID.
                  </p>
                </div>
              )}
            </div>
          </section>
        </div>

        {activeTab === 'settings' && (
          <div className="max-w-2xl space-y-6">
            <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 md:p-8">
              <h2 className="text-xl font-bold mb-6">Bot Credentials</h2>
              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Bot Token (@BotFather)</label>
                  <input 
                    type="password" 
                    placeholder="123456789:ABCDEF..."
                    className="w-full bg-slate-950 border border-slate-800 px-4 py-3 rounded-xl text-sm font-mono text-blue-400 outline-none"
                    value={token}
                    onChange={(e) => setToken(e.target.value)}
                  />
                </div>
                <div className="flex flex-col sm:flex-row gap-3 pt-2">
                  <button 
                    onClick={() => handleVerify(token)}
                    disabled={isVerifying}
                    className="flex-1 px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white text-sm font-bold rounded-xl transition-all"
                  >
                    {isVerifying ? 'Verifying...' : 'Save & Verify'}
                  </button>
                  <button 
                    onClick={() => { setToken(''); setBotInfo(null); localStorage.removeItem('tg_bot_token'); }}
                    className="px-8 py-3 bg-slate-800 text-slate-400 text-sm font-bold rounded-xl hover:text-rose-400 transition-all"
                  >
                    Reset
                  </button>
                </div>
              </div>
            </div>

            {/* App Promotion in Settings */}
            <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 flex items-center justify-between">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-blue-600/20 rounded-xl flex items-center justify-center text-blue-500">
                  <Icons.Download size={24} />
                </div>
                <div>
                  <h3 className="font-bold text-white">TeleBridge App</h3>
                  <p className="text-xs text-slate-500">Fast, secure, and always on your screen.</p>
                </div>
              </div>
              <button 
                onClick={handleInstallApp}
                className="px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white text-xs font-bold rounded-xl transition-all"
              >
                Download Now
              </button>
            </div>
          </div>
        )}
      </main>

      {/* iOS Install Instruction Modal */}
      {showInstallGuide && (
        <div className="fixed inset-0 z-[110] flex items-end md:items-center justify-center p-4">
           <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-sm" onClick={() => setShowInstallGuide(false)} />
           <div className="relative bg-slate-900 w-full max-w-sm rounded-[32px] p-8 border border-slate-800 shadow-2xl animate-in fade-in slide-in-from-bottom-10">
              <div className="text-center">
                 <div className="w-20 h-20 bg-blue-600 rounded-[28%] flex items-center justify-center mx-auto mb-6 shadow-2xl shadow-blue-500/20">
                    <Icons.Download size={40} className="text-white" />
                 </div>
                 <h2 className="text-2xl font-black text-white mb-2">Install on iPhone</h2>
                 <p className="text-slate-400 text-sm mb-8">Add TeleBridge to your home screen for the best experience.</p>

                 <div className="space-y-6 text-left">
                    <div className="flex items-center gap-4">
                       <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center text-xs font-bold text-white">1</div>
                       <p className="text-slate-300 text-sm flex items-center gap-2">Tap the Share icon <span className="inline-block p-1 bg-slate-800 rounded">
                          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
                       </span> in Safari</p>
                    </div>
                    <div className="flex items-center gap-4">
                       <div className="w-8 h-8 rounded-full bg-slate-800 flex items-center justify-center text-xs font-bold text-white">2</div>
                       <p className="text-slate-300 text-sm">Scroll down and select <span className="font-bold text-white">"Add to Home Screen"</span></p>
                    </div>
                 </div>

                 <button 
                    onClick={() => setShowInstallGuide(false)}
                    className="w-full mt-10 py-4 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-2xl transition-all"
                 >
                    Got it
                 </button>
              </div>
           </div>
        </div>
      )}

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

