export const MOCK_GROUPS: any[] = [];

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar.tsx';
import GroupCard from './components/GroupCard.tsx';
import InviteModal from './components/InviteModal.tsx';
import { Icons } from './constants.tsx';
import { TelegramGroup } from './types.ts';
import { verifyBotToken, getChatDetails, TelegramBotInfo } from './services/telegramService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');

  // Real State
  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [groups, setGroups] = useState<TelegramGroup[]>(JSON.parse(localStorage.getItem('tg_groups') || '[]'));
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const handleAddGroup = async () => {
    if (!token || !newChatId) return;
    setIsAddingGroup(true);
    setError(null);
    try {
      const chat = await getChatDetails(token, newChatId);
      const newGroup: TelegramGroup = {
        id: chat.id.toString(),
        name: chat.title,
        memberCount: 0, 
        description: chat.description || 'Synced Group',
        category: 'Telegram',
        image: `https://picsum.photos/seed/${chat.id}/200`
      };

      const updatedGroups = [...groups.filter(g => g.id !== newGroup.id), newGroup];
      setGroups(updatedGroups);
      localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
      setNewChatId('');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAddingGroup(false);
    }
  };

  const filteredGroups = groups.filter(g => 
    g.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col md:flex-row font-sans selection:bg-blue-500/30">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />

      <main className="flex-1 md:ml-64 p-4 md:p-8 pb-24 md:pb-8">
        <header className="flex flex-col gap-4 mb-8">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <h1 className="text-2xl md:text-3xl font-black text-white tracking-tight capitalize">
                {activeTab}
              </h1>
            </div>

            <div className="flex items-center gap-3">
               <div className={`hidden md:flex items-center gap-2 px-3 py-1.5 bg-slate-900 border border-slate-800 rounded-full`}>
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
                 <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                   {botInfo ? `@${botInfo.username}` : 'Offline'}
                 </span>
               </div>
               <button onClick={() => handleVerify(token)} className="p-2 text-slate-500 hover:text-blue-500 transition-colors">
                  <Icons.Zap size={20} className={isVerifying ? 'animate-spin' : ''} />
               </button>
            </div>
          </div>

          {(activeTab === 'dashboard' || activeTab === 'groups') && (
            <div className="flex flex-col md:flex-row items-center gap-3">
              <div className="relative group w-full md:flex-1">
                <input 
                  type="text" 
                  placeholder="Search groups..." 
                  className="bg-slate-900 border border-slate-800 text-white pl-4 pr-4 py-3 rounded-xl w-full text-sm focus:ring-2 focus:ring-blue-500/30 outline-none transition-all"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex w-full md:w-auto gap-2">
                <input 
                  type="text" 
                  placeholder="Chat ID (-100...)" 
                  className="flex-1 md:w-48 bg-slate-900 border border-slate-800 px-4 py-3 rounded-xl text-xs focus:ring-2 focus:ring-emerald-500/30 outline-none"
                  value={newChatId}
                  onChange={(e) => setNewChatId(e.target.value)}
                />
                <button 
                  onClick={handleAddGroup}
                  disabled={isAddingGroup || !botInfo}
                  className="px-5 py-3 bg-emerald-600 hover:bg-emerald-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg shadow-emerald-600/10"
                >
                  {isAddingGroup ? '...' : '+ Sync'}
                </button>
              </div>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-4 p-3 bg-rose-500/10 border border-rose-500/20 text-rose-400 rounded-xl text-[10px] font-bold uppercase tracking-wider">
             {error}
          </div>
        )}

        <div className="space-y-8">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
               <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-800">
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Active Bot</p>
                  <p className="text-sm font-bold text-white mt-1 truncate">{botInfo?.username || 'None'}</p>
               </div>
               <div className="bg-slate-900/50 p-4 rounded-2xl border border-slate-800">
                  <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Groups</p>
                  <p className="text-sm font-bold text-white mt-1">{groups.length}</p>
               </div>
            </div>
          )}

          <section>
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-sm font-bold text-slate-400 uppercase tracking-widest">Managed Groups</h2>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3">
              {filteredGroups.length > 0 ? (
                filteredGroups.map(group => (
                  <GroupCard 
                    key={group.id} 
                    group={group} 
                    onClick={(g) => setSelectedGroup(g)} 
                  />
                ))
              ) : (
                <div className="col-span-full py-16 text-center bg-slate-900/30 rounded-3xl border border-dashed border-slate-800">
                  <div className="w-16 h-16 bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-4 text-slate-700">
                    <Icons.Users size={32} />
                  </div>
                  <h3 className="text-lg font-bold text-slate-400">Add Bot & Group</h3>
                  <p className="text-slate-600 text-xs max-w-[240px] mx-auto mt-2 leading-relaxed">
                    Set your token in Settings, add bot as admin to group, then sync using Chat ID.
                  </p>
                </div>
              )}
            </div>
          </section>
        </div>

        {activeTab === 'settings' && (
          <div className="max-w-2xl space-y-6">
            <div className="bg-slate-900 border border-slate-800 rounded-3xl p-6 md:p-8">
              <h2 className="text-xl font-bold mb-6">Bot Credentials</h2>
              <div className="space-y-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Bot Token (@BotFather)</label>
                  <input 
                    type="password" 
                    placeholder="123456789:ABCDEF..."
                    className="w-full bg-slate-950 border border-slate-800 px-4 py-3 rounded-xl text-sm font-mono text-blue-400 outline-none"
                    value={token}
                    onChange={(e) => setToken(e.target.value)}
                  />
                </div>
                <div className="flex flex-col sm:flex-row gap-3 pt-2">
                  <button 
                    onClick={() => handleVerify(token)}
                    disabled={isVerifying}
                    className="flex-1 px-8 py-3 bg-blue-600 hover:bg-blue-500 text-white text-sm font-bold rounded-xl transition-all"
                  >
                    {isVerifying ? 'Verifying...' : 'Save & Verify'}
                  </button>
                  <button 
                    onClick={() => { setToken(''); setBotInfo(null); localStorage.removeItem('tg_bot_token'); }}
                    className="px-8 py-3 bg-slate-800 text-slate-400 text-sm font-bold rounded-xl hover:text-rose-400 transition-all"
                  >
                    Reset
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

export default App;

