import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar.tsx';
import GroupCard from './components/GroupCard.tsx';
import InviteModal from './components/InviteModal.tsx';
import { Icons } from './constants.tsx';
import { TelegramGroup } from './types.ts';
import { verifyBotToken, getChatDetails, TelegramBotInfo } from './services/telegramService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [theme, setTheme] = useState<'light' | 'dark'>(
    (localStorage.getItem('theme') as 'light' | 'dark') || 'dark'
  );

  // Real State
  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [groups, setGroups] = useState<TelegramGroup[]>(JSON.parse(localStorage.getItem('tg_groups') || '[]'));
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
      root.classList.remove('light');
    } else {
      root.classList.add('light');
      root.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));
  };

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const handleAddGroup = async () => {
    if (!token || !newChatId) return;
    setIsAddingGroup(true);
    setError(null);
    try {
      const chat = await getChatDetails(token, newChatId);
      const newGroup: TelegramGroup = {
        id: chat.id.toString(),
        name: chat.title,
        memberCount: 0, 
        description: chat.description || 'Synced Group',
        category: 'Telegram',
        image: `https://picsum.photos/seed/${chat.id}/200`
      };

      const updatedGroups = [...groups.filter(g => g.id !== newGroup.id), newGroup];
      setGroups(updatedGroups);
      localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
      setNewChatId('');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAddingGroup(false);
    }
  };

  const filteredGroups = groups.filter(g => 
    g.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans selection:bg-blue-500/30 transition-colors duration-300">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        theme={theme} 
        toggleTheme={toggleTheme} 
      />

      <main className="flex-1 md:ml-64 p-4 md:p-10 pb-24 md:pb-8">
        <header className="flex flex-col gap-6 mb-10">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[10px] font-extrabold text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em] mb-1">Administrator Portal</p>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">
                {activeTab}
              </h1>
            </div>

            <div className="flex items-center gap-3">
               <div className={`hidden md:flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm`}>
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
                 <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">
                   {botInfo ? `@${botInfo.username}` : 'Offline'}
                 </span>
               </div>
               <button onClick={() => handleVerify(token)} className="p-2.5 text-slate-400 hover:text-blue-500 transition-all hover:scale-110 active:scale-95 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800">
                  <Icons.Zap size={20} className={isVerifying ? 'animate-spin text-blue-500' : ''} />
               </button>
            </div>
          </div>

          {(activeTab === 'dashboard' || activeTab === 'groups') && (
            <div className="flex flex-col md:flex-row items-center gap-4 p-2 bg-slate-200/50 dark:bg-slate-900/50 rounded-2xl border border-slate-300/30 dark:border-slate-800/50">
              <div className="relative group w-full md:flex-1">
                <input 
                  type="text" 
                  placeholder="Filter groups..." 
                  className="bg-transparent text-slate-900 dark:text-white pl-4 pr-4 py-3 rounded-xl w-full text-sm outline-none placeholder-slate-400 dark:placeholder-slate-500"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex w-full md:w-auto gap-2">
                <input 
                  type="text" 
                  placeholder="Chat ID (-100...)" 
                  className="flex-1 md:w-48 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-4 py-3 rounded-xl text-xs outline-none focus:ring-2 focus:ring-blue-500/20"
                  value={newChatId}
                  onChange={(e) => setNewChatId(e.target.value)}
                />
                <button 
                  onClick={handleAddGroup}
                  disabled={isAddingGroup || !botInfo}
                  className="px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg shadow-blue-600/20 active:scale-95 whitespace-nowrap"
                >
                  {isAddingGroup ? 'Connecting...' : 'Connect Group'}
                </button>
              </div>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/5 border border-rose-500/20 text-rose-600 dark:text-rose-400 rounded-2xl text-[11px] font-bold uppercase tracking-wider flex items-center gap-3">
             <div className="w-2 h-2 rounded-full bg-rose-500" />
             {error}
          </div>
        )}

        <div className="space-y-12">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                  <p className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-2">Bot Profile</p>
                  <p className="text-lg font-black text-slate-900 dark:text-white truncate">{botInfo?.username ? `@${botInfo.username}` : 'Not Connected'}</p>
                  <div className="mt-4 flex items-center gap-2">
                    <div className={`px-2 py-1 rounded text-[10px] font-bold uppercase ${botInfo ? 'bg-emerald-500/10 text-emerald-600' : 'bg-slate-200 dark:bg-slate-800 text-slate-400'}`}>
                      {botInfo ? 'Ready' : 'Setup Required'}
                    </div>
                  </div>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                  <p className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-2">Managed Hubs</p>
                  <p className="text-3xl font-black text-slate-900 dark:text-white">{groups.length}</p>
                  <p className="mt-2 text-xs text-slate-500">Connected telegram groups</p>
               </div>
               <div className="hidden lg:block bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl border border-blue-400/20 shadow-xl shadow-blue-500/10">
                  <p className="text-[10px] font-extrabold text-blue-100 uppercase tracking-widest mb-2">AI Status</p>
                  <p className="text-lg font-bold text-white">Gemini 3 Pro Active</p>
                  <p className="mt-2 text-xs text-blue-100/70">Generating secure insights</p>
               </div>
            </div>
          )}

          <section>
            <div className="flex items-center justify-between mb-8">
              <h2 className="text-xs font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">Group Directory</h2>
              <div className="h-px flex-1 mx-6 bg-slate-200 dark:bg-slate-800 hidden md:block"></div>
              <span className="text-[10px] font-bold text-slate-400">{filteredGroups.length} total</span>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
              {filteredGroups.length > 0 ? (
                filteredGroups.map(group => (
                  <GroupCard 
                    key={group.id} 
                    group={group} 
                    onClick={(g) => setSelectedGroup(g)} 
                  />
                ))
              ) : (
                <div className="col-span-full py-24 text-center bg-white dark:bg-slate-900/20 rounded-[2.5rem] border-2 border-dashed border-slate-200 dark:border-slate-800/50">
                  <div className="w-20 h-20 bg-slate-100 dark:bg-slate-800/50 rounded-full flex items-center justify-center mx-auto mb-6 text-slate-400 dark:text-slate-700">
                    <Icons.Users size={40} />
                  </div>
                  <h3 className="text-xl font-bold text-slate-800 dark:text-slate-200">No groups connected</h3>
                  <p className="text-slate-500 text-sm max-w-[280px] mx-auto mt-2 leading-relaxed font-medium">
                    Link your first telegram group by providing its Chat ID in the sync bar above.
                  </p>
                </div>
              )}
            </div>
          </section>
        </div>

        {activeTab === 'settings' && (
          <div className="max-w-3xl space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl shadow-slate-200/50 dark:shadow-none">
              <div className="flex items-center gap-4 mb-10">
                <div className="w-12 h-12 bg-blue-600/10 rounded-2xl flex items-center justify-center text-blue-600">
                  <Icons.Zap size={24} />
                </div>
                <div>
                  <h2 className="text-2xl font-black text-slate-900 dark:text-white">Bot Integration</h2>
                  <p className="text-sm text-slate-500">Configure your secure API credentials</p>
                </div>
              </div>

              <div className="space-y-8">
                <div className="space-y-3">
                  <label className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Bot Token (from @BotFather)</label>
                  <input 
                    type="password" 
                    placeholder="123456789:ABCDEF..."
                    className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-6 py-4 rounded-2xl text-sm font-mono text-blue-600 dark:text-blue-400 outline-none focus:ring-2 focus:ring-blue-500/20 transition-all"
                    value={token}
                    onChange={(e) => setToken(e.target.value)}
                  />
                  <p className="text-[10px] text-slate-500 font-medium">Token is encrypted and stored locally in your browser.</p>
                </div>

                <div className="flex flex-col sm:flex-row gap-4 pt-4">
                  <button 
                    onClick={() => handleVerify(token)}
                    disabled={isVerifying}
                    className="flex-1 px-8 py-4 bg-blue-600 hover:bg-blue-500 text-white text-sm font-bold rounded-2xl transition-all shadow-lg shadow-blue-600/30 active:scale-[0.98]"
                  >
                    {isVerifying ? 'Authenticating...' : 'Save and Initialize'}
                  </button>
                  <button 
                    onClick={() => { setToken(''); setBotInfo(null); localStorage.removeItem('tg_bot_token'); }}
                    className="px-8 py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 text-sm font-bold rounded-2xl hover:bg-slate-200 dark:hover:bg-slate-700 hover:text-rose-500 transition-all active:scale-[0.98]"
                  >
                    Clear Credentials
                  </button>
                </div>
              </div>
            </div>

            <div className="bg-blue-600/5 dark:bg-blue-500/5 border border-blue-500/10 rounded-[2rem] p-6 flex items-start gap-4">
               <Icons.Check className="text-blue-600 mt-1 flex-shrink-0" size={18} />
               <div>
                  <h4 className="text-sm font-bold text-slate-900 dark:text-white mb-1">Security First</h4>
                  <p className="text-xs text-slate-500 leading-relaxed">TeleBridge uses client-side API requests. Your bot tokens never leave your browser or hit any 3rd-party servers other than official Telegram endpoints.</p>
               </div>
            </div>
          </div>
        )}
      </main>

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

export default App;

