                                <td className="px-8 py-5 text-xs text-slate-400 font-mono">
                                   {new Date(event.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                </td>
                                <td className="px-8 py-5 text-right">
                                   <button 
                                      onClick={() => handleKick(event.chatId, event.userId, idx)}
                                      className="p-2.5 bg-rose-500/10 hover:bg-rose-500 text-rose-500 hover:text-white rounded-xl transition-all active:scale-90"
                                      title="Kick User"
                                   >
                                      <Icons.Trash size={16} />
                                   </button>
                                </td>
                             </tr>
                          )) : (
                             <tr>
                                <td colSpan={4} className="px-8 py-20 text-center text-slate-400 text-sm font-medium">
                                   No join events recorded yet. Sync your bot and keep the app open to track activity.
                                </td>
                             </tr>
                          )}
                       </tbody>
                    </table>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="max-w-3xl space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <div className="flex items-start justify-between mb-10">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-blue-600/10 rounded-2xl flex items-center justify-center text-blue-600">
                      <Icons.Zap size={24} />
                    </div>
                    <div>
                      <h2 className="text-2xl font-black text-slate-900 dark:text-white">API Credentials</h2>
                      <p className="text-sm text-slate-500">Secure BotFather connection</p>
                    </div>
                  </div>
                  <button onClick={() => setIsLocked(!isLocked)} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${ isLocked ? 'bg-rose-500/10 text-rose-500' : 'bg-emerald-500/10 text-emerald-500' }`}>
                    <Icons.Check size={14} /> {isLocked ? 'Locked' : 'Unlocked'}
                  </button>
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Bot Token</label>
                    <input type="password" placeholder="123456789:ABCDEF..." disabled={isLocked} className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-6 py-4 rounded-2xl text-sm font-mono text-blue-600 dark:text-blue-400 outline-none focus:ring-2 focus:ring-blue-500/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed" value={token} onChange={(e) => setToken(e.target.value)} />
                </div>
                {!isLocked && (
                    <div className="flex flex-col sm:flex-row gap-4 pt-6 animate-in slide-in-from-top-2">
                      <button onClick={() => handleVerify(token)} disabled={isVerifying} className="flex-1 px-8 py-4 bg-blue-600 hover:bg-blue-500 text-white text-sm font-bold rounded-2xl transition-all active:scale-[0.98]">
                        {isVerifying ? 'Authenticating...' : 'Validate and Save'}
                      </button>
                      <button onClick={() => { setToken(''); setBotInfo(null); localStorage.removeItem('tg_bot_token'); }} className="px-8 py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 text-sm font-bold rounded-2xl hover:text-rose-500 transition-all">
                        Clear Credentials
                      </button>
                    </div>
                )}
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2">Synced Groups Directory</h2>
                <p className="text-sm text-slate-500 mb-8">Reference your synced Chat IDs.</p>
                <div className="space-y-3 max-h-96 overflow-y-auto pr-2">
                  {sortedGroups.map(group => (
                    <div key={group.id} className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                      <div className="flex items-center gap-4 min-w-0">
                        <img src={group.image} alt={group.name} className="w-10 h-10 rounded-lg object-cover flex-shrink-0" />
                        <div className="min-w-0">
                          <p className="text-sm font-bold text-slate-900 dark:text-white break-words">{group.name}</p>
                          <p className="text-xs font-mono text-slate-400">{group.id}</p>
                        </div>
                      </div>
                      <button onClick={() => copyToClipboard(group.id)} className="p-3 bg-white dark:bg-slate-700 rounded-xl text-slate-400 hover:text-blue-500 transition-all active:scale-90 shadow-sm">
                        <Icons.Copy size={16} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2">Export / Import</h2>
                <div className="flex flex-col sm:flex-row gap-4 mt-6">
                  <button onClick={handleExport} className="flex-1 flex items-center justify-center gap-3 px-8 py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-200 text-sm font-bold rounded-2xl transition-all">
                    <Icons.DownloadCloud size={18} /> Export Data
                  </button>
                  <button onClick={() => importFileRef.current?.click()} className="flex-1 flex items-center justify-center gap-3 px-8 py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-200 text-sm font-bold rounded-2xl transition-all">
                    <Icons.UploadCloud size={18} /> Import Data
                  </button>
                  <input type="file" ref={importFileRef} onChange={handleImport} accept=".json" className="hidden" />
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar.tsx';
import GroupCard from './components/GroupCard.tsx';
import InviteModal from './components/InviteModal.tsx';
import { Icons } from './constants.tsx';
import { TelegramGroup, JoinEvent } from './types.ts';
import { verifyBotToken, getChatDetails, TelegramBotInfo, getChatMemberCount, getRecentUpdates, kickChatMember } from './services/telegramService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    if (saved) return saved as 'light' | 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  // Real State
  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isLocked, setIsLocked] = useState(() => localStorage.getItem('tg_token_locked') === 'true');
  const [groups, setGroups] = useState<TelegramGroup[]>(() => {
    const saved = localStorage.getItem('tg_groups');
    return saved ? JSON.parse(saved) : [];
  });
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [totalMembers, setTotalMembers] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [joinEvents, setJoinEvents] = useState<JoinEvent[]>(() => {
    const saved = localStorage.getItem('tg_join_events');
    return saved ? JSON.parse(saved) : [];
  });
  const [lastUpdateId, setLastUpdateId] = useState(0);
  const [pendingKick, setPendingKick] = useState<string | null>(null); // To handle confirm kick

  const importFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  useEffect(() => {
    const total = groups.reduce((sum, group) => sum + (group.memberCount || 0), 0);
    setTotalMembers(total);
  }, [groups]);

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('tg_token_locked', isLocked.toString());
  }, [isLocked]);

  useEffect(() => {
    localStorage.setItem('tg_join_events', JSON.stringify(joinEvents));
  }, [joinEvents]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));
  };

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
      refreshMemberCounts(testToken);
      pollUpdates(testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const pollUpdates = async (currentToken: string) => {
    try {
      const updates = await getRecentUpdates(currentToken, lastUpdateId + 1);
      if (updates.length > 0) {
        const newEvents: JoinEvent[] = [];
        let maxId = lastUpdateId;

        updates.forEach(update => {
          maxId = Math.max(maxId, update.update_id);
          const memberUpdate = update.chat_member;
          if (memberUpdate && memberUpdate.new_chat_member?.status === 'member' && memberUpdate.old_chat_member?.status === 'left') {
            newEvents.push({
              userId: memberUpdate.new_chat_member.user.id,
              userName: memberUpdate.new_chat_member.user.first_name + (memberUpdate.new_chat_member.user.last_name ? ` ${memberUpdate.new_chat_member.user.last_name}` : ''),
              chatId: memberUpdate.chat.id,
              chatTitle: memberUpdate.chat.title,
              timestamp: memberUpdate.date ? memberUpdate.date * 1000 : Date.now()
            });
          }
        });

        if (newEvents.length > 0) {
          // Merge and avoid duplicates by checking userId and timestamp
          setJoinEvents(prev => {
            const merged = [...newEvents, ...prev];
            const unique = merged.filter((v, i, a) => a.findIndex(t => (t.userId === v.userId && t.timestamp === v.timestamp)) === i);
            return unique.slice(0, 500); // Increased history limit
          });
        }
        setLastUpdateId(maxId);
      }
    } catch (e) {
      console.error("Polling error", e);
    }
  };

  const handleAddGroup = async () => {
    if (!token || !newChatId) return;
    setIsAddingGroup(true);
    setError(null);
    try {
      const chat = await getChatDetails(token, newChatId);
      const memberCount = await getChatMemberCount(token, newChatId);
      const newGroup: TelegramGroup = {
        id: chat.id.toString(),
        name: chat.title,
        memberCount: memberCount, 
        description: chat.description || 'Synced Group',
        category: 'Telegram',
        image: `https://picsum.photos/seed/${chat.id}/200`,
        lastInteraction: Date.now()
      };

      const updatedGroups = [newGroup, ...groups.filter(g => g.id !== newGroup.id)];
      setGroups(updatedGroups);
      localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
      setNewChatId('');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAddingGroup(false);
    }
  };

  const handleKickConfirm = (eventId: string) => {
    if (pendingKick === eventId) {
      setPendingKick(null); // Cancel if clicked again
    } else {
      setPendingKick(eventId);
    }
  };

  const handleExecuteKick = async (chatId: number, userId: number, eventId: string) => {
    if (!token) return;
    try {
      await kickChatMember(token, chatId, userId);
      setJoinEvents(prev => prev.filter(e => `${e.userId}-${e.timestamp}` !== eventId));
      setPendingKick(null);
    } catch (err: any) {
      alert(`Error: ${err.message}`);
      setPendingKick(null);
    }
  };

  const updateGroupUsage = (groupId: string) => {
    const updated = groups.map(g => 
      g.id === groupId ? { ...g, lastInteraction: Date.now() } : g
    );
    setGroups(updated);
    localStorage.setItem('tg_groups', JSON.stringify(updated));
  };

  const refreshMemberCounts = async (currentToken: string) => {
    if (!currentToken || groups.length === 0) return;
    setIsRefreshing(true);
    const updatedGroupsPromises = groups.map(async (group) => {
        try {
            const memberCount = await getChatMemberCount(currentToken, group.id);
            return { ...group, memberCount };
        } catch (e) {
            console.error(`Failed to update member count for ${group.name}`, e);
            return group; 
        }
    });
    const updatedGroups = await Promise.all(updatedGroupsPromises);
    setGroups(updatedGroups);
    localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
    setIsRefreshing(false);
  };

  const joinsToday = useMemo(() => {
    const startOfDay = new Date().setHours(0, 0, 0, 0);
    return joinEvents.filter(e => e.timestamp >= startOfDay).length;
  }, [joinEvents]);

  const sortedGroups = useMemo(() => {
    return [...groups].sort((a, b) => (b.lastInteraction || 0) - (a.lastInteraction || 0));
  }, [groups]);

  const filteredGroups = sortedGroups.filter(g => 
    g.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    g.id.includes(searchQuery)
  );

  const groupedJoinEvents = useMemo(() => {
    const groups: { [date: string]: JoinEvent[] } = {};
    const today = new Date().toLocaleDateString();
    const yesterday = new Date(Date.now() - 86400000).toLocaleDateString();

    joinEvents.forEach(event => {
      const date = new Date(event.timestamp).toLocaleDateString();
      let label = date;
      if (date === today) label = "Today";
      else if (date === yesterday) label = "Yesterday";

      if (!groups[label]) groups[label] = [];
      groups[label].push(event);
    });
    return groups;
  }, [joinEvents]);

  const handleExport = () => {
    const config = { token, groups, isLocked, joinEvents };
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(config, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "telebridge-config.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const text = e.target?.result;
            if (typeof text !== 'string') throw new Error("Invalid file content");
            const config = JSON.parse(text);

            if (window.confirm("Overwrite current configuration? This cannot be undone.")) {
                if (config.token && typeof config.token === 'string') {
                    setToken(config.token);
                    localStorage.setItem('tg_bot_token', config.token);
                    handleVerify(config.token);
                }
                if (config.groups && Array.isArray(config.groups)) {
                    setGroups(config.groups);
                    localStorage.setItem('tg_groups', JSON.stringify(config.groups));
                }
                if (config.joinEvents && Array.isArray(config.joinEvents)) {
                    setJoinEvents(config.joinEvents);
                }
                if (typeof config.isLocked === 'boolean') {
                    setIsLocked(config.isLocked);
                    localStorage.setItem('tg_token_locked', config.isLocked.toString());
                }
            }
        } catch (error) {
            setError("Failed to parse configuration file.");
        } finally {
            if(event.target) event.target.value = '';
        }
    };
    reader.readAsText(file);
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans selection:bg-blue-500/30 transition-colors duration-300">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        theme={theme} 
        toggleTheme={toggleTheme} 
      />

      <main className="flex-1 md:ml-64 p-4 md:p-10 pb-24 md:pb-8">
        <header className="flex flex-col gap-6 mb-10">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[10px] font-extrabold text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em] mb-1">Administrator Portal</p>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">
                {activeTab}
              </h1>
            </div>

            <div className="flex items-center gap-2 md:gap-3">
               <button 
                 onClick={toggleTheme}
                 className="p-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-500 dark:text-slate-400 hover:text-blue-500 transition-all active:scale-95 shadow-sm"
                 title="Toggle Theme"
               >
                 {theme === 'dark' ? <Icons.Sun size={20} /> : <Icons.Moon size={20} />}
               </button>
               <div className={`hidden md:flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm`}>
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
                 <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">
                   {botInfo ? `@${botInfo.username}` : 'Offline'}
                 </span>
               </div>
               <button onClick={() => handleVerify(token)} className="p-2.5 text-slate-400 hover:text-blue-500 transition-all hover:scale-110 active:scale-95 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800">
                  <Icons.Zap size={20} className={isVerifying ? 'animate-spin text-blue-500' : ''} />
               </button>
            </div>
          </div>

          {(activeTab === 'dashboard' || activeTab === 'groups') && (
            <div className="flex flex-col md:flex-row items-center gap-4 p-2 bg-slate-200/50 dark:bg-slate-900/50 rounded-2xl border border-slate-300/30 dark:border-slate-800/50">
              <div className="relative group w-full md:flex-1">
                <Icons.Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600 pointer-events-none" />
                <input 
                  type="text" 
                  placeholder="Filter by name or Chat ID..." 
                  className="bg-transparent text-slate-900 dark:text-white pl-10 pr-4 py-3 rounded-xl w-full text-sm outline-none placeholder-slate-400 dark:placeholder-slate-500"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex w-full md:w-auto gap-2">
                <input 
                  type="text" 
                  placeholder="Chat ID (-100...)" 
                  className="flex-1 md:w-48 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-4 py-3 rounded-xl text-xs outline-none focus:ring-2 focus:ring-blue-500/20"
                  value={newChatId}
                  onChange={(e) => setNewChatId(e.target.value)}
                />
                <button 
                  onClick={handleAddGroup}
                  disabled={isAddingGroup || !botInfo}
                  className="px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg shadow-blue-600/20 active:scale-95 whitespace-nowrap"
                >
                  {isAddingGroup ? 'Connecting...' : 'Sync Group'}
                </button>
              </div>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/5 border border-rose-500/20 text-rose-600 dark:text-rose-400 rounded-2xl text-[11px] font-bold uppercase tracking-wider flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
             <div className="w-2 h-2 rounded-full bg-rose-500" />
             {error}
          </div>
        )}

        <div className="space-y-12 animate-in fade-in duration-500">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                  <p className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-2">Active Bot</p>
                  <p className="text-lg font-black text-slate-900 dark:text-white truncate">{botInfo?.username ? `@${botInfo.username}` : 'Not Connected'}</p>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                  <p className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-2">Total Hubs</p>
                  <p className="text-3xl font-black text-slate-900 dark:text-white">{groups.length}</p>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm relative">
                  <p className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest mb-2">Total Members</p>
                  <p className="text-3xl font-black text-slate-900 dark:text-white">{totalMembers.toLocaleString()}</p>
                  <button onClick={() => refreshMemberCounts(token)} disabled={isRefreshing || !botInfo} className="absolute top-4 right-4 p-2 text-slate-400 hover:text-blue-500 transition-all disabled:opacity-30">
                    <Icons.Refresh size={16} className={isRefreshing ? 'animate-spin' : ''} />
                  </button>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                  <p className="text-[10px] font-extrabold text-blue-600 dark:text-blue-400 uppercase tracking-widest mb-2">Joins Today</p>
                  <p className="text-3xl font-black text-slate-900 dark:text-white">{joinsToday}</p>
               </div>
            </div>
          )}

          {activeTab === 'groups' && (
            <section>
              <div className="flex items-center justify-between mb-8">
                <h2 className="text-xs font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">Group Directory</h2>
                <span className="text-[10px] font-bold text-slate-400">{filteredGroups.length} synced</span>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {filteredGroups.map((group, idx) => (
                  <GroupCard key={group.id} group={group} isPriority={idx === 0 && !!group.lastInteraction} onClick={(g) => { updateGroupUsage(g.id); setSelectedGroup(g); }} />
                ))}
              </div>
            </section>
          )}

          {activeTab === 'analysis' && (
            <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="bg-blue-600 p-8 rounded-[2.5rem] text-white shadow-xl shadow-blue-500/20">
                   <p className="text-[10px] font-black uppercase tracking-widest mb-2 opacity-70">Daily Pulse</p>
                   <p className="text-4xl font-black">{joinsToday}</p>
                   <p className="text-sm font-medium mt-2 opacity-90">Total joins recorded today across all synced groups.</p>
                </div>
                <div className="bg-slate-900 p-8 rounded-[2.5rem] border border-slate-800 text-white shadow-xl">
                   <p className="text-[10px] font-black uppercase tracking-widest mb-2 text-slate-500">System Monitoring</p>
                   <div className="flex items-center gap-4 mt-2">
                     <button onClick={() => pollUpdates(token)} disabled={!botInfo} className="px-6 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl text-xs font-bold transition-all active:scale-95 flex items-center gap-2">
                        <Icons.Refresh size={14} /> Scan for New Joins
                     </button>
                   </div>
                   <p className="text-[10px] text-slate-500 mt-4 uppercase font-bold">Scanning mode: Active Polling</p>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] overflow-hidden shadow-xl">
                 <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
                    <h2 className="text-xl font-black text-slate-900 dark:text-white">Recent Join Activity</h2>
                    <span className="px-3 py-1 bg-emerald-500/10 text-emerald-500 text-[10px] font-black uppercase rounded-full">Real-time Log</span>
                 </div>

                 <div className="overflow-x-auto">
                    <table className="w-full text-left">
                       <thead>
                          <tr className="bg-slate-50 dark:bg-slate-950/50 border-b border-slate-100 dark:border-slate-800">
                             <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">User Name</th>
                             <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Target Hub</th>
                             <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest">Join Time</th>
                             <th className="px-8 py-4 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Actions</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                          {Object.keys(groupedJoinEvents).length > 0 ? Object.entries(groupedJoinEvents).map(([date, events]) => (
                            <React.Fragment key={date}>
                              <tr className="bg-slate-100/50 dark:bg-slate-800/30">
                                <td colSpan={4} className="px-8 py-3 text-[10px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-[0.2em]">
                                  {date}
                                </td>
                              </tr>
                              {events.map((event) => {
                                const eventId = `${event.userId}-${event.timestamp}`;
                                return (
                                  <tr key={eventId} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                    <td className="px-8 py-5">
                                      <div className="flex items-center gap-3">
                                          <div className="w-8 h-8 bg-blue-600/10 rounded-full flex items-center justify-center text-blue-600 font-bold text-xs uppercase">
                                            {event.userName.charAt(0)}
                                          </div>
                                          <span className="text-sm font-bold text-slate-900 dark:text-white">{event.userName}</span>
                                      </div>
                                    </td>
                                    <td className="px-8 py-5 text-sm text-slate-500 dark:text-slate-400 font-medium">
                                      {event.chatTitle}
                                    </td>
                                    <td className="px-8 py-5 text-xs text-slate-400 font-mono">
                                      {new Date(event.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                    </td>
                                    <td className="px-8 py-5 text-right">
                                      {pendingKick === eventId ? (
                                        <div className="flex items-center justify-end gap-2 animate-in slide-in-from-right-2">
                                          <button 
                                            onClick={() => handleExecuteKick(event.chatId, event.userId, eventId)}
                                            className="px-3 py-1.5 bg-rose-600 text-white text-[10px] font-black uppercase rounded-lg shadow-lg shadow-rose-500/20 active:scale-90"
                                          >
                                            Confirm
                                          </button>
                                          <button 
                                            onClick={() => setPendingKick(null)}
                                            className="px-3 py-1.5 bg-slate-100 dark:bg-slate-800 text-slate-500 text-[10px] font-black uppercase rounded-lg active:scale-90"
                                          >
                                            Cancel
                                          </button>
                                        </div>
                                      ) : (
                                        <button 
                                          onClick={() => handleKickConfirm(eventId)}
                                          className="p-2.5 bg-rose-500/10 hover:bg-rose-500 text-rose-500 hover:text-white rounded-xl transition-all active:scale-90"
                                          title="Kick User"
                                        >
                                          <Icons.Trash size={16} />
                                        </button>
                                      )}
                                    </td>
                                  </tr>
                                );
                              })}
                            </React.Fragment>
                          )) : (
                             <tr>
                                <td colSpan={4} className="px-8 py-20 text-center text-slate-400 text-sm font-medium">
                                   No join events recorded yet. Sync your bot and keep the app open to track activity.
                                </td>
                             </tr>
                          )}
                       </tbody>
                    </table>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="max-w-3xl space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <div className="flex items-start justify-between mb-10">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-blue-600/10 rounded-2xl flex items-center justify-center text-blue-600">
                      <Icons.Zap size={24} />
                    </div>
                    <div>
                      <h2 className="text-2xl font-black text-slate-900 dark:text-white">API Credentials</h2>
                      <p className="text-sm text-slate-500">Secure BotFather connection</p>
                    </div>
                  </div>
                  <button onClick={() => setIsLocked(!isLocked)} className={`flex items-center gap-2 px-3 py-2 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all ${ isLocked ? 'bg-rose-500/10 text-rose-500' : 'bg-emerald-500/10 text-emerald-500' }`}>
                    <Icons.Check size={14} /> {isLocked ? 'Locked' : 'Unlocked'}
                  </button>
                </div>
                <div className="space-y-3">
                    <label className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Bot Token</label>
                    <input type="password" placeholder="123456789:ABCDEF..." disabled={isLocked} className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-6 py-4 rounded-2xl text-sm font-mono text-blue-600 dark:text-blue-400 outline-none focus:ring-2 focus:ring-blue-500/20 transition-all disabled:opacity-50 disabled:cursor-not-allowed" value={token} onChange={(e) => setToken(e.target.value)} />
                </div>
                {!isLocked && (
                    <div className="flex flex-col sm:flex-row gap-4 pt-6 animate-in slide-in-from-top-2">
                      <button onClick={() => handleVerify(token)} disabled={isVerifying} className="flex-1 px-8 py-4 bg-blue-600 hover:bg-blue-500 text-white text-sm font-bold rounded-2xl transition-all active:scale-[0.98]">
                        {isVerifying ? 'Authenticating...' : 'Validate and Save'}
                      </button>
                      <button onClick={() => { setToken(''); setBotInfo(null); localStorage.removeItem('tg_bot_token'); }} className="px-8 py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 text-sm font-bold rounded-2xl hover:text-rose-500 transition-all">
                        Clear Credentials
                      </button>
                    </div>
                )}
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2">Synced Groups Directory</h2>
                <p className="text-sm text-slate-500 mb-8">Reference your synced Chat IDs.</p>
                <div className="space-y-3 max-h-96 overflow-y-auto pr-2">
                  {sortedGroups.map(group => (
                    <div key={group.id} className="flex items-center justify-between p-4 bg-slate-50 dark:bg-slate-800/50 rounded-2xl">
                      <div className="flex items-center gap-4 min-w-0">
                        <img src={group.image} alt={group.name} className="w-10 h-10 rounded-lg object-cover flex-shrink-0" />
                        <div className="min-w-0">
                          <p className="text-sm font-bold text-slate-900 dark:text-white break-words">{group.name}</p>
                          <p className="text-xs font-mono text-slate-400">{group.id}</p>
                        </div>
                      </div>
                      <button onClick={() => copyToClipboard(group.id)} className="p-3 bg-white dark:bg-slate-700 rounded-xl text-slate-400 hover:text-blue-500 transition-all active:scale-90 shadow-sm">
                        <Icons.Copy size={16} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <h2 className="text-2xl font-black text-slate-900 dark:text-white mb-2">Export / Import</h2>
                <div className="flex flex-col sm:flex-row gap-4 mt-6">
                  <button onClick={handleExport} className="flex-1 flex items-center justify-center gap-3 px-8 py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-200 text-sm font-bold rounded-2xl transition-all">
                    <Icons.DownloadCloud size={18} /> Export Data
                  </button>
                  <button onClick={() => importFileRef.current?.click()} className="flex-1 flex items-center justify-center gap-3 px-8 py-4 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-200 text-sm font-bold rounded-2xl transition-all">
                    <Icons.UploadCloud size={18} /> Import Data
                  </button>
                  <input type="file" ref={importFileRef} onChange={handleImport} accept=".json" className="hidden" />
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar.tsx';
import GroupCard from './components/GroupCard.tsx';
import InviteModal from './components/InviteModal.tsx';
import { Icons } from './constants.tsx';
import { TelegramGroup, JoinEvent } from './types.ts';
import { verifyBotToken, getChatDetails, TelegramBotInfo, getChatMemberCount, getRecentUpdates, kickChatMember } from './services/telegramService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    if (saved) return saved as 'light' | 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  // Real State
  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isLocked, setIsLocked] = useState(() => localStorage.getItem('tg_token_locked') === 'true');
  const [groups, setGroups] = useState<TelegramGroup[]>(() => {
    const saved = localStorage.getItem('tg_groups');
    return saved ? JSON.parse(saved) : [];
  });
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [totalMembers, setTotalMembers] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [joinEvents, setJoinEvents] = useState<JoinEvent[]>(() => {
    const saved = localStorage.getItem('tg_join_events');
    return saved ? JSON.parse(saved) : [];
  });
  const [lastUpdateId, setLastUpdateId] = useState(0);
  const [pendingKick, setPendingKick] = useState<string | null>(null); // To handle confirm kick

  const importFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  useEffect(() => {
    const total = groups.reduce((sum, group) => sum + (group.memberCount || 0), 0);
    setTotalMembers(total);
  }, [groups]);

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('tg_token_locked', isLocked.toString());
  }, [isLocked]);

  useEffect(() => {
    localStorage.setItem('tg_join_events', JSON.stringify(joinEvents));
  }, [joinEvents]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));
  };

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
      refreshMemberCounts(testToken);
      pollUpdates(testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const pollUpdates = async (currentToken: string) => {
    try {
      const updates = await getRecentUpdates(currentToken, lastUpdateId + 1);
      if (updates.length > 0) {
        const newEvents: JoinEvent[] = [];
        let maxId = lastUpdateId;

        updates.forEach(update => {
          maxId = Math.max(maxId, update.update_id);
          const memberUpdate = update.chat_member;
          if (memberUpdate && memberUpdate.new_chat_member?.status === 'member' && memberUpdate.old_chat_member?.status === 'left') {
            newEvents.push({
              userId: memberUpdate.new_chat_member.user.id,
              userName: memberUpdate.new_chat_member.user.first_name + (memberUpdate.new_chat_member.user.last_name ? ` ${memberUpdate.new_chat_member.user.last_name}` : ''),
              chatId: memberUpdate.chat.id,
              chatTitle: memberUpdate.chat.title,
              timestamp: memberUpdate.date ? memberUpdate.date * 1000 : Date.now()
            });
          }
        });

        if (newEvents.length > 0) {
          // Merge and avoid duplicates by checking userId and timestamp
          setJoinEvents(prev => {
            const merged = [...newEvents, ...prev];
            const unique = merged.filter((v, i, a) => a.findIndex(t => (t.userId === v.userId && t.timestamp === v.timestamp)) === i);
            return unique.slice(0, 500); // Increased history limit
          });
        }
        setLastUpdateId(maxId);
      }
    } catch (e) {
      console.error("Polling error", e);
    }
  };

  const handleAddGroup = async () => {
    if (!token || !newChatId) return;
    setIsAddingGroup(true);
    setError(null);
    try {
      const chat = await getChatDetails(token, newChatId);
      const memberCount = await getChatMemberCount(token, newChatId);
      const newGroup: TelegramGroup = {
        id: chat.id.toString(),
        name: chat.title,
        memberCount: memberCount, 
        description: chat.description || 'Synced Group',
        category: 'Telegram',
        image: `https://picsum.photos/seed/${chat.id}/200`,
        lastInteraction: Date.now()
      };

      const updatedGroups = [newGroup, ...groups.filter(g => g.id !== newGroup.id)];
      setGroups(updatedGroups);
      localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
      setNewChatId('');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAddingGroup(false);
    }
  };

  const handleKickConfirm = (eventId: string) => {
    if (pendingKick === eventId) {
      setPendingKick(null); // Cancel if clicked again
    } else {
      setPendingKick(eventId);
    }
  };

  const handleExecuteKick = async (chatId: number, userId: number, eventId: string) => {
    if (!token) return;
    try {
      await kickChatMember(token, chatId, userId);
      setJoinEvents(prev => prev.filter(e => `${e.userId}-${e.timestamp}` !== eventId));
      setPendingKick(null);
    } catch (err: any) {
      alert(`Error: ${err.message}`);
      setPendingKick(null);
    }
  };

  const updateGroupUsage = (groupId: string) => {
    const updated = groups.map(g => 
      g.id === groupId ? { ...g, lastInteraction: Date.now() } : g
    );
    setGroups(updated);
    localStorage.setItem('tg_groups', JSON.stringify(updated));
  };

  const refreshMemberCounts = async (currentToken: string) => {
    if (!currentToken || groups.length === 0) return;
    setIsRefreshing(true);
    const updatedGroupsPromises = groups.map(async (group) => {
        try {
            const memberCount = await getChatMemberCount(currentToken, group.id);
            return { ...group, memberCount };
        } catch (e) {
            console.error(`Failed to update member count for ${group.name}`, e);
            return group; 
        }
    });
    const updatedGroups = await Promise.all(updatedGroupsPromises);
    setGroups(updatedGroups);
    localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
    setIsRefreshing(false);
  };

  const joinsToday = useMemo(() => {
    const startOfDay = new Date().setHours(0, 0, 0, 0);
    return joinEvents.filter(e => e.timestamp >= startOfDay).length;
  }, [joinEvents]);

  const sortedGroups = useMemo(() => {
    return [...groups].sort((a, b) => (b.lastInteraction || 0) - (a.lastInteraction || 0));
  }, [groups]);

  const filteredGroups = sortedGroups.filter(g => 
    g.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    g.id.includes(searchQuery)
  );

  const groupedJoinEvents = useMemo(() => {
    const groups: { [date: string]: JoinEvent[] } = {};
    const today = new Date().toLocaleDateString();
    const yesterday = new Date(Date.now() - 86400000).toLocaleDateString();

    joinEvents.forEach(event => {
      const date = new Date(event.timestamp).toLocaleDateString();
      let label = date;
      if (date === today) label = "Today";
      else if (date === yesterday) label = "Yesterday";

      if (!groups[label]) groups[label] = [];
      groups[label].push(event);
    });
    return groups;
  }, [joinEvents]);

  const handleExport = () => {
    const config = { token, groups, isLocked, joinEvents };
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(config, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", "telebridge-config.json");
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const text = e.target?.result;
            if (typeof text !== 'string') throw new Error("Invalid file content");
            const config = JSON.parse(text);

            if (window.confirm("Overwrite current configuration? This cannot be undone.")) {
                if (config.token && typeof config.token === 'string') {
                    setToken(config.token);
                    localStorage.setItem('tg_bot_token', config.token);
                    handleVerify(config.token);
                }
                if (config.groups && Array.isArray(config.groups)) {
                    setGroups(config.groups);
                    localStorage.setItem('tg_groups', JSON.stringify(config.groups));
                }
                if (config.joinEvents && Array.isArray(config.joinEvents)) {
                    setJoinEvents(config.joinEvents);
                }
                if (typeof config.isLocked === 'boolean') {
                    setIsLocked(config.isLocked);
                    localStorage.setItem('tg_token_locked', config.isLocked.toString());
                }
            }
        } catch (error) {
            setError("Failed to parse configuration file.");
        } finally {
            if(event.target) event.target.value = '';
        }
    };
    reader.readAsText(file);
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans selection:bg-blue-500/30 transition-colors duration-300">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        theme={theme} 
        toggleTheme={toggleTheme} 
      />

      <main className="flex-1 md:ml-64 p-4 md:p-10 pb-24 md:pb-8">
        <header className="flex flex-col gap-6 mb-10">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[10px] font-extrabold text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em] mb-1">Administrator Portal</p>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">
                {activeTab}
              </h1>
            </div>

            <div className="flex items-center gap-2 md:gap-3">
               <button 
                 onClick={toggleTheme}
                 className="p-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-500 dark:text-slate-400 hover:text-blue-500 transition-all active:scale-95 shadow-sm"
                 title="Toggle Theme"
               >
                 {theme === 'dark' ? <Icons.Sun size={20} /> : <Icons.Moon size={20} />}
               </button>
               <div className={`hidden md:flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm`}>
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
                 <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">
                   {botInfo ? `@${botInfo.username}` : 'Offline'}
                 </span>
               </div>
               <button onClick={() => handleVerify(token)} className="p-2.5 text-slate-400 hover:text-blue-500 transition-all hover:scale-110 active:scale-95 bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800">
                  <Icons.Zap size={20} className={isVerifying ? 'animate-spin text-blue-500' : ''} />
               </button>
            </div>
          </div>

          {(activeTab === 'dashboard' || activeTab === 'groups') && (
            <div className="flex flex-col md:flex-row items-center gap-4 p-2 bg-slate-200/50 dark:bg-slate-900/50 rounded-2xl border border-slate-300/30 dark:border-slate-800/50">
              <div className="relative group w-full md:flex-1">
                <Icons.Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600 pointer-events-none" />
                <input 
                  type="text" 
                  placeholder="Filter by name or Chat ID..." 
                  className="bg-transparent text-slate-900 dark:text-white pl-10 pr-4 py-3 rounded-xl w-full text-sm outline-none placeholder-slate-400 dark:placeholder-slate-500"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>

              <div className="flex w-full md:w-auto gap-2">
                <input 
                  type="text" 
                  placeholder="Chat ID (-100...)" 
                  className="flex-1 md:w-48 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-4 py-3 rounded-xl text-xs outline-none focus:ring-2 focus:ring-blue-500/20"
                  value={newChatId}
                  onChange={(e) => setNewChatId(e.target.value)}
                />
                <button 
                  onClick={handleAddGroup}
                  disabled={isAddingGroup || !botInfo}
                  className="px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg shadow-blue-600/20 active:scale-95 whitespace-nowrap"
                >
                  {isAddingGroup ? 'Connecting...' : 'Sync Group'}
                </button>
              </div>
            </div>
          )}
        </header>

