import { GoogleGenAI, Type } from "@google/genai";
import { TelegramGroup, GeminiInsight } from "../types.ts";

/**
 * Helper to get the AI instance.
 * Guidelines require creating a new instance before API calls for up-to-date keys.
 */
const getAi = () => new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function getGroupInsights(group: TelegramGroup): Promise<GeminiInsight> {
  const prompt = `Analyze this Telegram group and provide administrative insights:
    Name: ${group.name}
    Description: ${group.description}
    Members: ${group.memberCount}
    Category: ${group.category}

    Provide a professional summary, a strategy for growth, and a creative suggestion for member retention.`;

  try {
    const ai = getAi();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            title: { type: Type.STRING },
            summary: { type: Type.STRING },
            suggestion: { type: Type.STRING },
          },
          required: ["title", "summary", "suggestion"],
        },
      },
    });

    // Access the .text property directly, do not call as a method
    const text = response.text || "{}";
    return JSON.parse(text.trim());
  } catch (error) {
    console.error("Gemini Error:", error);
    return {
      title: "Group Analysis",
      summary: "Could not generate insights at this time.",
      suggestion: "Try again later."
    };
  }
}

export async function generateLinkDescription(groupName: string): Promise<string> {
  const prompt = `Generate a short, enticing 1-sentence invite message for a group named "${groupName}" that emphasizes exclusivity.`;

  try {
    const ai = getAi();
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
    });
    // Access the .text property directly
    return response.text?.trim() || `You're invited to join ${groupName}! This link is for your eyes only.`;
  } catch (error) {
    return `You're invited to join ${groupName}! This link is for your eyes only.`;
  }
}

const BASE_URL = 'https://api.telegram.org/bot';

export interface TelegramBotInfo {
  id: number;
  is_bot: boolean;
  first_name: string;
  username: string;
}

export interface TelegramChat {
  id: number;
  title: string;
  type: string;
  description?: string;
}

export async function verifyBotToken(token: string): Promise<TelegramBotInfo> {
  const response = await fetch(`${BASE_URL}${token}/getMe`);
  const data = await response.json();
  if (!data.ok) throw new Error(data.description || 'Invalid Token');
  return data.result;
}

export async function getChatDetails(token: string, chatId: string | number): Promise<TelegramChat> {
  const response = await fetch(`${BASE_URL}${token}/getChat?chat_id=${chatId}`);
  const data = await response.json();
  if (!data.ok) throw new Error(data.description || 'Could not find chat. Make sure the bot is an admin in the group.');
  return data.result;
}

export async function getChatMemberCount(token: string, chatId: string | number): Promise<number> {
  const response = await fetch(`${BASE_URL}${token}/getChatMemberCount?chat_id=${chatId}`);
  const data = await response.json();
  if (!data.ok) throw new Error(data.description || 'Could not get member count.');
  return data.result;
}

export async function createInviteLink(
  token: string, 
  chatId: string | number, 
  limit: number, 
  expireMinutes: number
): Promise<string> {
  let url = `${BASE_URL}${token}/createChatInviteLink?chat_id=${chatId}&member_limit=${limit}`;

  if (expireMinutes > 0) {
    const expireDate = Math.floor(Date.now() / 1000) + (expireMinutes * 60);
    url += `&expire_date=${expireDate}`;
  }

  const response = await fetch(url);
  const data = await response.json();
  if (!data.ok) throw new Error(data.description || 'Failed to create invite link');
  return data.result.invite_link;
}

export async function kickChatMember(token: string, chatId: string | number, userId: number): Promise<boolean> {
  // Ban member
  const response = await fetch(`${BASE_URL}${token}/banChatMember?chat_id=${chatId}&user_id=${userId}`);
  const data = await response.json();
  if (!data.ok) throw new Error(data.description || 'Failed to kick member');

  // Unban immediately to just "kick" and not permanently ban
  await fetch(`${BASE_URL}${token}/unbanChatMember?chat_id=${chatId}&user_id=${userId}`);
  return true;
}

export async function getRecentUpdates(token: string, offset?: number): Promise<any[]> {
  // Request multiple update types to catch bot joining groups and user member changes
  const allowedUpdates = JSON.stringify(["chat_member", "my_chat_member", "message"]);
  const url = `${BASE_URL}${token}/getUpdates?allowed_updates=${allowedUpdates}${offset ? `&offset=${offset}` : ''}`;
  const response = await fetch(url);
  const data = await response.json();
  if (!data.ok) return [];
  return data.result;
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar.tsx';
