import { verifyBotToken, getChatDetails, TelegramBotInfo, getChatMemberCount, getRecentUpdates, kickChatMember } from './services/telegramService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    if (saved) return saved as 'light' | 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isLocked, setIsLocked] = useState(() => localStorage.getItem('tg_token_locked') === 'true');
  const [groups, setGroups] = useState<TelegramGroup[]>(() => {
    const saved = localStorage.getItem('tg_groups');
    return saved ? JSON.parse(saved) : [];
  });
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [totalMembers, setTotalMembers] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [joinEvents, setJoinEvents] = useState<JoinEvent[]>(() => {
    const saved = localStorage.getItem('tg_join_events');
    return saved ? JSON.parse(saved) : [];
  });
  const [lastUpdateId, setLastUpdateId] = useState(() => Number(localStorage.getItem('tg_last_update_id')) || 0);
  const [pendingKick, setPendingKick] = useState<string | null>(null);

  const importFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  useEffect(() => {
    const total = groups.reduce((sum, group) => sum + (group.memberCount || 0), 0);
    setTotalMembers(total);
  }, [groups]);

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('tg_token_locked', isLocked.toString());
  }, [isLocked]);

  useEffect(() => {
    localStorage.setItem('tg_join_events', JSON.stringify(joinEvents));
  }, [joinEvents]);

  useEffect(() => {
    localStorage.setItem('tg_last_update_id', lastUpdateId.toString());
  }, [lastUpdateId]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));
  };

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
      refreshMemberCounts(testToken);
      discoverGroupsAndJoins(testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const discoverGroupsAndJoins = async (currentToken: string) => {
    if (!currentToken || isScanning) return;
    setIsScanning(true);
    try {
      const updates = await getRecentUpdates(currentToken, lastUpdateId + 1);
      const newDiscoveredGroups: Map<number, string> = new Map();
      const newDiscoveredJoins: JoinEvent[] = [];
      let maxId = lastUpdateId;

      updates.forEach(update => {
        maxId = Math.max(maxId, update.update_id);

        // Find Groups from messages, member updates or bot state changes
        const chat = update.message?.chat || 
                     update.chat_member?.chat || 
                     update.my_chat_member?.chat || 
                     update.channel_post?.chat;

        if (chat && (chat.type === 'group' || chat.type === 'supergroup' || chat.type === 'channel')) {
          newDiscoveredGroups.set(chat.id, chat.title || chat.username || 'Unknown Hub');
        }

        // Find Join Events
        const memberUpdate = update.chat_member;
        if (memberUpdate && memberUpdate.new_chat_member?.status === 'member') {
          newDiscoveredJoins.push({
            userId: memberUpdate.new_chat_member.user.id,
            userName: memberUpdate.new_chat_member.user.first_name + (memberUpdate.new_chat_member.user.last_name ? ` ${memberUpdate.new_chat_member.user.last_name}` : ''),
            chatId: memberUpdate.chat.id,
            chatTitle: memberUpdate.chat.title,
            timestamp: memberUpdate.date ? memberUpdate.date * 1000 : Date.now()
          });
        }
      });

      // Update Groups list automatically
      if (newDiscoveredGroups.size > 0) {
        const currentIds = new Set(groups.map(g => g.id));
        const addedGroups: TelegramGroup[] = [];

        for (const [id, title] of newDiscoveredGroups.entries()) {
          const stringId = id.toString();
          if (!currentIds.has(stringId)) {
            try {
              const count = await getChatMemberCount(currentToken, stringId);
              addedGroups.push({
                id: stringId,
                name: title,
                memberCount: count,
                description: 'Auto-discovered via deep scan',
                category: 'Telegram',
                image: `https://picsum.photos/seed/${id}/200`,
                lastInteraction: Date.now()
              });
            } catch (e) { 
              console.error("Discovery error for chat", id);
              // Still add if it's new
              addedGroups.push({
                id: stringId,
                name: title,
                memberCount: 0,
                description: 'Auto-discovered via deep scan',
                category: 'Telegram',
                image: `https://picsum.photos/seed/${id}/200`,
                lastInteraction: Date.now()
              });
            }
          }
        }

        if (addedGroups.length > 0) {
          const updated = [...addedGroups, ...groups];
          setGroups(updated);
          localStorage.setItem('tg_groups', JSON.stringify(updated));
        }
      }

      // Update Join Events
      if (newDiscoveredJoins.length > 0) {
        setJoinEvents(prev => {
          const merged = [...newDiscoveredJoins, ...prev];
          // Unique by user and timestamp to avoid double recording
          const unique = merged.filter((v, i, a) => a.findIndex(t => (t.userId === v.userId && t.timestamp === v.timestamp)) === i);
          return unique.slice(0, 1000);
        });
      }

      setLastUpdateId(maxId);
    } catch (e) {
      console.error("Discovery process failed", e);
    } finally {
      setIsScanning(false);
    }
  };

  const handleKickConfirm = (eventId: string) => {
    if (pendingKick === eventId) {
      setPendingKick(null);
    } else {
      setPendingKick(eventId);
    }
  };

  const handleExecuteKick = async (chatId: number, userId: number, eventId: string) => {
    if (!token) return;
    try {
      await kickChatMember(token, chatId, userId);
      setJoinEvents(prev => prev.filter(e => `${e.userId}-${e.timestamp}` !== eventId));
      setPendingKick(null);
      // Refresh count for that group
      refreshMemberCounts(token);
    } catch (err: any) {
      alert(`Kick failed: ${err.message}`);
      setPendingKick(null);
    }
  };

  const refreshMemberCounts = async (currentToken: string) => {
    if (!currentToken || groups.length === 0) return;
    setIsRefreshing(true);
    const updatedGroupsPromises = groups.map(async (group) => {
        try {
            const memberCount = await getChatMemberCount(currentToken, group.id);
            return { ...group, memberCount };
        } catch (e) { return group; }
    });
    const updatedGroups = await Promise.all(updatedGroupsPromises);
    setGroups(updatedGroups);
    localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
    setIsRefreshing(false);
  };

  const filteredJoinsForSelectedDate = useMemo(() => {
    return joinEvents.filter(e => {
      const dateStr = new Date(e.timestamp).toISOString().split('T')[0];
      return dateStr === selectedDate;
    }).sort((a, b) => b.timestamp - a.timestamp);
  }, [joinEvents, selectedDate]);

  const joinsOnSelectedDateCount = useMemo(() => filteredJoinsForSelectedDate.length, [filteredJoinsForSelectedDate]);

  const joinsToday = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === today).length;
  }, [joinEvents]);

  const sortedGroups = useMemo(() => {
    return [...groups].sort((a, b) => (b.lastInteraction || 0) - (a.lastInteraction || 0));
  }, [groups]);

  const filteredGroups = sortedGroups.filter(g => 
    g.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    g.id.includes(searchQuery)
  );

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans selection:bg-blue-500/30 transition-colors duration-300">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} theme={theme} toggleTheme={toggleTheme} />

      <main className="flex-1 md:ml-64 p-4 md:p-10 pb-24 md:pb-8">
        <header className="flex flex-col gap-6 mb-10">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[10px] font-extrabold text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em] mb-1">TeleBridge Control</p>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">{activeTab}</h1>
            </div>

            <div className="flex items-center gap-2 md:gap-3">
               <button 
                 onClick={toggleTheme} 
                 className="p-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-500 hover:text-blue-500 transition-all shadow-sm active:scale-95"
                 title="Toggle Theme"
               >
                 {theme === 'dark' ? <Icons.Sun size={20} /> : <Icons.Moon size={20} />}
               </button>
               <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm">
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
                 <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">{botInfo ? `@${botInfo.username}` : 'Offline'}</span>
               </div>
               <button 
                 onClick={() => discoverGroupsAndJoins(token)} 
                 className="p-2.5 text-slate-400 hover:text-blue-500 transition-all bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 active:scale-95 shadow-sm"
                 title="Deep Scan Bot Updates"
               >
                  <Icons.Zap size={20} className={isScanning ? 'animate-spin text-blue-500' : ''} />
               </button>
            </div>
          </div>

          {activeTab !== 'settings' && activeTab !== 'analysis' && (
            <div className="flex flex-col md:flex-row items-center gap-4 p-2 bg-slate-200/50 dark:bg-slate-900/50 rounded-2xl border border-slate-300/30 dark:border-slate-800/50">
              <div className="relative group w-full md:flex-1">
                <Icons.Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" />
                <input type="text" placeholder="Filter synced hubs..." className="bg-transparent text-slate-900 dark:text-white pl-10 pr-4 py-3 rounded-xl w-full text-sm outline-none placeholder-slate-500" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              </div>
              <button onClick={() => discoverGroupsAndJoins(token)} disabled={isScanning || !botInfo} className="w-full md:w-auto px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg active:scale-95 whitespace-nowrap">
                {isScanning ? 'Scanning Activity...' : 'Force Deep Scan'}
              </button>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/5 border border-rose-500/20 text-rose-600 dark:text-rose-400 rounded-2xl text-[11px] font-bold uppercase tracking-wider flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
             <div className="w-2 h-2 rounded-full bg-rose-500" />
             {error}
          </div>
        )}

        <div className="space-y-12">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                  <p className="text-[10px] font-extrabold text-slate-400 uppercase mb-2 tracking-widest">Active Hubs</p>
                  <p className="text-3xl font-black">{groups.length}</p>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                  <p className="text-[10px] font-extrabold text-slate-400 uppercase mb-2 tracking-widest">Global Reach</p>
                  <p className="text-3xl font-black">{totalMembers.toLocaleString()}</p>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                  <p className="text-[10px] font-extrabold text-blue-500 uppercase mb-2 tracking-widest">Growth (Today)</p>
                  <p className="text-3xl font-black">{joinsToday}</p>
               </div>
               <div className={`p-6 rounded-3xl border shadow-xl transition-all duration-500 ${isScanning ? 'bg-blue-600 border-blue-400/20 shadow-blue-500/30' : 'bg-slate-900 border-slate-800 shadow-black/20'}`}>
                  <p className={`text-[10px] font-extrabold uppercase mb-2 tracking-widest ${isScanning ? 'text-blue-100' : 'text-slate-500'}`}>Scanner Status</p>
                  <p className="text-lg font-bold text-white flex items-center gap-2">
                    {isScanning && <Icons.Refresh size={18} className="animate-spin" />}
                    {isScanning ? 'Discovering Hubs...' : 'Idle - Ready to Scan'}
                  </p>
               </div>
            </div>
          )}

          {activeTab === 'groups' && (
            <section className="animate-in fade-in slide-in-from-bottom-2">
              <div className="flex items-center justify-between mb-8">
                <h2 className="text-xs font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">Group Directory</h2>
                <div className="flex items-center gap-2">
                  <button onClick={() => refreshMemberCounts(token)} disabled={isRefreshing} className="p-2 text-slate-400 hover:text-blue-500 transition-all">
                    <Icons.Refresh size={16} className={isRefreshing ? 'animate-spin' : ''} />
                  </button>
                  <span className="text-[10px] font-bold text-slate-400">{filteredGroups.length} synced</span>
                </div>
              </div>
              {filteredGroups.length > 0 ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {filteredGroups.map((group, idx) => (
                    <GroupCard key={group.id} group={group} isPriority={idx === 0 && !!group.lastInteraction} onClick={(g) => { setSelectedGroup(g); }} />
                  ))}
                </div>
              ) : (
                <div className="text-center py-20 bg-white/50 dark:bg-slate-900/20 rounded-[2.5rem] border border-dashed border-slate-200 dark:border-slate-800">
                   <p className="text-sm text-slate-400">No groups found. Try a "Deep Scan" to auto-discover groups where the bot is active.</p>
                </div>
              )}
            </section>
          )}

          {activeTab === 'analysis' && (
            <div className="space-y-8 animate-in fade-in">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 flex flex-col md:flex-row items-start md:items-center justify-between gap-4 bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm">
                  <div>
                    <h2 className="text-xl font-black">History Explorer</h2>
                    <p className="text-xs text-slate-500 mt-1">Audit member growth for specific dates</p>
                  </div>
                  <div className="flex items-center gap-3 w-full md:w-auto">
                    <input 
                      type="date" 
                      value={selectedDate} 
                      onChange={(e) => setSelectedDate(e.target.value)}
                      className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-5 py-3 rounded-2xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500/20 transition-all cursor-pointer"
                    />
                    <button 
                      onClick={() => discoverGroupsAndJoins(token)} 
                      className="p-3.5 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-500/20 active:scale-95 transition-all"
                      title="Sync Recent Updates"
                    >
                      <Icons.Refresh size={20} className={isScanning ? 'animate-spin' : ''} />
                    </button>
                  </div>
                </div>

                <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-8 rounded-[2.5rem] text-white shadow-xl shadow-blue-500/20 flex flex-col justify-center">
                   <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Records for {selectedDate}</p>
                   <p className="text-4xl font-black">{joinsOnSelectedDateCount}</p>
                   <p className="text-xs font-medium mt-2 opacity-90">Member joins discovered</p>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] overflow-hidden shadow-xl">
                 <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-950/20">
                    <div>
                      <h2 className="text-lg font-black">{selectedDate === new Date().toISOString().split('T')[0] ? 'Live Join Feed (Today)' : `Join Log: ${selectedDate}`}</h2>
                      <p className="text-[10px] font-bold text-blue-600 uppercase tracking-widest mt-1">Audit Compliance Active</p>
                    </div>
                    <span className="px-4 py-2 bg-slate-950 dark:bg-white text-white dark:text-slate-950 text-[10px] font-black uppercase rounded-xl tracking-tighter">Verified Events</span>
                 </div>

                 <div className="overflow-x-auto">
                    <table className="w-full text-left">
                       <thead>
                          <tr className="border-b border-slate-100 dark:border-slate-800">
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">User Details</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Target Hub</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Precise Time</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Moderation</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                          {filteredJoinsForSelectedDate.length > 0 ? filteredJoinsForSelectedDate.map((event) => {
                            const eventId = `${event.userId}-${event.timestamp}`;
                            const isPending = pendingKick === eventId;
                            return (
                              <tr key={eventId} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                <td className="px-8 py-6">
                                  <div className="flex items-center gap-3">
                                      <div className="w-10 h-10 bg-gradient-to-tr from-slate-200 to-slate-100 dark:from-slate-800 dark:to-slate-700 rounded-full flex items-center justify-center text-slate-500 dark:text-slate-400 font-black text-sm border border-white/10 shadow-inner">
                                        {event.userName.charAt(0)}
                                      </div>
                                      <span className="text-sm font-bold text-slate-900 dark:text-white">{event.userName}</span>
                                  </div>
                                </td>
                                <td className="px-8 py-6 text-sm text-slate-500 dark:text-slate-400 font-medium">
                                  <span className="px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg">{event.chatTitle}</span>
                                </td>
                                <td className="px-8 py-6 text-xs text-slate-400 font-mono">
                                  {new Date(event.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                                </td>
                                <td className="px-8 py-6 text-right">
                                  {isPending ? (
                                    <div className="flex items-center justify-end gap-2 animate-in slide-in-from-right-2">
                                      <button 
                                        onClick={() => handleExecuteKick(event.chatId, event.userId, eventId)}
                                        className="px-4 py-2 bg-rose-600 text-white text-[10px] font-black uppercase rounded-xl shadow-lg shadow-rose-600/20 active:scale-95"
                                      >
                                        Execute Kick
                                      </button>
                                      <button 
                                        onClick={() => setPendingKick(null)}
                                        className="px-4 py-2 bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 text-[10px] font-black uppercase rounded-xl active:scale-95"
                                      >
                                        Cancel
                                      </button>
                                    </div>
                                  ) : (
                                    <button 
                                      onClick={() => handleKickConfirm(eventId)}
                                      className="p-3 bg-rose-500/10 hover:bg-rose-500 text-rose-500 hover:text-white rounded-2xl transition-all active:scale-90"
                                      title="Initiate Kick"
                                    >
                                      <Icons.Trash size={18} />
                                    </button>
                                  )}
                                </td>
                              </tr>
                            );
                          }) : (
                             <tr>
                                <td colSpan={4} className="px-8 py-24 text-center">
                                   <div className="flex flex-col items-center gap-4">
                                     <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center text-slate-300 dark:text-slate-600">
                                       <Icons.Clock size={32} />
                                     </div>
                                     <div className="max-w-xs mx-auto">
                                       <p className="text-sm font-bold text-slate-900 dark:text-white">No Join Records</p>
                                       <p className="text-xs text-slate-400 mt-1">No member activity discovered on {selectedDate}. Tap scan to check for updates.</p>
                                     </div>
                                   </div>
                                </td>
                             </tr>
                          )}
                       </tbody>
                    </table>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="max-w-3xl space-y-8 animate-in fade-in slide-in-from-bottom-4">
              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <div className="flex items-start justify-between mb-10">
                  <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-blue-600/10 rounded-2xl flex items-center justify-center text-blue-600 shadow-inner">
                      <Icons.Zap size={28} />
                    </div>
                    <div>
                      <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">API Infrastructure</h2>
                      <p className="text-sm text-slate-500">Core BotFather link status</p>
                    </div>
                  </div>
                  <button onClick={() => setIsLocked(!isLocked)} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${ isLocked ? 'bg-rose-500/10 text-rose-500' : 'bg-emerald-500/10 text-emerald-500' }`}>
                    <Icons.Check size={14} strokeWidth={3} /> {isLocked ? 'Immutable' : 'Configurable'}
                  </button>
                </div>
                <div className="space-y-4">
                    <label className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Secret Bot Token</label>
                    <input type="password" placeholder="Enter Token..." disabled={isLocked} className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-6 py-5 rounded-2xl text-sm font-mono text-blue-600 dark:text-blue-400 outline-none focus:ring-4 focus:ring-blue-500/10 transition-all disabled:opacity-50" value={token} onChange={(e) => setToken(e.target.value)} />
                </div>
                {!isLocked && (
                    <div className="flex flex-col sm:flex-row gap-4 pt-8">
                      <button onClick={() => handleVerify(token)} disabled={isVerifying} className="flex-1 px-8 py-5 bg-blue-600 hover:bg-blue-500 text-white text-sm font-black rounded-2xl transition-all active:scale-[0.98] shadow-xl shadow-blue-600/20">
                        {isVerifying ? 'Authenticating...' : 'Validate and Connect'}
                      </button>
                      <button onClick={() => { setToken(''); setBotInfo(null); localStorage.removeItem('tg_bot_token'); }} className="px-8 py-5 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 text-sm font-black rounded-2xl hover:text-rose-500 transition-all">
                        Clear Node
                      </button>
                    </div>
                )}
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <div className="flex items-center justify-between mb-8">
                  <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">Data Management</h2>
                  <div className="flex items-center gap-2">
                    <button onClick={handleExport} className="p-3 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-200 rounded-xl hover:text-blue-500 transition-all shadow-sm" title="Backup Config">
                      <Icons.DownloadCloud size={20} />
                    </button>
                    <button onClick={() => importFileRef.current?.click()} className="p-3 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-200 rounded-xl hover:text-blue-500 transition-all shadow-sm" title="Restore Config">
                      <Icons.UploadCloud size={20} />
                    </button>
                    <input type="file" ref={importFileRef} onChange={handleImport} accept=".json" className="hidden" />
                  </div>
                </div>
                <p className="text-sm text-slate-500 mb-8 leading-relaxed">Backup your group directory and join history events to a local JSON file for security.</p>
                <div className="p-6 bg-amber-500/5 border border-amber-500/10 rounded-2xl">
                   <p className="text-[11px] font-bold text-amber-600 dark:text-amber-400 uppercase tracking-wider mb-2">Cloud Warning</p>
                   <p className="text-xs text-slate-600 dark:text-slate-400">All data is stored locally in your browser. Clearing your browser data will wipe your synced hubs and join logs. Use the export tool regularly.</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar.tsx';
import GroupCard from './components/GroupCard.tsx';
import InviteModal from './components/InviteModal.tsx';
import { Icons } from './constants.tsx';
import { TelegramGroup, JoinEvent } from './types.ts';
import { verifyBotToken, getChatDetails, TelegramBotInfo, getChatMemberCount, getRecentUpdates, kickChatMember } from './services/telegramService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    if (saved) return saved as 'light' | 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isLocked, setIsLocked] = useState(() => localStorage.getItem('tg_token_locked') === 'true');
  const [groups, setGroups] = useState<TelegramGroup[]>(() => {
    const saved = localStorage.getItem('tg_groups');
    return saved ? JSON.parse(saved) : [];
  });
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [totalMembers, setTotalMembers] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [joinEvents, setJoinEvents] = useState<JoinEvent[]>(() => {
    const saved = localStorage.getItem('tg_join_events');
    return saved ? JSON.parse(saved) : [];
  });
  const [lastUpdateId, setLastUpdateId] = useState(() => Number(localStorage.getItem('tg_last_update_id')) || 0);
  const [pendingKick, setPendingKick] = useState<string | null>(null);

  const importFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  useEffect(() => {
    const total = groups.reduce((sum, group) => sum + (group.memberCount || 0), 0);
    setTotalMembers(total);
  }, [groups]);

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('tg_token_locked', isLocked.toString());
  }, [isLocked]);

  useEffect(() => {
    localStorage.setItem('tg_join_events', JSON.stringify(joinEvents));
  }, [joinEvents]);

  useEffect(() => {
    localStorage.setItem('tg_last_update_id', lastUpdateId.toString());
  }, [lastUpdateId]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));
  };

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
      refreshMemberCounts(testToken);
      discoverGroupsAndJoins(testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const discoverGroupsAndJoins = async (currentToken: string) => {
    if (!currentToken || isScanning) return;
    setIsScanning(true);
    try {
      const updates = await getRecentUpdates(currentToken, lastUpdateId + 1);
      const newDiscoveredGroups: Map<number, string> = new Map();
      const newDiscoveredJoins: JoinEvent[] = [];
      let maxId = lastUpdateId;

      updates.forEach(update => {
        maxId = Math.max(maxId, update.update_id);

        // Find Groups from messages, member updates or bot state changes
        const chat = update.message?.chat || 
                     update.chat_member?.chat || 
                     update.my_chat_member?.chat || 
                     update.channel_post?.chat;

        if (chat && (chat.type === 'group' || chat.type === 'supergroup' || chat.type === 'channel')) {
          newDiscoveredGroups.set(chat.id, chat.title || chat.username || 'Unknown Hub');
        }

        // Find Join Events
        const memberUpdate = update.chat_member;
        if (memberUpdate && memberUpdate.new_chat_member?.status === 'member') {
          newDiscoveredJoins.push({
            userId: memberUpdate.new_chat_member.user.id,
            userName: memberUpdate.new_chat_member.user.first_name + (memberUpdate.new_chat_member.user.last_name ? ` ${memberUpdate.new_chat_member.user.last_name}` : ''),
            chatId: memberUpdate.chat.id,
            chatTitle: memberUpdate.chat.title,
            timestamp: memberUpdate.date ? memberUpdate.date * 1000 : Date.now()
          });
        }
      });

      // Update Groups list automatically
      if (newDiscoveredGroups.size > 0) {
        const currentIds = new Set(groups.map(g => g.id));
        const addedGroups: TelegramGroup[] = [];

        for (const [id, title] of newDiscoveredGroups.entries()) {
          const stringId = id.toString();
          if (!currentIds.has(stringId)) {
            try {
              const count = await getChatMemberCount(currentToken, stringId);
              addedGroups.push({
                id: stringId,
                name: title,
                memberCount: count,
                description: 'Auto-discovered via deep scan',
                category: 'Telegram',
                image: `https://picsum.photos/seed/${id}/200`,
                lastInteraction: Date.now()
              });
            } catch (e) { 
              console.error("Discovery error for chat", id);
              // Still add if it's new
              addedGroups.push({
                id: stringId,
                name: title,
                memberCount: 0,
                description: 'Auto-discovered via deep scan',
                category: 'Telegram',
                image: `https://picsum.photos/seed/${id}/200`,
                lastInteraction: Date.now()
              });
            }
          }
        }

        if (addedGroups.length > 0) {
          const updated = [...addedGroups, ...groups];
          setGroups(updated);
          localStorage.setItem('tg_groups', JSON.stringify(updated));
        }
      }

      // Update Join Events
      if (newDiscoveredJoins.length > 0) {
        setJoinEvents(prev => {
          const merged = [...newDiscoveredJoins, ...prev];
          // Unique by user and timestamp to avoid double recording
          const unique = merged.filter((v, i, a) => a.findIndex(t => (t.userId === v.userId && t.timestamp === v.timestamp)) === i);
          return unique.slice(0, 1000);
        });
      }

      setLastUpdateId(maxId);
    } catch (e) {
      console.error("Discovery process failed", e);
    } finally {
      setIsScanning(false);
    }
  };

  const handleKickConfirm = (eventId: string) => {
    if (pendingKick === eventId) {
      setPendingKick(null);
    } else {
      setPendingKick(eventId);
    }
  };

  const handleExecuteKick = async (chatId: number, userId: number, eventId: string) => {
    if (!token) return;
    try {
      await kickChatMember(token, chatId, userId);
      setJoinEvents(prev => prev.filter(e => `${e.userId}-${e.timestamp}` !== eventId));
      setPendingKick(null);
      // Refresh count for that group
      refreshMemberCounts(token);
    } catch (err: any) {
      alert(`Kick failed: ${err.message}`);
      setPendingKick(null);
    }
  };

  const refreshMemberCounts = async (currentToken: string) => {
    if (!currentToken || groups.length === 0) return;
    setIsRefreshing(true);
    const updatedGroupsPromises = groups.map(async (group) => {
        try {
            const memberCount = await getChatMemberCount(currentToken, group.id);
            return { ...group, memberCount };
        } catch (e) { return group; }
    });
    const updatedGroups = await Promise.all(updatedGroupsPromises);
    setGroups(updatedGroups);
    localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
    setIsRefreshing(false);
  };

  // Fix: Implemented handleExport for configuration backup
  const handleExport = () => {
    const data = {
      groups,
      joinEvents,
      lastUpdateId
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `telebridge-backup-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  // Fix: Implemented handleImport for configuration restoration
  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);

        if (data.groups) {
          setGroups(data.groups);
          localStorage.setItem('tg_groups', JSON.stringify(data.groups));
        }
        if (data.joinEvents) {
          setJoinEvents(data.joinEvents);
          localStorage.setItem('tg_join_events', JSON.stringify(data.joinEvents));
        }
        if (data.lastUpdateId) {
          const newId = Number(data.lastUpdateId);
          setLastUpdateId(newId);
          localStorage.setItem('tg_last_update_id', newId.toString());
        }

        alert('Configuration restored successfully!');
      } catch (err) {
        console.error("Import error:", err);
        alert('Failed to import configuration. Invalid file format.');
      }
    };
    reader.readAsText(file);
    if (event.target) event.target.value = '';
  };

  const filteredJoinsForSelectedDate = useMemo(() => {
    return joinEvents.filter(e => {
      const dateStr = new Date(e.timestamp).toISOString().split('T')[0];
      return dateStr === selectedDate;
    }).sort((a, b) => b.timestamp - a.timestamp);
  }, [joinEvents, selectedDate]);

  const joinsOnSelectedDateCount = useMemo(() => filteredJoinsForSelectedDate.length, [filteredJoinsForSelectedDate]);

  const joinsToday = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === today).length;
  }, [joinEvents]);

  const sortedGroups = useMemo(() => {
    return [...groups].sort((a, b) => (b.lastInteraction || 0) - (a.lastInteraction || 0));
  }, [groups]);

  const filteredGroups = sortedGroups.filter(g => 
    g.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
    g.id.includes(searchQuery)
  );

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans selection:bg-blue-500/30 transition-colors duration-300">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} theme={theme} toggleTheme={toggleTheme} />

      <main className="flex-1 md:ml-64 p-4 md:p-10 pb-24 md:pb-8">
        <header className="flex flex-col gap-6 mb-10">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[10px] font-extrabold text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em] mb-1">TeleBridge Control</p>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">{activeTab}</h1>
            </div>

            <div className="flex items-center gap-2 md:gap-3">
               <button 
                 onClick={toggleTheme} 
                 className="p-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-500 hover:text-blue-500 transition-all shadow-sm active:scale-95"
                 title="Toggle Theme"
               >
                 {theme === 'dark' ? <Icons.Sun size={20} /> : <Icons.Moon size={20} />}
               </button>
               <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm">
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
                 <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">{botInfo ? `@${botInfo.username}` : 'Offline'}</span>
               </div>
               <button 
                 onClick={() => discoverGroupsAndJoins(token)} 
                 className="p-2.5 text-slate-400 hover:text-blue-500 transition-all bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 active:scale-95 shadow-sm"
                 title="Deep Scan Bot Updates"
               >
                  <Icons.Zap size={20} className={isScanning ? 'animate-spin text-blue-500' : ''} />
               </button>
            </div>
          </div>

          {activeTab !== 'settings' && activeTab !== 'analysis' && (
            <div className="flex flex-col md:flex-row items-center gap-4 p-2 bg-slate-200/50 dark:bg-slate-900/50 rounded-2xl border border-slate-300/30 dark:border-slate-800/50">
              <div className="relative group w-full md:flex-1">
                <Icons.Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" />
                <input type="text" placeholder="Filter synced hubs..." className="bg-transparent text-slate-900 dark:text-white pl-10 pr-4 py-3 rounded-xl w-full text-sm outline-none placeholder-slate-500" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              </div>
              <button onClick={() => discoverGroupsAndJoins(token)} disabled={isScanning || !botInfo} className="w-full md:w-auto px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg active:scale-95 whitespace-nowrap">
                {isScanning ? 'Scanning Activity...' : 'Force Deep Scan'}
              </button>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/5 border border-rose-500/20 text-rose-600 dark:text-rose-400 rounded-2xl text-[11px] font-bold uppercase tracking-wider flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
             <div className="w-2 h-2 rounded-full bg-rose-500" />
             {error}
          </div>
        )}

        <div className="space-y-12">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                  <p className="text-[10px] font-extrabold text-slate-400 uppercase mb-2 tracking-widest">Active Hubs</p>
                  <p className="text-3xl font-black">{groups.length}</p>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                  <p className="text-[10px] font-extrabold text-slate-400 uppercase mb-2 tracking-widest">Global Reach</p>
                  <p className="text-3xl font-black">{totalMembers.toLocaleString()}</p>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                  <p className="text-[10px] font-extrabold text-blue-500 uppercase mb-2 tracking-widest">Growth (Today)</p>
                  <p className="text-3xl font-black">{joinsToday}</p>
               </div>
               <div className={`p-6 rounded-3xl border shadow-xl transition-all duration-500 ${isScanning ? 'bg-blue-600 border-blue-400/20 shadow-blue-500/30' : 'bg-slate-900 border-slate-800 shadow-black/20'}`}>
                  <p className={`text-[10px] font-extrabold uppercase mb-2 tracking-widest ${isScanning ? 'text-blue-100' : 'text-slate-500'}`}>Scanner Status</p>
                  <p className="text-lg font-bold text-white flex items-center gap-2">
                    {isScanning && <Icons.Refresh size={18} className="animate-spin" />}
                    {isScanning ? 'Discovering Hubs...' : 'Idle - Ready to Scan'}
                  </p>
               </div>
            </div>
          )}

          {activeTab === 'groups' && (
            <section className="animate-in fade-in slide-in-from-bottom-2">
              <div className="flex items-center justify-between mb-8">
                <h2 className="text-xs font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">Group Directory</h2>
                <div className="flex items-center gap-2">
                  <button onClick={() => refreshMemberCounts(token)} disabled={isRefreshing} className="p-2 text-slate-400 hover:text-blue-500 transition-all">
                    <Icons.Refresh size={16} className={isRefreshing ? 'animate-spin' : ''} />
                  </button>
                  <span className="text-[10px] font-bold text-slate-400">{filteredGroups.length} synced</span>
                </div>
              </div>
              {filteredGroups.length > 0 ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {filteredGroups.map((group, idx) => (
                    <GroupCard key={group.id} group={group} isPriority={idx === 0 && !!group.lastInteraction} onClick={(g) => { setSelectedGroup(g); }} />
                  ))}
                </div>
              ) : (
                <div className="text-center py-20 bg-white/50 dark:bg-slate-900/20 rounded-[2.5rem] border border-dashed border-slate-200 dark:border-slate-800">
                   <p className="text-sm text-slate-400">No groups found. Try a "Deep Scan" to auto-discover groups where the bot is active.</p>
                </div>
              )}
            </section>
          )}

          {activeTab === 'analysis' && (
            <div className="space-y-8 animate-in fade-in">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 flex flex-col md:flex-row items-start md:items-center justify-between gap-4 bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm">
                  <div>
                    <h2 className="text-xl font-black">History Explorer</h2>
                    <p className="text-xs text-slate-500 mt-1">Audit member growth for specific dates</p>
                  </div>
                  <div className="flex items-center gap-3 w-full md:w-auto">
                    <input 
                      type="date" 
                      value={selectedDate} 
                      onChange={(e) => setSelectedDate(e.target.value)}
                      className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-5 py-3 rounded-2xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500/20 transition-all cursor-pointer"
                    />
                    <button 
                      onClick={() => discoverGroupsAndJoins(token)} 
                      className="p-3.5 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-500/20 active:scale-95 transition-all"
                      title="Sync Recent Updates"
                    >
                      <Icons.Refresh size={20} className={isScanning ? 'animate-spin' : ''} />
                    </button>
                  </div>
                </div>

                <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-8 rounded-[2.5rem] text-white shadow-xl shadow-blue-500/20 flex flex-col justify-center">
                   <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Records for {selectedDate}</p>
                   <p className="text-4xl font-black">{joinsOnSelectedDateCount}</p>
                   <p className="text-xs font-medium mt-2 opacity-90">Member joins discovered</p>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] overflow-hidden shadow-xl">
                 <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-950/20">
                    <div>
                      <h2 className="text-lg font-black">{selectedDate === new Date().toISOString().split('T')[0] ? 'Live Join Feed (Today)' : `Join Log: ${selectedDate}`}</h2>
                      <p className="text-[10px] font-bold text-blue-600 uppercase tracking-widest mt-1">Audit Compliance Active</p>
                    </div>
                    <span className="px-4 py-2 bg-slate-950 dark:bg-white text-white dark:text-slate-950 text-[10px] font-black uppercase rounded-xl tracking-tighter">Verified Events</span>
                 </div>

                 <div className="overflow-x-auto">
                    <table className="w-full text-left">
                       <thead>
                          <tr className="border-b border-slate-100 dark:border-slate-800">
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">User Details</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Target Hub</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Precise Time</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Moderation</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                          {filteredJoinsForSelectedDate.length > 0 ? filteredJoinsForSelectedDate.map((event) => {
                            const eventId = `${event.userId}-${event.timestamp}`;
                            const isPending = pendingKick === eventId;
                            return (
                              <tr key={eventId} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                <td className="px-8 py-6">
                                  <div className="flex items-center gap-3">
                                      <div className="w-10 h-10 bg-gradient-to-tr from-slate-200 to-slate-100 dark:from-slate-800 dark:to-slate-700 rounded-full flex items-center justify-center text-slate-500 dark:text-slate-400 font-black text-sm border border-white/10 shadow-inner">
                                        {event.userName.charAt(0)}
                                      </div>
                                      <span className="text-sm font-bold text-slate-900 dark:text-white">{event.userName}</span>
                                  </div>
                                </td>
                                <td className="px-8 py-6 text-sm text-slate-500 dark:text-slate-400 font-medium">
                                  <span className="px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg">{event.chatTitle}</span>
                                </td>
                                <td className="px-8 py-6 text-xs text-slate-400 font-mono">
                                  {new Date(event.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                                </td>
                                <td className="px-8 py-6 text-right">
                                  {isPending ? (
                                    <div className="flex items-center justify-end gap-2 animate-in slide-in-from-right-2">
                                      <button 
                                        onClick={() => handleExecuteKick(event.chatId, event.userId, eventId)}
                                        className="px-4 py-2 bg-rose-600 text-white text-[10px] font-black uppercase rounded-xl shadow-lg shadow-rose-600/20 active:scale-95"
                                      >
                                        Execute Kick
                                      </button>
                                      <button 
                                        onClick={() => setPendingKick(null)}
                                        className="px-4 py-2 bg-slate-200 dark:bg-slate-800 text-slate-600 dark:text-slate-300 text-[10px] font-black uppercase rounded-xl active:scale-95"
                                      >
                                        Cancel
                                      </button>
                                    </div>
                                  ) : (
                                    <button 
                                      onClick={() => handleKickConfirm(eventId)}
                                      className="p-3 bg-rose-500/10 hover:bg-rose-500 text-rose-500 hover:text-white rounded-2xl transition-all active:scale-90"
                                      title="Initiate Kick"
                                    >
                                      <Icons.Trash size={18} />
                                    </button>
                                  )}
                                </td>
                              </tr>
                            );
                          }) : (
                             <tr>
                                <td colSpan={4} className="px-8 py-24 text-center">
                                   <div className="flex flex-col items-center gap-4">
                                     <div className="w-16 h-16 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center text-slate-300 dark:text-slate-600">
                                       <Icons.Clock size={32} />
                                     </div>
                                     <div className="max-w-xs mx-auto">
                                       <p className="text-sm font-bold text-slate-900 dark:text-white">No Join Records</p>
                                       <p className="text-xs text-slate-400 mt-1">No member activity discovered on {selectedDate}. Tap scan to check for updates.</p>
                                     </div>
                                   </div>
                                </td>
                             </tr>
                          )}
                       </tbody>
                    </table>
                 </div>
              </div>
            </div>
          )}

          {activeTab === 'settings' && (
            <div className="max-w-3xl space-y-8 animate-in fade-in slide-in-from-bottom-4">
              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <div className="flex items-start justify-between mb-10">
                  <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-blue-600/10 rounded-2xl flex items-center justify-center text-blue-600 shadow-inner">
                      <Icons.Zap size={28} />
                    </div>
                    <div>
                      <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">API Infrastructure</h2>
                      <p className="text-sm text-slate-500">Core BotFather link status</p>
                    </div>
                  </div>
                  <button onClick={() => setIsLocked(!isLocked)} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${ isLocked ? 'bg-rose-500/10 text-rose-500' : 'bg-emerald-500/10 text-emerald-500' }`}>
                    <Icons.Check size={14} strokeWidth={3} /> {isLocked ? 'Immutable' : 'Configurable'}
                  </button>
                </div>
                <div className="space-y-4">
                    <label className="text-[10px] font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-widest">Secret Bot Token</label>
                    <input type="password" placeholder="Enter Token..." disabled={isLocked} className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-6 py-5 rounded-2xl text-sm font-mono text-blue-600 dark:text-blue-400 outline-none focus:ring-4 focus:ring-blue-500/10 transition-all disabled:opacity-50" value={token} onChange={(e) => setToken(e.target.value)} />
                </div>
                {!isLocked && (
                    <div className="flex flex-col sm:flex-row gap-4 pt-8">
                      <button onClick={() => handleVerify(token)} disabled={isVerifying} className="flex-1 px-8 py-5 bg-blue-600 hover:bg-blue-500 text-white text-sm font-black rounded-2xl transition-all active:scale-[0.98] shadow-xl shadow-blue-600/20">
                        {isVerifying ? 'Authenticating...' : 'Validate and Connect'}
                      </button>
                      <button onClick={() => { setToken(''); setBotInfo(null); localStorage.removeItem('tg_bot_token'); }} className="px-8 py-5 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 text-sm font-black rounded-2xl hover:text-rose-500 transition-all">
                        Clear Node
                      </button>
                    </div>
                )}
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <div className="flex items-center justify-between mb-8">
                  <h2 className="text-2xl font-black text-slate-900 dark:text-white tracking-tight">Data Management</h2>
                  <div className="flex items-center gap-2">
                    <button onClick={handleExport} className="p-3 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-200 rounded-xl hover:text-blue-500 transition-all shadow-sm" title="Backup Config">
                      <Icons.DownloadCloud size={20} />
                    </button>
                    <button onClick={() => importFileRef.current?.click()} className="p-3 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-200 rounded-xl hover:text-blue-500 transition-all shadow-sm" title="Restore Config">
                      <Icons.UploadCloud size={20} />
                    </button>
                    <input type="file" ref={importFileRef} onChange={handleImport} accept=".json" className="hidden" />
                  </div>
                </div>
                <p className="text-sm text-slate-500 mb-8 leading-relaxed">Backup your group directory and join history events to a local JSON file for security.</p>
                <div className="p-6 bg-amber-500/5 border border-amber-500/10 rounded-2xl">
                   <p className="text-[11px] font-bold text-amber-600 dark:text-amber-400 uppercase tracking-wider mb-2">Cloud Warning</p>
                   <p className="text-xs text-slate-600 dark:text-slate-400">All data is stored locally in your browser. Clearing your browser data will wipe your synced hubs and join logs. Use the export tool regularly.</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar.tsx';
import GroupCard from './components/GroupCard.tsx';
import InviteModal from './components/InviteModal.tsx';
import { Icons } from './constants.tsx';
import { TelegramGroup, JoinEvent } from './types.ts';
import { verifyBotToken, getChatDetails, TelegramBotInfo, getChatMemberCount, getRecentUpdates, kickChatMember } from './services/telegramService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    if (saved) return saved as 'light' | 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isLocked, setIsLocked] = useState(() => localStorage.getItem('tg_token_locked') === 'true');
  const [groups, setGroups] = useState<TelegramGroup[]>(() => {
    const saved = localStorage.getItem('tg_groups');
    return saved ? JSON.parse(saved) : [];
  });
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [totalMembers, setTotalMembers] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [joinEvents, setJoinEvents] = useState<JoinEvent[]>(() => {
    const saved = localStorage.getItem('tg_join_events');
    return saved ? JSON.parse(saved) : [];
  });
  const [lastUpdateId, setLastUpdateId] = useState(() => Number(localStorage.getItem('tg_last_update_id')) || 0);
  const [pendingKick, setPendingKick] = useState<string | null>(null);

  const importFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  useEffect(() => {
    const total = groups.reduce((sum, group) => sum + (group.memberCount || 0), 0);
    setTotalMembers(total);
  }, [groups]);

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('tg_token_locked', isLocked.toString());
  }, [isLocked]);

  useEffect(() => {
    localStorage.setItem('tg_join_events', JSON.stringify(joinEvents));
  }, [joinEvents]);

  useEffect(() => {
    localStorage.setItem('tg_last_update_id', lastUpdateId.toString());
  }, [lastUpdateId]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));
  };

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
      // Immediately refresh and scan for groups on connection
      refreshMemberCounts(testToken);
      discoverGroupsAndJoins(testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const discoverGroupsAndJoins = async (currentToken: string) => {
    if (!currentToken || isScanning) return;
    setIsScanning(true);
    try {
      // Fetch latest updates to see which chats the bot is interacting with
      const updates = await getRecentUpdates(currentToken, lastUpdateId + 1);
      const newDiscoveredGroups: Map<number, string> = new Map();
      const newDiscoveredJoins: JoinEvent[] = [];
      let maxId = lastUpdateId;

      updates.forEach(update => {
        maxId = Math.max(maxId, update.update_id);

        // Identify groups from any update part (messages, bot membership changes, etc.)
        const chat = update.message?.chat || 
                     update.chat_member?.chat || 
                     update.my_chat_member?.chat || 
                     update.channel_post?.chat;

        if (chat && (chat.type === 'group' || chat.type === 'supergroup' || chat.type === 'channel')) {
          newDiscoveredGroups.set(chat.id, chat.title || chat.username || 'Unknown Hub');
        }

        // Identify new member joins
        const memberUpdate = update.chat_member;
        if (memberUpdate && memberUpdate.new_chat_member?.status === 'member') {
          newDiscoveredJoins.push({
            userId: memberUpdate.new_chat_member.user.id,
            userName: memberUpdate.new_chat_member.user.first_name + (memberUpdate.new_chat_member.user.last_name ? ` ${memberUpdate.new_chat_member.user.last_name}` : ''),
            chatId: memberUpdate.chat.id,
            chatTitle: memberUpdate.chat.title,
            timestamp: memberUpdate.date ? memberUpdate.date * 1000 : Date.now()
          });
        }
      });

      // Update Groups list automatically if new ones are found
      if (newDiscoveredGroups.size > 0) {
        const currentIds = new Set(groups.map(g => g.id));
        const addedGroups: TelegramGroup[] = [];

        for (const [id, title] of newDiscoveredGroups.entries()) {
          const stringId = id.toString();
          if (!currentIds.has(stringId)) {
            try {
              const count = await getChatMemberCount(currentToken, stringId);
              addedGroups.push({
                id: stringId,
                name: title,
                memberCount: count,
                description: 'Auto-discovered hub',
                category: 'Telegram',
                image: `https://picsum.photos/seed/${id}/200`,
                lastInteraction: Date.now()
              });
            } catch (e) { 
              // Fallback if member count can't be fetched
              addedGroups.push({
                id: stringId,
                name: title,
                memberCount: 0,
                description: 'Discovery pending permissions',
                category: 'Telegram',
                image: `https://picsum.photos/seed/${id}/200`,
                lastInteraction: Date.now()
              });
            }
          }
        }

        if (addedGroups.length > 0) {
          const updated = [...addedGroups, ...groups];
          setGroups(updated);
          localStorage.setItem('tg_groups', JSON.stringify(updated));
        }
      }

      // Record new join events
      if (newDiscoveredJoins.length > 0) {
        setJoinEvents(prev => {
          const merged = [...newDiscoveredJoins, ...prev];
          const unique = merged.filter((v, i, a) => a.findIndex(t => (t.userId === v.userId && t.timestamp === v.timestamp)) === i);
          return unique.slice(0, 1000); // Keep last 1000 events
        });
      }

      setLastUpdateId(maxId);
    } catch (e) {
      console.error("Scanning failed", e);
    } finally {
      setIsScanning(false);
    }
  };

  const handleKickConfirm = (eventId: string) => {
    setPendingKick(prev => prev === eventId ? null : eventId);
  };

  const handleExecuteKick = async (chatId: number, userId: number, eventId: string) => {
    if (!token) return;
    try {
      await kickChatMember(token, chatId, userId);
      setJoinEvents(prev => prev.filter(e => `${e.userId}-${e.timestamp}` !== eventId));
      setPendingKick(null);
      refreshMemberCounts(token);
    } catch (err: any) {
      alert(`Action failed: ${err.message}`);
      setPendingKick(null);
    }
  };

  const refreshMemberCounts = async (currentToken: string) => {
    if (!currentToken || groups.length === 0) return;
    setIsRefreshing(true);
    const updatedGroupsPromises = groups.map(async (group) => {
        try {
            const memberCount = await getChatMemberCount(currentToken, group.id);
            return { ...group, memberCount };
        } catch (e) { return group; }
    });
    const updatedGroups = await Promise.all(updatedGroupsPromises);
    setGroups(updatedGroups);
    localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
    setIsRefreshing(false);
  };

  const handleExport = () => {
    const data = { groups, joinEvents, lastUpdateId };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `telebridge-backup-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);
        if (data.groups) {
          setGroups(data.groups);
          localStorage.setItem('tg_groups', JSON.stringify(data.groups));
        }
        if (data.joinEvents) {
          setJoinEvents(data.joinEvents);
          localStorage.setItem('tg_join_events', JSON.stringify(data.joinEvents));
        }
        if (data.lastUpdateId) {
          setLastUpdateId(Number(data.lastUpdateId));
        }
        alert('Data restored successfully.');
      } catch (err) {
        alert('Invalid backup file.');
      }
    };
    reader.readAsText(file);
    if (event.target) event.target.value = '';
  };

  const filteredJoinsByDate = useMemo(() => {
    return joinEvents.filter(e => {
      const d = new Date(e.timestamp).toISOString().split('T')[0];
      return d === selectedDate;
    }).sort((a, b) => b.timestamp - a.timestamp);
  }, [joinEvents, selectedDate]);

  const joinsTodayCount = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === today).length;
  }, [joinEvents]);

  const filteredGroups = useMemo(() => {
    return groups.filter(g => 
      g.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      g.id.includes(searchQuery)
    ).sort((a, b) => (b.lastInteraction || 0) - (a.lastInteraction || 0));
  }, [groups, searchQuery]);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans transition-colors duration-300">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} theme={theme} toggleTheme={toggleTheme} />

      <main className="flex-1 md:ml-64 p-4 md:p-10 pb-24 md:pb-8">
        <header className="flex flex-col gap-6 mb-10">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[10px] font-extrabold text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em] mb-1">Central Intelligence</p>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">{activeTab}</h1>
            </div>

            <div className="flex items-center gap-2 md:gap-3">
               <button 
                 onClick={toggleTheme} 
                 className="p-2.5 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl text-slate-500 hover:text-blue-500 transition-all shadow-sm active:scale-95"
               >
                 {theme === 'dark' ? <Icons.Sun size={20} /> : <Icons.Moon size={20} />}
               </button>
               <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm">
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
                 <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest truncate max-w-[120px]">
                   {botInfo ? `@${botInfo.username}` : 'Disconnected'}
                 </span>
               </div>
               <button 
                 onClick={() => discoverGroupsAndJoins(token)} 
                 className="p-2.5 text-slate-400 hover:text-blue-500 transition-all bg-white dark:bg-slate-900 rounded-xl border border-slate-200 dark:border-slate-800 active:scale-95 shadow-sm"
                 title="Scan Workspace"
               >
                  <Icons.Zap size={20} className={isScanning ? 'animate-spin text-blue-500' : ''} />
               </button>
            </div>
          </div>

          {activeTab !== 'settings' && activeTab !== 'analysis' && (
            <div className="flex flex-col md:flex-row items-center gap-4 p-2 bg-slate-200/50 dark:bg-slate-900/50 rounded-2xl border border-slate-300/30 dark:border-slate-800/50">
              <div className="relative w-full md:flex-1">
                <Icons.Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 dark:text-slate-600" />
                <input type="text" placeholder="Search synced hubs..." className="bg-transparent text-slate-900 dark:text-white pl-10 pr-4 py-3 rounded-xl w-full text-sm outline-none placeholder-slate-500" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              </div>
              <button 
                onClick={() => discoverGroupsAndJoins(token)} 
                disabled={isScanning || !botInfo} 
                className="w-full md:w-auto px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg active:scale-95"
              >
                {isScanning ? 'Syncing Hubs...' : 'Scan All Groups'}
              </button>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/5 border border-rose-500/20 text-rose-600 dark:text-rose-400 rounded-2xl text-[11px] font-bold uppercase tracking-wider flex items-center gap-3 animate-in fade-in slide-in-from-top-1">
             <div className="w-2 h-2 rounded-full bg-rose-500" />
             {error}
          </div>
        )}

        <div className="space-y-12">
          {activeTab === 'dashboard' && (
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                  <p className="text-[10px] font-extrabold text-slate-400 uppercase mb-2 tracking-widest">Active Hubs</p>
                  <p className="text-3xl font-black">{groups.length}</p>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                  <p className="text-[10px] font-extrabold text-slate-400 uppercase mb-2 tracking-widest">Global Reach</p>
                  <p className="text-3xl font-black">{totalMembers.toLocaleString()}</p>
               </div>
               <div className="bg-white dark:bg-slate-900/50 p-6 rounded-3xl border border-slate-200 dark:border-slate-800 shadow-sm">
                  <p className="text-[10px] font-extrabold text-blue-500 uppercase mb-2 tracking-widest">Joins Today</p>
                  <p className="text-3xl font-black">{joinsTodayCount}</p>
               </div>
               <div className={`p-6 rounded-3xl border shadow-xl transition-all duration-500 ${isScanning ? 'bg-blue-600 border-blue-400/20 shadow-blue-500/30' : 'bg-slate-900 border-slate-800'}`}>
                  <p className={`text-[10px] font-extrabold uppercase mb-2 tracking-widest ${isScanning ? 'text-blue-100' : 'text-slate-500'}`}>System Engine</p>
                  <div className="flex items-center gap-2">
                    {isScanning && <Icons.Refresh size={18} className="animate-spin text-white" />}
                    <p className="text-lg font-bold text-white">{isScanning ? 'Auto-Syncing Workspace' : 'Ready to Connect'}</p>
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'groups' && (
            <section className="animate-in fade-in slide-in-from-bottom-2">
              <div className="flex items-center justify-between mb-8">
                <h2 className="text-xs font-extrabold text-slate-400 uppercase tracking-[0.2em]">Group Directory</h2>
                <div className="flex items-center gap-2">
                  <button onClick={() => refreshMemberCounts(token)} disabled={isRefreshing} className="p-2 text-slate-400 hover:text-blue-500 transition-all">
                    <Icons.Refresh size={16} className={isRefreshing ? 'animate-spin' : ''} />
                  </button>
                  <span className="text-[10px] font-bold text-slate-400">{filteredGroups.length} synced</span>
                </div>
              </div>
              {filteredGroups.length > 0 ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {filteredGroups.map((group, idx) => (
                    <GroupCard key={group.id} group={group} isPriority={idx === 0 && !!group.lastInteraction} onClick={(g) => setSelectedGroup(g)} />
                  ))}
                </div>
              ) : (
                <div className="text-center py-20 bg-white dark:bg-slate-900/20 rounded-[2.5rem] border border-dashed border-slate-200 dark:border-slate-800">
                   <p className="text-sm text-slate-400">No groups found. Bot connection and "Deep Scan" required.</p>
                </div>
              )}
            </section>
          )}

          {activeTab === 'analysis' && (
            <div className="space-y-8 animate-in fade-in">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 flex flex-col md:flex-row items-start md:items-center justify-between gap-4 bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm">
                  <div>
                    <h2 className="text-xl font-black">Join History Explorer</h2>
                    <p className="text-xs text-slate-500 mt-1">Select a date to audit member records</p>
                  </div>
                  <div className="flex items-center gap-3 w-full md:w-auto">
                    <input 
                      type="date" 
                      value={selectedDate} 
                      onChange={(e) => setSelectedDate(e.target.value)}
                      max={new Date().toISOString().split('T')[0]}
                      className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-5 py-3 rounded-2xl text-sm font-bold outline-none cursor-pointer hover:border-blue-500/50 transition-all"
                    />
                    <button 
                      onClick={() => discoverGroupsAndJoins(token)} 
                      className="p-3.5 bg-blue-600 text-white rounded-2xl shadow-lg active:scale-95 transition-all"
                    >
                      <Icons.Refresh size={20} className={isScanning ? 'animate-spin' : ''} />
                    </button>
                  </div>
                </div>

                <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-8 rounded-[2.5rem] text-white shadow-xl shadow-blue-500/20 flex flex-col justify-center">
                   <p className="text-[10px] font-black uppercase tracking-widest mb-1 opacity-70">Records on {selectedDate}</p>
                   <p className="text-4xl font-black">{filteredJoinsByDate.length}</p>
                   <p className="text-xs font-medium mt-2 opacity-90">Detected join events</p>
                </div>
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] overflow-hidden shadow-xl">
                 <div className="p-8 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center bg-slate-50/50 dark:bg-slate-950/20">
                    <h2 className="text-lg font-black">{selectedDate === new Date().toISOString().split('T')[0] ? 'Live Feed' : `Join Log: ${selectedDate}`}</h2>
                    <div className="px-4 py-2 bg-slate-900 dark:bg-white text-white dark:text-slate-900 text-[10px] font-black uppercase rounded-xl">Audit Log</div>
                 </div>

                 <div className="overflow-x-auto">
                    <table className="w-full text-left">
                       <thead>
                          <tr className="border-b border-slate-100 dark:border-slate-800 bg-slate-50/30 dark:bg-slate-950/10">
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">User</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Hub</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Timestamp</th>
                             <th className="px-8 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Actions</th>
                          </tr>
                       </thead>
                       <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                          {filteredJoinsByDate.length > 0 ? filteredJoinsByDate.map((event) => {
                            const eventId = `${event.userId}-${event.timestamp}`;
                            const isPending = pendingKick === eventId;
                            return (
                              <tr key={eventId} className="hover:bg-slate-50 dark:hover:bg-slate-800/50 transition-colors">
                                <td className="px-8 py-6">
                                  <div className="flex items-center gap-3">
                                      <div className="w-10 h-10 bg-slate-100 dark:bg-slate-800 rounded-full flex items-center justify-center text-slate-400 font-black text-xs">
                                        {event.userName.charAt(0)}
                                      </div>
                                      <span className="text-sm font-bold">{event.userName}</span>
                                  </div>
                                </td>
                                <td className="px-8 py-6">
                                  <span className="px-3 py-1 bg-slate-100 dark:bg-slate-800 text-xs rounded-lg font-medium">{event.chatTitle}</span>
                                </td>
                                <td className="px-8 py-6 text-xs text-slate-400 font-mono">
                                  {new Date(event.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                </td>
                                <td className="px-8 py-6 text-right">
                                  {isPending ? (
                                    <div className="flex items-center justify-end gap-2 animate-in slide-in-from-right-2">
                                      <button 
                                        onClick={() => handleExecuteKick(event.chatId, event.userId, eventId)}
