              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <div className="flex items-start justify-between mb-10">
                  <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-blue-600/10 rounded-2xl flex items-center justify-center text-blue-600 shadow-inner">
                      <Icons.Zap size={28} />
                    </div>
                    <div>
                      <h2 className="text-2xl font-black">Node Connection</h2>
                      <p className="text-sm text-slate-500">BotFather Token Management</p>
                    </div>
                  </div>
                  <button onClick={() => setIsLocked(!isLocked)} className={`flex items-center gap-2 px-4 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${ isLocked ? 'bg-rose-500/10 text-rose-500' : 'bg-emerald-500/10 text-emerald-500' }`}>
                    <Icons.Check size={14} /> {isLocked ? 'Immutable' : 'Unlocked'}
                  </button>
                </div>
                <div className="space-y-4">
                    <label className="text-[10px] font-extrabold text-slate-400 uppercase tracking-widest">Bot API Token</label>
                    <input type="password" placeholder="Paste bot token..." disabled={isLocked} className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-6 py-5 rounded-2xl text-sm font-mono text-blue-600 dark:text-blue-400 outline-none focus:ring-4 focus:ring-blue-500/10 transition-all disabled:opacity-50" value={token} onChange={(e) => setToken(e.target.value)} />
                </div>
                {!isLocked && (
                    <div className="flex flex-col sm:flex-row gap-4 pt-8">
                      <button onClick={() => handleVerify(token)} disabled={isVerifying} className="flex-1 px-8 py-5 bg-blue-600 hover:bg-blue-500 text-white text-sm font-black rounded-2xl transition-all active:scale-[0.98] shadow-xl">
                        {isVerifying ? 'Verifying Node...' : 'Connect and Discovery'}
                      </button>
                      <button onClick={() => { setToken(''); setBotInfo(null); localStorage.removeItem('tg_bot_token'); }} className="px-8 py-5 bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 text-sm font-black rounded-2xl hover:text-rose-500 transition-all">
                        Reset System
