                    </div>
                )}
              </div>

              <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
                <div className="flex items-center justify-between mb-8">
                  <h2 className="text-2xl font-black">Storage & Backup</h2>
                  <div className="flex items-center gap-2">
                    <button onClick={handleExport} className="p-3 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-200 rounded-xl hover:text-blue-500 transition-all" title="Backup">
                      <Icons.DownloadCloud size={20} />
                    </button>
                    <button onClick={() => importFileRef.current?.click()} className="p-3 bg-slate-50 dark:bg-slate-800 text-slate-600 dark:text-slate-200 rounded-xl hover:text-blue-500 transition-all" title="Restore">
                      <Icons.UploadCloud size={20} />
                    </button>
                    <input type="file" ref={importFileRef} onChange={handleImport} accept=".json" className="hidden" />
                  </div>
                </div>
                <div className="p-6 bg-amber-500/5 border border-amber-500/10 rounded-2xl">
                   <p className="text-[11px] font-bold text-amber-600 uppercase tracking-wider mb-2">Notice</p>
                   <p className="text-xs text-slate-600 dark:text-slate-400">All discoveries and join logs are stored locally. Clearing your browser cache will erase this history unless exported.</p>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

