import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar.tsx';
import GroupCard from './components/GroupCard.tsx';
import InviteModal from './components/InviteModal.tsx';
import { Icons } from './constants.tsx';
import { TelegramGroup } from './types.ts';
import { verifyBotToken, getChatDetails, TelegramBotInfo, getChatMemberCount } from './services/telegramService.ts';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    if (saved) return saved as 'light' | 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || '');
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isLocked, setIsLocked] = useState(() => localStorage.getItem('tg_token_locked') === 'true');
  const [groups, setGroups] = useState<TelegramGroup[]>(() => {
    const saved = localStorage.getItem('tg_groups');
    return saved ? JSON.parse(saved) : [];
  });
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const importFileRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  useEffect(() => {
    const root = window.document.documentElement;
    root.classList.remove('light', 'dark');
    root.classList.add(theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => {
    localStorage.setItem('tg_token_locked', isLocked.toString());
  }, [isLocked]);

  const toggleTheme = () => {
    setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));
  };

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
      refreshMemberCounts(testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const refreshMemberCounts = async (currentToken: string) => {
    if (!currentToken || groups.length === 0) return;
    setIsRefreshing(true);
    const updatedGroupsPromises = groups.map(async (group) => {
        try {
            const memberCount = await getChatMemberCount(currentToken, group.id);
            return { ...group, memberCount };
        } catch (e) { return group; }
    });
    const updatedGroups = await Promise.all(updatedGroupsPromises);
    setGroups(updatedGroups);
    localStorage.setItem('tg_groups', JSON.stringify(updatedGroups));
    setIsRefreshing(false);
  };

  const handleAddGroup = async () => {
    if (!token || !newChatId) return;
    setIsAddingGroup(true);
    setError(null);
    try {
      const chat = await getChatDetails(token, newChatId);
      const memberCount = await getChatMemberCount(token, newChatId);

      const newGroup: TelegramGroup = {
        id: chat.id.toString(),
        name: chat.title,
        memberCount: memberCount,
        description: chat.description || 'Synced Telegram Group',
        category: 'Telegram',
        image: `https://picsum.photos/seed/${chat.id}/200`,
        lastInteraction: Date.now()
      };

      const updated = [newGroup, ...groups.filter(g => g.id !== newGroup.id)];
      setGroups(updated);
      localStorage.setItem('tg_groups', JSON.stringify(updated));
      setNewChatId('');
      alert('Group synced successfully!');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAddingGroup(false);
    }
  };

  const handleExport = () => {
    const data = { groups };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `telebridge-backup-${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const content = e.target?.result as string;
        const data = JSON.parse(content);
        if (data.groups) {
          setGroups(data.groups);
          localStorage.setItem('tg_groups', JSON.stringify(data.groups));
          alert('Configuration restored!');
        }
      } catch (err) {
        alert('Failed to import config.');
      }
    };
    reader.readAsText(file);
    if (event.target) event.target.value = '';
  };

  const totalMembers = useMemo(() => groups.reduce((sum, g) => sum + (g.memberCount || 0), 0), [groups]);

  const filteredGroups = useMemo(() => {
    return groups.filter(g => 
      g.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      g.id.includes(searchQuery)
    ).sort((a, b) => (b.lastInteraction || 0) - (a.lastInteraction || 0));
  }, [groups, searchQuery]);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans transition-colors duration-300">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} theme={theme} toggleTheme={toggleTheme} />

      <main className="flex-1 md:ml-64 p-4 md:p-10 pb-24 md:pb-8">
        <header className="flex flex-col gap-6 mb-10">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[10px] font-extrabold text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em] mb-1">Bridge Admin</p>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">{activeTab}</h1>
            </div>

            <div className="flex items-center gap-2">
               <div className="hidden sm:flex items-center gap-2 px-4 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm">
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 animate-pulse' : 'bg-rose-500'}`} />
                 <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-widest">
                   {botInfo ? `@${botInfo.username}` : 'Offline'}
                 </span>
               </div>
            </div>
          </div>

          {activeTab === 'groups' && (
            <div className="flex flex-col md:flex-row items-center gap-4 p-2 bg-white/50 dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-slate-800">
              <div className="relative w-full md:flex-1">
                <Icons.Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                <input type="text" placeholder="Search hubs..." className="bg-transparent text-slate-900 dark:text-white pl-10 pr-4 py-3 rounded-xl w-full text-sm outline-none" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              </div>
              <div className="flex items-center gap-2 w-full md:w-auto">
                <input 
                  type="text" 
                  placeholder="Chat ID (e.g. -100...)" 
                  className="flex-1 md:w-48 bg-white dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-4 py-3 rounded-xl text-xs outline-none focus:ring-2 focus:ring-blue-500/20" 
                  value={newChatId}
                  onChange={(e) => setNewChatId(e.target.value)}
                />
                <button 
                  onClick={handleAddGroup}
                  disabled={isAddingGroup || !token || !newChatId}
                  className="px-6 py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-30 text-white text-xs font-bold rounded-xl transition-all shadow-lg active:scale-95 whitespace-nowrap"
                >
                  {isAddingGroup ? 'Syncing...' : 'Add Group'}
                </button>
              </div>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/10 border border-rose-500/20 text-rose-600 dark:text-rose-400 rounded-2xl text-xs font-bold flex items-center gap-3">
             <div className="w-2 h-2 rounded-full bg-rose-500" />
             {error}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
             <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Connected Hubs</p>
                <p className="text-4xl font-black">{groups.length}</p>
             </div>
             <div className="bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Total Reach</p>
                <p className="text-4xl font-black">{totalMembers.toLocaleString()}</p>
             </div>
             <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-8 rounded-[2.5rem] text-white shadow-xl shadow-blue-500/20">
                <p className="text-[10px] font-black text-blue-100 uppercase tracking-widest mb-2">System Status</p>
                <p className="text-xl font-bold flex items-center gap-2">
                  <Icons.Check size={20} />
                  {botInfo ? 'Operational' : 'Waiting for Node'}
                </p>
             </div>
          </div>
        )}

        {activeTab === 'groups' && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 animate-in fade-in">
            {filteredGroups.map((group) => (
              <GroupCard key={group.id} group={group} onClick={(g) => setSelectedGroup(g)} />
            ))}
            {filteredGroups.length === 0 && (
              <div className="col-span-full py-20 text-center text-slate-400 italic text-sm">
                No hubs synced yet. Add one using the ID bar above.
              </div>
            )}
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="max-w-2xl space-y-8 animate-in slide-in-from-bottom-4">
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
               <h2 className="text-2xl font-black mb-8">Bot Configuration</h2>
               <div className="space-y-6">
                  <div>
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-2">Bot Token</label>
                    <input 
                      type="password" 
                      placeholder="BotFather Token..." 
                      disabled={isLocked}
                      className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-6 py-5 rounded-2xl text-sm font-mono outline-none focus:ring-4 focus:ring-blue-500/10 transition-all disabled:opacity-50" 
                      value={token} 
                      onChange={(e) => setToken(e.target.value)} 
                    />
                  </div>
                  <div className="flex gap-4">
                    <button 
                      onClick={() => handleVerify(token)} 
                      disabled={isVerifying || isLocked}
                      className="flex-1 py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl text-sm font-black transition-all shadow-lg active:scale-95"
                    >
                      {isVerifying ? 'Verifying...' : 'Test Connection'}
                    </button>
                    <button 
                      onClick={() => setIsLocked(!isLocked)}
                      className={`px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${isLocked ? 'bg-rose-500/10 text-rose-500' : 'bg-slate-100 dark:bg-slate-800'}`}
                    >
                      {isLocked ? 'Unlock' : 'Lock'}
                    </button>
                  </div>
               </div>
            </div>

            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2.5rem] p-8 md:p-12 shadow-xl">
               <h2 className="text-2xl font-black mb-8">Persistence</h2>
               <div className="flex items-center gap-4">
                  <button onClick={handleExport} className="flex-1 flex items-center justify-center gap-2 py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-sm font-bold hover:bg-blue-600 hover:text-white transition-all">
                    <Icons.DownloadCloud size={18} /> Backup
                  </button>
                  <button onClick={() => importFileRef.current?.click()} className="flex-1 flex items-center justify-center gap-2 py-4 bg-slate-100 dark:bg-slate-800 rounded-2xl text-sm font-bold hover:bg-blue-600 hover:text-white transition-all">
                    <Icons.UploadCloud size={18} /> Restore
                  </button>
                  <input type="file" ref={importFileRef} onChange={handleImport} accept=".json" className="hidden" />
               </div>
            </div>
          </div>
        )}
      </main>

      {selectedGroup && (
        <InviteModal 
          group={selectedGroup} 
          onClose={() => setSelectedGroup(null)} 
          botToken={token}
        />
      )}
    </div>
  );
};

