               </div>
               <div className={`p-6 rounded-3xl border shadow-xl transition-all duration-500 ${isScanning ? 'bg-blue-600 border-blue-400/20 shadow-blue-500/30' : 'bg-slate-900 border-slate-800 shadow-black/20'}`}>
                  <p className={`text-[10px] font-extrabold uppercase mb-2 tracking-widest ${isScanning ? 'text-blue-100' : 'text-slate-500'}`}>Scanner Status</p>
                  <p className="text-lg font-bold text-white flex items-center gap-2">
                    {isScanning && <Icons.Refresh size={18} className="animate-spin" />}
                    {isScanning ? 'Discovering Hubs...' : 'Idle - Ready to Scan'}
                  </p>
               </div>
            </div>
          )}

          {activeTab === 'groups' && (
            <section className="animate-in fade-in slide-in-from-bottom-2">
              <div className="flex items-center justify-between mb-8">
                <h2 className="text-xs font-extrabold text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em]">Group Directory</h2>
                <div className="flex items-center gap-2">
                  <button onClick={() => refreshMemberCounts(token)} disabled={isRefreshing} className="p-2 text-slate-400 hover:text-blue-500 transition-all">
                    <Icons.Refresh size={16} className={isRefreshing ? 'animate-spin' : ''} />
                  </button>
                  <span className="text-[10px] font-bold text-slate-400">{filteredGroups.length} synced</span>
                </div>
              </div>
              {filteredGroups.length > 0 ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                  {filteredGroups.map((group, idx) => (
                    <GroupCard key={group.id} group={group} isPriority={idx === 0 && !!group.lastInteraction} onClick={(g) => { setSelectedGroup(g); }} />
