                   <p className="text-sm text-slate-400">No groups found. Try a "Deep Scan" to auto-discover groups where the bot is active.</p>
                </div>
              )}
            </section>
          )}

          {activeTab === 'analysis' && (
            <div className="space-y-8 animate-in fade-in">
              <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                <div className="lg:col-span-2 flex flex-col md:flex-row items-start md:items-center justify-between gap-4 bg-white dark:bg-slate-900 p-8 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 shadow-sm">
                  <div>
                    <h2 className="text-xl font-black">History Explorer</h2>
                    <p className="text-xs text-slate-500 mt-1">Audit member growth for specific dates</p>
                  </div>
                  <div className="flex items-center gap-3 w-full md:w-auto">
                    <input 
                      type="date" 
                      value={selectedDate} 
                      onChange={(e) => setSelectedDate(e.target.value)}
                      className="bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-5 py-3 rounded-2xl text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500/20 transition-all cursor-pointer"
                    />
                    <button 
                      onClick={() => discoverGroupsAndJoins(token)} 
                      className="p-3.5 bg-blue-600 text-white rounded-2xl shadow-lg shadow-blue-500/20 active:scale-95 transition-all"
