               </button>
            </div>
          </div>

          {(activeTab === 'groups' || activeTab === 'dashboard') && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
              <div className="relative group flex-1">
                <Icons.Search size={18} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                <input 
