import React, { useState } from 'react';
import { TelegramGroup } from '../types.ts';
import { Icons } from '../constants.tsx';

interface GroupCardProps {
  group: TelegramGroup;
  isPriority?: boolean;
  onClick: (group: TelegramGroup) => void;
}

const GroupCard: React.FC<GroupCardProps> = ({ group, isPriority, onClick }) => {
  const [copied, setCopied] = useState(false);

  const copyId = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(group.id);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div 
      onClick={() => onClick(group)}
      className="group relative bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-[2rem] p-6 flex flex-col gap-5 hover:border-blue-500/50 hover:bg-slate-50 dark:hover:bg-slate-800/40 transition-all duration-500 cursor-pointer shadow-[0_4px_20px_-10px_rgba(0,0,0,0.1)] hover:shadow-[0_20px_40px_-15px_rgba(37,99,235,0.15)] active:scale-[0.98]"
    >
      {isPriority && (
        <div className="absolute top-4 right-4 px-3 py-1 bg-blue-600 text-white text-[9px] font-black uppercase tracking-[0.2em] rounded-full shadow-xl shadow-blue-600/30 z-10">
          Recent
        </div>
      )}

      <div className="flex items-start gap-4">
        <div className="w-16 h-16 rounded-2xl overflow-hidden bg-slate-100 dark:bg-slate-800 flex-shrink-0 shadow-inner group-hover:scale-105 transition-transform duration-500 border border-slate-100 dark:border-slate-800">
          <img 
            src={group.image} 
            alt={group.name} 
            className="w-full h-full object-cover grayscale-[0.1] group-hover:grayscale-0 transition-all"
            loading="lazy"
          />
        </div>

        <div className="flex-1 min-w-0 pt-1">
          <h3 className="text-lg font-black text-slate-900 dark:text-white tracking-tight leading-tight mb-1 group-hover:text-blue-600 transition-colors">{group.name}</h3>
          <div className="flex items-center gap-2 text-slate-400 dark:text-slate-500">
            <Icons.Users size={12} strokeWidth={3} />
            <span className="text-[10px] font-black uppercase tracking-widest">{group.memberCount.toLocaleString()} members</span>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between mt-2 pt-5 border-t border-slate-100 dark:border-slate-800/60">
        <button 
          onClick={copyId}
          className="flex items-center gap-2 group/id px-3 py-2 bg-slate-50 dark:bg-slate-800/50 rounded-xl hover:bg-blue-600/10 transition-colors"
        >
          <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest group-hover/id:text-blue-600 transition-colors">
            ID: {group.id.length > 12 ? `${group.id.substring(0, 10)}...` : group.id}
          </span>
          <Icons.Copy size={12} className={`transition-all ${copied ? 'scale-125 text-emerald-500' : 'text-slate-300 group-hover/id:text-blue-400'}`} />
        </button>

        <div className="w-10 h-10 bg-slate-50 dark:bg-slate-800 rounded-xl flex items-center justify-center text-slate-400 dark:text-slate-600 group-hover:bg-blue-600 group-hover:text-white transition-all duration-500 shadow-sm">
          <Icons.Link size={20} />
        </div>
      </div>
    </div>
  );
};

export default GroupCard;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import Sidebar from './components/Sidebar.tsx';
import GroupCard from './components/GroupCard.tsx';
import InviteModal from './components/InviteModal.tsx';
import { Icons } from './constants.tsx';
import { TelegramGroup, JoinEvent } from './types.ts';
import { verifyBotToken, getChatDetails, TelegramBotInfo, getChatMemberCount, getRecentUpdates, kickChatMember } from './services/telegramService.ts';

const DEFAULT_TOKEN = '8357993008:AAGCcWUfCrRboCCnUS3N3kHS53PvAPIMwxs';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedGroup, setSelectedGroup] = useState<TelegramGroup | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedDate, setSelectedDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [theme, setTheme] = useState<'light' | 'dark'>(() => {
    const saved = localStorage.getItem('theme');
    if (saved) return saved as 'light' | 'dark';
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [token, setToken] = useState(localStorage.getItem('tg_bot_token') || DEFAULT_TOKEN);
  const [botInfo, setBotInfo] = useState<TelegramBotInfo | null>(null);
  const [isVerifying, setIsVerifying] = useState(false);
  const [isLocked, setIsLocked] = useState(() => localStorage.getItem('tg_token_locked') === 'true');
  const [groups, setGroups] = useState<TelegramGroup[]>(() => {
    const saved = localStorage.getItem('tg_groups');
    return saved ? JSON.parse(saved) : [];
  });
  const [newChatId, setNewChatId] = useState('');
  const [isAddingGroup, setIsAddingGroup] = useState(false);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [totalMembers, setTotalMembers] = useState(0);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [joinEvents, setJoinEvents] = useState<JoinEvent[]>(() => {
    const saved = localStorage.getItem('tg_join_events');
    return saved ? JSON.parse(saved) : [];
  });
  const [lastUpdateId, setLastUpdateId] = useState(() => Number(localStorage.getItem('tg_last_update_id')) || 0);
  const [pendingKick, setPendingKick] = useState<string | null>(null);

  const importFileRef = useRef<HTMLInputElement>(null);

  // Initial verification
  useEffect(() => {
    if (token) {
      handleVerify(token);
    }
  }, []);

  // Calculate total reach
  useEffect(() => {
    const total = groups.reduce((sum, group) => sum + (group.memberCount || 0), 0);
    setTotalMembers(total);
  }, [groups]);

  // Handle Theme Toggling on HTML Element
  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
      root.classList.remove('light');
    } else {
      root.classList.add('light');
      root.classList.remove('dark');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  // Persist State
  useEffect(() => localStorage.setItem('tg_token_locked', isLocked.toString()), [isLocked]);
  useEffect(() => localStorage.setItem('tg_join_events', JSON.stringify(joinEvents)), [joinEvents]);
  useEffect(() => localStorage.setItem('tg_last_update_id', lastUpdateId.toString()), [lastUpdateId]);
  useEffect(() => localStorage.setItem('tg_groups', JSON.stringify(groups)), [groups]);

  const toggleTheme = () => setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
      refreshMemberCounts(testToken);
      discoverGroupsAndJoins(testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const handleAddGroupManual = async () => {
    if (!token || !newChatId) return;
    setIsAddingGroup(true);
    setError(null);
    try {
      const chat = await getChatDetails(token, newChatId);
      const count = await getChatMemberCount(token, newChatId);

      const newGroup: TelegramGroup = {
        id: chat.id.toString(),
        name: chat.title,
        memberCount: count,
        description: chat.description || 'Manually added hub',
        category: 'Telegram',
        image: `https://picsum.photos/seed/${chat.id}/200`,
        lastInteraction: Date.now()
      };

      setGroups(prev => {
        const filtered = prev.filter(g => g.id !== newGroup.id);
        return [newGroup, ...filtered];
      });
      setNewChatId('');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAddingGroup(false);
    }
  };

  const discoverGroupsAndJoins = async (currentToken: string) => {
    if (!currentToken || isScanning) return;
    setIsScanning(true);
    try {
      // Offset by 1 to get only NEW updates
      const updates = await getRecentUpdates(currentToken, lastUpdateId + 1);
      const newDiscoveredGroups: Map<number, string> = new Map();
      const newDiscoveredJoins: JoinEvent[] = [];
      let maxId = lastUpdateId;

      updates.forEach(update => {
        maxId = Math.max(maxId, update.update_id);

        // Group discovery
        const chat = update.message?.chat || update.chat_member?.chat || update.my_chat_member?.chat;
        if (chat && (chat.type === 'group' || chat.type === 'supergroup' || chat.type === 'channel')) {
          newDiscoveredGroups.set(chat.id, chat.title || chat.username || 'Unknown Hub');
        }

        // Join tracking
        const memberUpdate = update.chat_member;
        if (memberUpdate && (memberUpdate.new_chat_member?.status === 'member' || memberUpdate.new_chat_member?.status === 'administrator')) {
          newDiscoveredJoins.push({
            userId: memberUpdate.new_chat_member.user.id,
            userName: memberUpdate.new_chat_member.user.first_name + (memberUpdate.new_chat_member.user.last_name ? ` ${memberUpdate.new_chat_member.user.last_name}` : ''),
            chatId: memberUpdate.chat.id,
            chatTitle: memberUpdate.chat.title,
            timestamp: memberUpdate.date ? memberUpdate.date * 1000 : Date.now()
          });
        }
      });

      // Map newly found groups
      if (newDiscoveredGroups.size > 0) {
        const currentIds = new Set(groups.map(g => g.id));
        const addedGroups: TelegramGroup[] = [];
        for (const [id, title] of newDiscoveredGroups.entries()) {
          const stringId = id.toString();
          if (!currentIds.has(stringId)) {
            try {
              const count = await getChatMemberCount(currentToken, stringId);
              addedGroups.push({
                id: stringId,
                name: title,
                memberCount: count,
                description: 'Auto-discovered from bot interaction',
                category: 'Telegram',
                image: `https://picsum.photos/seed/${id}/200`,
                lastInteraction: Date.now()
              });
            } catch (e) { /* ignore restricted chats */ }
          }
        }
        if (addedGroups.length > 0) setGroups(prev => [...addedGroups, ...prev]);
      }

      // Merge join history
      if (newDiscoveredJoins.length > 0) {
        setJoinEvents(prev => {
          const merged = [...newDiscoveredJoins, ...prev];
          const unique = merged.filter((v, i, a) => a.findIndex(t => (t.userId === v.userId && t.timestamp === v.timestamp)) === i);
          return unique.slice(0, 5000); // Increased buffer
        });
      }
      setLastUpdateId(maxId);
    } catch (e) { 
      console.error("Discovery failed", e);
    } finally { 
      setIsScanning(false); 
    }
  };

  const handleKickConfirm = (eventId: string) => setPendingKick(prev => prev === eventId ? null : eventId);

  const handleExecuteKick = async (chatId: number, userId: number, eventId: string) => {
    if (!token) return;
    try {
      await kickChatMember(token, chatId, userId);
      setJoinEvents(prev => prev.filter(e => `${e.userId}-${e.timestamp}` !== eventId));
      setPendingKick(null);
      refreshMemberCounts(token);
    } catch (err: any) {
      alert(`Kick failed: ${err.message}`);
      setPendingKick(null);
    }
  };

  const refreshMemberCounts = async (currentToken: string) => {
    if (!currentToken || groups.length === 0) return;
    setIsRefreshing(true);
    const updatedGroups = await Promise.all(groups.map(async (group) => {
      try {
        const memberCount = await getChatMemberCount(currentToken, group.id);
        return { ...group, memberCount };
      } catch (e) { return group; }
    }));
    setGroups(updatedGroups);
    setIsRefreshing(false);
  };

  // ROBUST IMPORT: Detects older JSON formats and maps them
  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const rawData = JSON.parse(event.target?.result as string);

        // Support legacy keys from previous app versions
        const mappedGroups = rawData.groups || rawData.hubs || [];
        const mappedJoins = rawData.joinEvents || rawData.events || rawData.joins || [];
        const mappedToken = rawData.token || rawData.botToken || token;
        const mappedUpdateId = rawData.lastUpdateId || rawData.cursor || 0;

        if (mappedGroups.length > 0) setGroups(mappedGroups);
        if (mappedJoins.length > 0) setJoinEvents(mappedJoins);
        if (mappedUpdateId) setLastUpdateId(Number(mappedUpdateId));
        if (mappedToken) {
          setToken(mappedToken);
          handleVerify(mappedToken);
        }

        alert(`Successfully restored ${mappedGroups.length} hubs and ${mappedJoins.length} events!`);
      } catch (err) { 
        setError('The selected file is not a valid TeleBridge backup.');
      }
    };
    reader.readAsText(file);
    if (e.target) e.target.value = '';
  };

  const handleExport = () => {
    const data = { groups, joinEvents, lastUpdateId, theme, token, isLocked, exportDate: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `telebridge-backup-${selectedDate}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const filteredJoinsForSelectedDate = useMemo(() => {
    return joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === selectedDate)
      .sort((a, b) => b.timestamp - a.timestamp);
  }, [joinEvents, selectedDate]);

  const joinsToday = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === today).length;
  }, [joinEvents]);

  const filteredGroups = useMemo(() => {
    return groups.filter(g => g.name.toLowerCase().includes(searchQuery.toLowerCase()) || g.id.includes(searchQuery))
      .sort((a, b) => (b.lastInteraction || 0) - (a.lastInteraction || 0));
  }, [groups, searchQuery]);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans selection:bg-blue-500/30 transition-all duration-300">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} theme={theme} toggleTheme={toggleTheme} />

      <main className="flex-1 md:ml-64 p-4 md:p-6 lg:p-10 pb-24 md:pb-8 max-w-[1400px] mx-auto w-full">
        <header className="flex flex-col gap-6 mb-8">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <div className="w-1.5 h-1.5 rounded-full bg-blue-600 dark:bg-blue-400 shadow-[0_0_8px_rgba(37,99,235,0.6)]" />
                <p className="text-[9px] font-black text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em]">TeleBridge Infrastructure</p>
              </div>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">{activeTab}</h1>
            </div>

            <div className="flex items-center gap-2 self-end sm:self-auto">
               <div className="flex items-center gap-2.5 px-4 py-2 bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm backdrop-blur-sm">
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-rose-500 animate-pulse'}`} />
                 <span className="text-[10px] font-black text-slate-600 dark:text-slate-400 tracking-wider">
                   {botInfo ? `@${botInfo.username}` : 'DISCONNECTED'}
                 </span>
               </div>
               <button 
                 onClick={() => discoverGroupsAndJoins(token)} 
                 disabled={isScanning}
                 className="p-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-xl transition-all shadow-lg shadow-blue-500/10 active:scale-90"
                 title="Force Activity Scan"
               >
                 <Icons.Refresh size={18} className={isScanning ? 'animate-spin' : ''} />
               </button>
            </div>
          </div>

          {(activeTab === 'groups' || activeTab === 'dashboard') && (
            <div className="flex flex-col lg:flex-row gap-3">
              <div className="relative group flex-1">
                <Icons.Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                <input 
                  type="text" 
                  placeholder="Filter hubs..." 
                  className="bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 pl-11 pr-4 py-3 rounded-xl w-full text-xs outline-none focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)} 
                />
              </div>
              <div className="flex items-center gap-2 w-full lg:w-auto">
                <input 
                  type="text" 
                  placeholder="Chat ID..." 
                  className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 px-4 py-3 rounded-xl text-xs flex-1 lg:w-48 outline-none focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm" 
                  value={newChatId}
                  onChange={(e) => setNewChatId(e.target.value)}
                />
                <button 
                  onClick={handleAddGroupManual}
                  disabled={isAddingGroup || !newChatId}
                  className="px-5 py-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all hover:opacity-90 active:scale-95 disabled:opacity-30 shadow-lg"
                >
                  {isAddingGroup ? '...' : 'Add'}
                </button>
              </div>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/5 border border-rose-500/20 text-rose-600 dark:text-rose-400 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3 animate-in slide-in-from-top-2">
             <div className="w-2 h-2 rounded-full bg-rose-500" />
             {error}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
             <div className="bg-white dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Hubs</p>
                <p className="text-3xl font-black">{groups.length}</p>
             </div>
             <div className="bg-white dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Reach</p>
                <p className="text-3xl font-black">{totalMembers.toLocaleString()}</p>
             </div>
             <div className="bg-white dark:bg-slate-900/50 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm transition-all hover:shadow-md">
                <p className="text-[9px] font-black text-blue-500 uppercase tracking-widest mb-1">Joins Today</p>
                <p className="text-3xl font-black">{joinsToday}</p>
             </div>
             <div className="bg-slate-900 dark:bg-white p-6 rounded-2xl shadow-xl flex flex-col justify-center">
                <p className="text-[9px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-1">Status</p>
                <p className="text-sm font-black text-white dark:text-slate-900">{botInfo ? 'OPERATIONAL' : 'OFFLINE'}</p>
             </div>
          </div>
        )}

        {activeTab === 'groups' && (
          <div className="space-y-6 animate-in fade-in">
            {filteredGroups.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {filteredGroups.map((group) => (
                  <GroupCard key={group.id} group={group} onClick={(g) => setSelectedGroup(g)} />
                ))}
              </div>
            ) : (
              <div className="py-24 flex flex-col items-center justify-center bg-white/50 dark:bg-slate-900/10 rounded-3xl border border-dashed border-slate-200 dark:border-slate-800 text-center">
                 <h3 className="text-sm font-black text-slate-400">No Groups Synced</h3>
                 <p className="text-xs text-slate-500 mt-1 max-w-xs">Enter a Chat ID or scan updates to discover hubs where the bot is active.</p>
              </div>
            )}
          </div>
