  useEffect(() => {
    const root = window.document.documentElement;
    if (theme === 'dark') {
      root.classList.add('dark');
      root.classList.remove('light');
    } else {
      root.classList.remove('dark');
      root.classList.add('light');
    }
    localStorage.setItem('theme', theme);
  }, [theme]);

  useEffect(() => localStorage.setItem('tg_token_locked', isLocked.toString()), [isLocked]);
  useEffect(() => localStorage.setItem('tg_join_events', JSON.stringify(joinEvents)), [joinEvents]);
  useEffect(() => localStorage.setItem('tg_last_update_id', lastUpdateId.toString()), [lastUpdateId]);
  useEffect(() => localStorage.setItem('tg_groups', JSON.stringify(groups)), [groups]);

  const toggleTheme = () => setTheme(prev => (prev === 'dark' ? 'light' : 'dark'));

  const handleVerify = async (testToken: string) => {
    if (!testToken) return;
    setIsVerifying(true);
    setError(null);
    try {
      const info = await verifyBotToken(testToken);
      setBotInfo(info);
      setToken(testToken);
      localStorage.setItem('tg_bot_token', testToken);
      refreshMemberCounts(testToken);
      discoverGroupsAndJoins(testToken);
    } catch (err: any) {
      setError(err.message);
      setBotInfo(null);
    } finally {
      setIsVerifying(false);
    }
  };

  const handleAddGroupManual = async () => {
    if (!token || !newChatId) return;
    setIsAddingGroup(true);
    setError(null);
    try {
      const chat = await getChatDetails(token, newChatId);
      const count = await getChatMemberCount(token, newChatId);
      const newGroup: TelegramGroup = {
        id: chat.id.toString(),
        name: chat.title,
        memberCount: count,
        description: chat.description || 'Manually added hub',
        category: 'Telegram',
        image: `https://picsum.photos/seed/${chat.id}/200`,
        lastInteraction: Date.now()
      };
      setGroups(prev => {
        const filtered = prev.filter(g => g.id !== newGroup.id);
        return [newGroup, ...filtered];
      });
      setNewChatId('');
    } catch (err: any) {
      setError(err.message);
    } finally {
      setIsAddingGroup(false);
    }
  };

  const discoverGroupsAndJoins = async (currentToken: string) => {
    if (!currentToken || isScanning) return;
    setIsScanning(true);
    try {
      const updates = await getRecentUpdates(currentToken, lastUpdateId + 1);
      const newDiscoveredGroups: Map<number, string> = new Map();
      const newDiscoveredJoins: JoinEvent[] = [];
      let maxId = lastUpdateId;

      updates.forEach(update => {
        maxId = Math.max(maxId, update.update_id);
        const chat = update.message?.chat || update.chat_member?.chat || update.my_chat_member?.chat;
        if (chat && (chat.type === 'group' || chat.type === 'supergroup' || chat.type === 'channel')) {
          newDiscoveredGroups.set(chat.id, chat.title || chat.username || 'Unknown Hub');
        }
        const memberUpdate = update.chat_member;
        if (memberUpdate && (memberUpdate.new_chat_member?.status === 'member' || memberUpdate.new_chat_member?.status === 'administrator')) {
          newDiscoveredJoins.push({
            userId: memberUpdate.new_chat_member.user.id,
            userName: memberUpdate.new_chat_member.user.first_name + (memberUpdate.new_chat_member.user.last_name ? ` ${memberUpdate.new_chat_member.user.last_name}` : ''),
            chatId: memberUpdate.chat.id,
            chatTitle: memberUpdate.chat.title,
            timestamp: memberUpdate.date ? memberUpdate.date * 1000 : Date.now()
          });
        }
      });

      if (newDiscoveredGroups.size > 0) {
        const currentIds = new Set(groups.map(g => g.id));
        const addedGroups: TelegramGroup[] = [];
        for (const [id, title] of newDiscoveredGroups.entries()) {
          const stringId = id.toString();
          if (!currentIds.has(stringId)) {
            try {
              const count = await getChatMemberCount(currentToken, stringId);
              addedGroups.push({
                id: stringId,
                name: title,
                memberCount: count,
                description: 'Auto-discovered',
                category: 'Telegram',
                image: `https://picsum.photos/seed/${id}/200`,
                lastInteraction: Date.now()
              });
            } catch (e) {}
          }
        }
        if (addedGroups.length > 0) setGroups(prev => [...addedGroups, ...prev]);
      }

      if (newDiscoveredJoins.length > 0) {
        setJoinEvents(prev => {
          const merged = [...newDiscoveredJoins, ...prev];
          const unique = merged.filter((v, i, a) => a.findIndex(t => (t.userId === v.userId && t.timestamp === v.timestamp)) === i);
          return unique.slice(0, 10000);
        });
      }
      setLastUpdateId(maxId);
    } catch (e) {} finally { setIsScanning(false); }
  };

  const handleExecuteKick = async (chatId: number, userId: number, eventId: string) => {
    if (!token) return;
    try {
      await kickChatMember(token, chatId, userId);
      setJoinEvents(prev => prev.filter(e => `${e.userId}-${e.timestamp}` !== eventId));
      setPendingKick(null);
      refreshMemberCounts(token);
    } catch (err: any) {
      alert(`Kick failed: ${err.message}`);
      setPendingKick(null);
    }
  };

  const refreshMemberCounts = async (currentToken: string) => {
    if (!currentToken || groups.length === 0) return;
    setIsRefreshing(true);
    const updatedGroups = await Promise.all(groups.map(async (group) => {
      try {
        const memberCount = await getChatMemberCount(currentToken, group.id);
        return { ...group, memberCount };
      } catch (e) { return group; }
    }));
    setGroups(updatedGroups);
    setIsRefreshing(false);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.groups) setGroups(data.groups);
        if (data.joinEvents) setJoinEvents(data.joinEvents);
        if (data.lastUpdateId) setLastUpdateId(Number(data.lastUpdateId));
        if (data.token) { setToken(data.token); handleVerify(data.token); }
        alert('Data Restored!');
      } catch (err) { setError('Import failed'); }
    };
    reader.readAsText(file);
    if (e.target) e.target.value = '';
  };

  const handleExport = () => {
    const data = { groups, joinEvents, lastUpdateId, theme, token, isLocked };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `telebridge-backup-${selectedDate}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const filteredJoinsForSelectedDate = useMemo(() => {
    return joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === selectedDate)
      .sort((a, b) => b.timestamp - a.timestamp);
  }, [joinEvents, selectedDate]);

  const joinsToday = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    return joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === today).length;
  }, [joinEvents]);

  const filteredGroups = useMemo(() => {
    return groups.filter(g => g.name.toLowerCase().includes(searchQuery.toLowerCase()) || g.id.includes(searchQuery))
      .sort((a, b) => (b.lastInteraction || 0) - (a.lastInteraction || 0));
  }, [groups, searchQuery]);

  const handleKickConfirm = (eventId: string) => setPendingKick(prev => prev === eventId ? null : eventId);

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans selection:bg-blue-500/30 transition-all duration-300">
      <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} theme={theme} toggleTheme={toggleTheme} />

      <main className="flex-1 md:ml-64 p-4 md:p-6 lg:p-10 pb-24 md:pb-8 max-w-[1400px] mx-auto w-full">
        {/* Adjusted Gap here - mb-4 instead of mb-8 */}
        <header className="flex flex-col gap-4 mb-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <div>
              <div className="flex items-center gap-2 mb-1">
                <div className="w-1.5 h-1.5 rounded-full bg-blue-600 dark:bg-blue-400 shadow-[0_0_8px_rgba(37,99,235,0.6)]" />
                <p className="text-[9px] font-black text-blue-600 dark:text-blue-400 uppercase tracking-[0.2em]">TeleBridge Portal</p>
              </div>
              <h1 className="text-3xl md:text-4xl font-black text-slate-900 dark:text-white tracking-tight capitalize">{activeTab}</h1>
            </div>

            <div className="flex items-center gap-3 self-end sm:self-auto">
               {/* New Theme Toggle Button at Top */}
               <button 
                 onClick={toggleTheme}
                 className={`p-2.5 rounded-xl transition-all shadow-lg active:scale-90 border flex items-center gap-2 font-black text-[10px] uppercase tracking-widest ${theme === 'dark' ? 'bg-amber-500/10 text-amber-500 border-amber-500/30 shadow-amber-500/20' : 'bg-indigo-600 text-white border-indigo-600 shadow-indigo-600/30'}`}
               >
                 {theme === 'dark' ? <Icons.Sun size={18} /> : <Icons.Moon size={18} />}
                 <span className="hidden sm:inline">{theme === 'dark' ? 'Day' : 'Night'}</span>
               </button>

               <div className="flex items-center gap-2.5 px-4 py-2 bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm backdrop-blur-sm">
                 <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : 'bg-rose-500 animate-pulse'}`} />
                 <span className="text-[10px] font-black text-slate-600 dark:text-slate-400 tracking-wider uppercase">
                   {botInfo ? 'BOT ONLINE' : 'DISCONNECTED'}
                 </span>
               </div>

               <button 
                 onClick={() => discoverGroupsAndJoins(token)} 
                 disabled={isScanning}
                 className="p-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-xl transition-all shadow-xl shadow-blue-600/30 active:scale-90"
                 title="Sync updates"
               >
                 <Icons.Refresh size={18} className={isScanning ? 'animate-spin' : ''} />
               </button>
            </div>
          </div>

          {(activeTab === 'groups' || activeTab === 'dashboard') && (
            <div className="flex flex-col lg:flex-row gap-3">
              <div className="relative group flex-1">
                <Icons.Search size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                <input 
                  type="text" 
                  placeholder="Search synchronized batches..." 
                  className="bg-white dark:bg-slate-900/50 border border-slate-200 dark:border-slate-800 pl-11 pr-4 py-3 rounded-xl w-full text-xs outline-none focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm" 
                  value={searchQuery} 
                  onChange={(e) => setSearchQuery(e.target.value)} 
                />
              </div>
              <div className="flex items-center gap-2 w-full lg:w-auto">
                <input 
                  type="text" 
                  placeholder="New Chat ID..." 
                  className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 px-4 py-3 rounded-xl text-xs flex-1 lg:w-48 outline-none focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm" 
                  value={newChatId}
                  onChange={(e) => setNewChatId(e.target.value)}
                />
                <button 
                  onClick={handleAddGroupManual}
                  disabled={isAddingGroup || !newChatId}
                  className="px-5 py-3 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all hover:opacity-90 active:scale-95 disabled:opacity-30 shadow-lg shadow-slate-900/20 dark:shadow-white/10"
                >
                  {isAddingGroup ? 'Adding...' : 'Add'}
                </button>
              </div>
            </div>
          )}
        </header>

        {error && (
          <div className="mb-6 p-4 bg-rose-500/5 border border-rose-500/20 text-rose-600 dark:text-rose-400 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-3">
             <div className="w-2 h-2 rounded-full bg-rose-500" />
             {error}
          </div>
        )}

        {activeTab === 'dashboard' && (
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
             <div className="bg-indigo-600/10 dark:bg-indigo-500/10 p-6 rounded-2xl border border-indigo-200 dark:border-indigo-800/50 shadow-sm transition-all hover:scale-[1.02] shadow-indigo-500/10">
                <div className="w-10 h-10 bg-indigo-600 text-white rounded-xl flex items-center justify-center mb-4 shadow-lg shadow-indigo-600/30">
                   <Icons.Home size={18} />
                </div>
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Active Hubs</p>
                <p className="text-3xl font-black text-indigo-600 dark:text-indigo-400">{groups.length}</p>
             </div>
             <div className="bg-emerald-600/10 dark:bg-emerald-500/10 p-6 rounded-2xl border border-emerald-200 dark:border-emerald-800/50 shadow-sm transition-all hover:scale-[1.02] shadow-emerald-500/10">
                <div className="w-10 h-10 bg-emerald-600 text-white rounded-xl flex items-center justify-center mb-4 shadow-lg shadow-emerald-600/30">
                   <Icons.Users size={18} />
                </div>
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">Total Reach</p>
                <p className="text-3xl font-black text-emerald-600 dark:text-emerald-400">{totalMembers.toLocaleString()}</p>
             </div>
             <div className="bg-amber-600/10 dark:bg-amber-500/10 p-6 rounded-2xl border border-amber-200 dark:border-amber-800/50 shadow-sm transition-all hover:scale-[1.02] shadow-amber-500/10">
                <div className="w-10 h-10 bg-amber-600 text-white rounded-xl flex items-center justify-center mb-4 shadow-lg shadow-amber-600/30">
                   <Icons.Activity size={18} />
                </div>
                <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-1">New Audits</p>
                <p className="text-3xl font-black text-amber-600 dark:text-amber-400">{joinsToday}</p>
             </div>
             <div className="bg-rose-600/10 dark:bg-rose-500/10 p-6 rounded-2xl border border-rose-200 dark:border-rose-800/50 shadow-sm transition-all hover:scale-[1.02] shadow-rose-500/10">
                <div className="w-10 h-10 bg-rose-600 text-white rounded-xl flex items-center justify-center mb-4 shadow-lg shadow-rose-600/30">
                   <Icons.Zap size={18} />
                </div>
                <p className="text-[9px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest mb-1">System Uplink</p>
                <p className="text-sm font-black text-rose-600 dark:text-rose-400 uppercase tracking-tight leading-none">{botInfo ? 'OPERATIONAL' : 'OFFLINE'}</p>
             </div>
          </div>
        )}

        {activeTab === 'groups' && (
          <div className="space-y-6 animate-in fade-in">
            {filteredGroups.length > 0 ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {filteredGroups.map((group) => (
                  <GroupCard key={group.id} group={group} onClick={(g) => setSelectedGroup(g)} />
                ))}
              </div>
            ) : (
              <div className="py-24 flex flex-col items-center justify-center bg-white/50 dark:bg-slate-900/10 rounded-3xl border border-dashed border-slate-200 dark:border-slate-800 text-center">
                 <h3 className="text-sm font-black text-slate-400">No Batches Synced</h3>
                 <p className="text-xs text-slate-500 mt-1 max-w-xs">Scan updates or manually add IDs to populate your hub.</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'analysis' && (
          <div className="space-y-6 animate-in fade-in">
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
               <div className="lg:col-span-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 p-6 rounded-3xl shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                  <div>
                    <h2 className="text-lg font-black">Audit History</h2>
                    <p className="text-[10px] text-slate-500 font-bold uppercase tracking-wider">Candidate Verification Records</p>
                  </div>
                  <div className="flex items-center gap-2 p-1 bg-slate-100 dark:bg-slate-950 rounded-xl border border-slate-200 dark:border-slate-800">
                    <input 
                      type="date" 
                      value={selectedDate} 
                      onChange={(e) => setSelectedDate(e.target.value)}
                      className="bg-transparent border-none px-4 py-2 text-xs font-black outline-none cursor-pointer"
                    />
                  </div>
               </div>
               <div className="bg-indigo-600 p-6 rounded-3xl text-white shadow-lg shadow-indigo-600/30 flex flex-col justify-center">
                  <p className="text-[9px] font-black uppercase tracking-widest opacity-70 mb-1">Records Found</p>
                  <p className="text-4xl font-black">{filteredJoinsForSelectedDate.length}</p>
               </div>
            </div>

            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl overflow-hidden shadow-xl">
               <div className="overflow-x-auto">
                  <table className="w-full text-left">
                     <thead>
                        <tr className="border-b border-slate-100 dark:border-slate-800">
                           <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Candidate</th>
                           <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Assigned Hub</th>
                           <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Time</th>
                           <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Moderation</th>
                        </tr>
                     </thead>
                     <tbody className="divide-y divide-slate-100 dark:divide-slate-800">
                        {filteredJoinsForSelectedDate.length > 0 ? filteredJoinsForSelectedDate.map((event) => {
                          const eventId = `${event.userId}-${event.timestamp}`;
                          const isPending = pendingKick === eventId;
                          return (
                            <tr key={eventId} className="group hover:bg-slate-50 dark:hover:bg-slate-800/30 transition-colors">
                              <td className="px-6 py-4">
                                <span className="text-xs font-black text-slate-900 dark:text-white">{event.userName}</span>
                              </td>
                              <td className="px-6 py-4">
                                <span className="px-2 py-1 bg-slate-100 dark:bg-slate-800 rounded-lg text-[10px] font-bold text-slate-500">
                                  {event.chatTitle}
                                </span>
                              </td>
                              <td className="px-6 py-4 text-[10px] text-slate-400 font-mono">
                                {new Date(event.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                              </td>
                              <td className="px-6 py-4 text-right">
                                {isPending ? (
                                  <div className="flex items-center justify-end gap-2 animate-in fade-in scale-in-95">
                                    <button 
                                      onClick={() => handleExecuteKick(event.chatId, event.userId, eventId)}
                                      className="px-3 py-1.5 bg-rose-600 text-white text-[9px] font-black uppercase rounded-lg shadow-lg shadow-rose-600/30 active:scale-90 transition-all"
                                    >
                                      Confirm
                                    </button>
                                    <button onClick={() => setPendingKick(null)} className="p-1.5 bg-slate-200 dark:bg-slate-800 text-slate-600 rounded-lg"><Icons.Refresh size={14} /></button>
                                  </div>
                                ) : (
                                  <button 
                                    onClick={() => handleKickConfirm(eventId)}
                                    className="p-2.5 bg-rose-500/10 text-rose-500 hover:bg-rose-500 hover:text-white rounded-xl transition-all active:scale-90 shadow-rose-500/10"
                                  >
                                    <Icons.Trash size={16} />
                                  </button>
                                )}
                              </td>
                            </tr>
                          );
                        }) : (
                           <tr><td colSpan={4} className="px-6 py-20 text-center text-slate-400 text-xs italic font-bold">Zero records detected for this audit cycle.</td></tr>
                        )}
                     </tbody>
                  </table>
               </div>
            </div>
          </div>
        )}

        {activeTab === 'settings' && (
          <div className="max-w-2xl space-y-6 animate-in slide-in-from-bottom-8">
            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-8 shadow-xl">
              <div className="flex items-center gap-4 mb-8">
                <div className="w-12 h-12 bg-indigo-600 text-white rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-600/30">
                  <Icons.Zap size={24} />
                </div>
                <div>
                  <h2 className="text-xl font-black">Node Architecture</h2>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">Active Bot: {botInfo ? `@${botInfo.username}` : 'DISCONNECTED'}</p>
                </div>
              </div>

              <div className="space-y-4">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Secure Uplink Key</label>
                  <input 
                    type="password" 
                    placeholder="Enter Bot Token..." 
                    disabled={isLocked} 
                    className="w-full bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 px-6 py-4 rounded-2xl text-xs font-mono outline-none focus:ring-4 focus:ring-blue-500/5 transition-all shadow-inner" 
                    value={token} 
                    onChange={(e) => setToken(e.target.value)} 
                  />
                  <div className="flex gap-2">
                    <button onClick={() => handleVerify(token)} disabled={isVerifying} className="flex-1 px-6 py-4 bg-blue-600 text-white text-[10px] font-black uppercase rounded-2xl shadow-xl shadow-blue-600/30 active:scale-95 transition-all">
                      {isVerifying ? 'Verifying...' : 'Validate Uplink'}
                    </button>
                    <button onClick={() => setIsLocked(!isLocked)} className={`px-6 py-4 rounded-2xl text-[10px] font-black uppercase active:scale-95 transition-all shadow-lg ${isLocked ? 'bg-amber-500/10 text-amber-600 border border-amber-500/20 shadow-amber-500/10' : 'bg-slate-100 dark:bg-slate-800 text-slate-500 shadow-slate-500/10'}`}>
                      {isLocked ? 'Unlock Config' : 'Lock Config'}
                    </button>
                  </div>
              </div>
            </div>

            <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-3xl p-8 shadow-xl">
               <h3 className="text-sm font-black mb-6">Database Management</h3>
               <div className="flex gap-2">
                  <button onClick={handleExport} className="flex-1 p-4 bg-indigo-600/5 dark:bg-indigo-500/5 text-indigo-600 rounded-2xl flex flex-col items-center gap-2 hover:bg-indigo-600 hover:text-white transition-all shadow-xl shadow-indigo-600/5 hover:shadow-indigo-600/20">
                    <Icons.DownloadCloud size={20} />
                    <span className="text-[9px] font-black uppercase tracking-widest">Export Archive</span>
                  </button>
                  <button onClick={() => importFileRef.current?.click()} className="flex-1 p-4 bg-emerald-600/5 dark:bg-emerald-500/5 text-emerald-600 rounded-2xl flex flex-col items-center gap-2 hover:bg-emerald-600 hover:text-white transition-all shadow-xl shadow-emerald-600/5 hover:shadow-emerald-600/20">
                    <Icons.UploadCloud size={20} />
                    <span className="text-[9px] font-black uppercase tracking-widest">Restore Backup</span>
                  </button>
                  <input type="file" ref={importFileRef} onChange={handleImport} accept=".json" className="hidden" />
               </div>
            </div>
          </div>
        )}
      </main>

      {selectedGroup && <InviteModal group={selectedGroup} onClose={() => setSelectedGroup(null)} botToken={token} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { TelegramGroup } from '../types.ts';
import { Icons } from '../constants.tsx';

interface GroupCardProps {
  group: TelegramGroup;
  isPriority?: boolean;
  onClick: (group: TelegramGroup) => void;
}

// Map of vibrant colors for the cards
const CARD_THEMES = [
  { border: 'border-blue-400/30', bg: 'bg-blue-50/50 dark:bg-blue-900/10', icon: 'text-blue-500', glow: 'shadow-blue-500/10' },
  { border: 'border-rose-400/30', bg: 'bg-rose-50/50 dark:bg-rose-900/10', icon: 'text-rose-500', glow: 'shadow-rose-500/10' },
  { border: 'border-emerald-400/30', bg: 'bg-emerald-50/50 dark:bg-emerald-900/10', icon: 'text-emerald-500', glow: 'shadow-emerald-500/10' },
  { border: 'border-amber-400/30', bg: 'bg-amber-50/50 dark:bg-amber-900/10', icon: 'text-amber-500', glow: 'shadow-amber-500/10' },
  { border: 'border-indigo-400/30', bg: 'bg-indigo-50/50 dark:bg-indigo-900/10', icon: 'text-indigo-500', glow: 'shadow-indigo-500/10' },
  { border: 'border-purple-400/30', bg: 'bg-purple-50/50 dark:bg-purple-900/10', icon: 'text-purple-500', glow: 'shadow-purple-500/10' },
  { border: 'border-cyan-400/30', bg: 'bg-cyan-50/50 dark:bg-cyan-900/10', icon: 'text-cyan-500', glow: 'shadow-cyan-500/10' },
];

const GroupCard: React.FC<GroupCardProps> = ({ group, isPriority, onClick }) => {
  const [copied, setCopied] = useState(false);

  // Pick a stable theme based on group ID
  const themeIndex = Math.abs(parseInt(group.id.substring(group.id.length - 2))) % CARD_THEMES.length;
  const theme = CARD_THEMES[themeIndex];

  const copyId = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(group.id);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div 
      onClick={() => onClick(group)}
      className={`group relative ${theme.bg} border ${theme.border} rounded-2xl p-4 flex flex-col gap-3 hover:border-blue-500/50 hover:bg-white dark:hover:bg-slate-900 transition-all duration-300 cursor-pointer ${theme.glow} hover:shadow-xl active:scale-[0.98]`}
    >
      <div className="flex items-center gap-3">
        <div className={`w-12 h-12 rounded-xl overflow-hidden bg-white dark:bg-slate-800 flex-shrink-0 border ${theme.border} shadow-sm group-hover:scale-110 transition-transform`}>
          <img 
            src={group.image} 
            alt={group.name} 
            className="w-full h-full object-cover grayscale-[0.2] group-hover:grayscale-0"
            loading="lazy"
          />
        </div>

        <div className="flex-1 min-w-0">
          <h3 className="text-sm font-black text-slate-900 dark:text-white truncate group-hover:text-blue-600 transition-colors">{group.name}</h3>
          <div className="flex items-center gap-1.5 text-slate-400 dark:text-slate-500">
            <Icons.Users size={10} strokeWidth={3} className={theme.icon} />
            <span className="text-[9px] font-black uppercase tracking-widest">{group.memberCount.toLocaleString()} Members</span>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between pt-3 border-t border-slate-200/50 dark:border-slate-800/60">
        <button 
          onClick={copyId}
          className="flex items-center gap-1.5 px-2 py-1 bg-white/60 dark:bg-slate-800/50 rounded-lg hover:bg-blue-600/10 transition-colors border border-transparent hover:border-blue-500/20"
        >
          <span className="text-[8px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-widest">
            ID: {group.id.length > 8 ? `${group.id.substring(0, 8)}...` : group.id}
          </span>
          <Icons.Copy size={10} className={copied ? 'text-emerald-500' : 'text-slate-300'} />
        </button>

        <div className={`w-8 h-8 ${theme.bg} rounded-lg flex items-center justify-center ${theme.icon} group-hover:bg-blue-600 group-hover:text-white transition-all shadow-sm border ${theme.border}`}>
          <Icons.Link size={16} />
        </div>
      </div>
    </div>
  );
};

