  { border: 'border-amber-600/40', bg: 'bg-amber-600/30 dark:bg-amber-600/20', icon: 'text-amber-600', glow: 'shadow-amber-600/10' },
  { border: 'border-indigo-600/40', bg: 'bg-indigo-600/30 dark:bg-indigo-600/20', icon: 'text-indigo-600', glow: 'shadow-indigo-600/10' },
