];

const GroupCard: React.FC<GroupCardProps> = ({ group, isPriority, onClick }) => {
  const [copied, setCopied] = useState(false);

  // Pick a stable theme based on group ID
  const themeIndex = Math.abs(parseInt(group.id.slice(-2))) % CARD_THEMES.length;
  const theme = CARD_THEMES[themeIndex];

  const copyId = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(group.id);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div 
      onClick={() => onClick(group)}
      className={`group relative ${theme.bg} border-2 ${theme.border} rounded-2xl p-4 flex flex-col gap-3 hover:bg-white dark:hover:bg-slate-900 transition-all duration-500 cursor-pointer ${theme.glow} hover:shadow-2xl active:scale-[0.98]`}
