        <div className={`w-10 h-10 rounded-xl overflow-hidden bg-white dark:bg-slate-800 flex-shrink-0 border ${theme.border} group-hover:scale-110 transition-transform shadow-sm`}>
          <img 
            src={group.image} 
            alt={group.name} 
            className="w-full h-full object-cover"
            loading="lazy"
          />
