            <span className="text-[8px] font-black uppercase tracking-widest">{group.memberCount.toLocaleString()} Users</span>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between pt-3 border-t border-slate-900/10 dark:border-white/10">
        <button 
          onClick={copyId}
          className="flex items-center gap-1.5 px-2 py-1 bg-white/40 dark:bg-slate-800/40 rounded-lg hover:bg-white transition-all shadow-sm"
        >
          <span className="text-[7px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">
            ID: {group.id.length > 10 ? `${group.id.slice(0, 10)}...` : group.id}
