          <Icons.Copy size={10} className={copied ? 'text-emerald-600' : 'text-slate-400'} strokeWidth={3} />
        </button>

        <div className={`w-7 h-7 bg-white/50 dark:bg-slate-800 rounded-lg flex items-center justify-center ${theme.icon} group-hover:bg-blue-600 group-hover:text-white transition-all shadow-sm`}>
          <Icons.Link size={14} strokeWidth={3} />
        </div>
      </div>
    </div>
  );
};

