    if (!token) return;
    try {
      await kickChatMember(token, chatId, userId);
      setJoinEvents(prev => prev.filter(e => `${e.userId}-${e.timestamp}` !== eventId));
      setPendingKick(null);
      alert("Candidate purged from hub.");
    } catch (err: any) { alert(`Kick failed: ${err.message}`); }
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.joinEvents) setJoinEvents(data.joinEvents);
        if (data.groups) setGroups(data.groups);
        if (data.token) setToken(data.token);
        alert('Archives Restored!');
      } catch (err) { alert('Import failed: Invalid Data'); }
    };
    reader.readAsText(file);
    if (e.target) e.target.value = '';
  };

  const handleExport = () => {
    const data = { joinEvents, groups, token, theme };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `telebridge-backup-${selectedDate}.json`;
    a.click();
  };

  const scrollToTop = () => {
    analysisScrollRef.current?.scrollTo({ top: 0, behavior: 'smooth' });
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const filteredJoins = useMemo(() => joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === selectedDate).sort((a, b) => b.timestamp - a.timestamp), [joinEvents, selectedDate]);
  const joinsToday = useMemo(() => joinEvents.filter(e => new Date(e.timestamp).toISOString().split('T')[0] === new Date().toISOString().split('T')[0]).length, [joinEvents]);
  const filteredGroups = useMemo(() => groups.filter(g => g.name.toLowerCase().includes(searchQuery.toLowerCase()) || g.id.includes(searchQuery)), [groups, searchQuery]);

  // Format time in 12-hour system
  const formatTime12h = (timestamp: number) => {
    return new Date(timestamp).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 flex flex-col md:flex-row font-sans transition-all duration-300">
