import React, { useState } from 'react';
import { TelegramGroup } from '../types.ts';
import { Icons } from '../constants.tsx';

interface GroupCardProps {
  group: TelegramGroup;
  isPriority?: boolean;
  onClick: (group: TelegramGroup) => void;
}

// Map of Deep colorful card themes with medium opacity (approx 40-50%)
const CARD_THEMES = [
  { border: 'border-blue-500/50', bg: 'bg-blue-600/40 dark:bg-blue-900/40', icon: 'text-blue-600 dark:text-blue-400', glow: 'shadow-blue-500/20' },
  { border: 'border-rose-500/50', bg: 'bg-rose-600/40 dark:bg-rose-900/40', icon: 'text-rose-600 dark:text-rose-400', glow: 'shadow-rose-500/20' },
  { border: 'border-emerald-500/50', bg: 'bg-emerald-600/40 dark:bg-emerald-900/40', icon: 'text-emerald-600 dark:text-emerald-400', glow: 'shadow-emerald-500/20' },
  { border: 'border-amber-500/50', bg: 'bg-amber-600/40 dark:bg-amber-900/40', icon: 'text-amber-600 dark:text-amber-400', glow: 'shadow-amber-500/20' },
  { border: 'border-indigo-500/50', bg: 'bg-indigo-600/40 dark:bg-indigo-900/40', icon: 'text-indigo-600 dark:text-indigo-400', glow: 'shadow-indigo-500/20' },
  { border: 'border-purple-500/50', bg: 'bg-purple-600/40 dark:bg-purple-900/40', icon: 'text-purple-600 dark:text-purple-400', glow: 'shadow-purple-500/20' },
  { border: 'border-cyan-500/50', bg: 'bg-cyan-600/40 dark:bg-cyan-900/40', icon: 'text-cyan-600 dark:text-cyan-400', glow: 'shadow-cyan-500/20' },
];

const GroupCard: React.FC<GroupCardProps> = ({ group, onClick }) => {
  const [copied, setCopied] = useState(false);

  // Pick a stable theme based on group ID hash
  const themeIndex = Math.abs(parseInt(group.id.slice(-3))) % CARD_THEMES.length;
  const theme = CARD_THEMES[themeIndex];

  const copyId = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(group.id);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div 
      onClick={() => onClick(group)}
      className={`group relative ${theme.bg} border-2 ${theme.border} rounded-3xl p-5 flex flex-col gap-4 hover:bg-opacity-10 dark:hover:bg-slate-900 transition-all duration-500 cursor-pointer ${theme.glow} hover:shadow-3xl active:scale-[0.97] backdrop-blur-sm`}
    >
      <div className="flex items-center gap-4">
        <div className={`w-12 h-12 rounded-2xl overflow-hidden bg-white dark:bg-slate-800 flex-shrink-0 border-2 ${theme.border} group-hover:scale-110 transition-all duration-500 shadow-xl`}>
          <img 
            src={group.image} 
            alt={group.name} 
            className="w-full h-full object-cover"
            loading="lazy"
          />
        </div>

        <div className="flex-1 min-w-0">
          <h3 className="text-[13px] font-black text-slate-900 dark:text-white truncate group-hover:text-blue-600 transition-colors uppercase tracking-tight">{group.name}</h3>
          <div className="flex items-center gap-1.5 text-slate-600 dark:text-slate-300">
            <Icons.Users size={12} strokeWidth={4} className={theme.icon} />
            <span className="text-[9px] font-black uppercase tracking-[0.1em]">{group.memberCount.toLocaleString()} Verified</span>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between pt-4 border-t border-slate-900/5 dark:border-white/5">
        <button 
          onClick={copyId}
          className="flex items-center gap-2 px-3 py-1.5 bg-white/50 dark:bg-slate-800/50 rounded-xl hover:bg-white transition-all shadow-md border border-transparent hover:border-blue-500/20"
        >
          <span className="text-[8px] font-black text-slate-500 dark:text-slate-400 uppercase tracking-widest">
            {group.id.length > 12 ? `${group.id.slice(0, 12)}...` : group.id}
          </span>
          <Icons.Copy size={11} className={copied ? 'text-emerald-600' : 'text-slate-400'} strokeWidth={3} />
        </button>

        <div className={`w-9 h-9 bg-white/60 dark:bg-slate-800 rounded-xl flex items-center justify-center ${theme.icon} group-hover:bg-blue-600 group-hover:text-white group-hover:shadow-xl group-hover:shadow-blue-500/30 transition-all shadow-md`}>
          <Icons.Link size={16} strokeWidth={3} />
        </div>
      </div>
    </div>
  );
};

export default GroupCard;

