              </button>

              <div className="hidden sm:flex items-center gap-2 px-3 py-2 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl shadow-sm">
                <div className={`w-2 h-2 rounded-full ${botInfo ? 'bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.7)]' : 'bg-rose-500 animate-pulse'}`} />
                <span className="text-[10px] font-black tracking-widest uppercase opacity-80">{botInfo ? 'BOT ACTIVE' : 'BOT OFFLINE'}</span>
              </div>

              <button 
                onClick={() => discoverGroupsAndJoins(token)} 
