interface GroupCardProps {
  group: TelegramGroup;
  onClick: (group: TelegramGroup) => void;
}

const UNIQUE_THEMES = [
  { gradient: 'from-blue-600/40 to-indigo-700/40', accent: 'bg-blue-600', shadow: 'shadow-blue-500/20', pattern: 'radial-gradient(circle at 2px 2px, rgba(59,130,246,0.1) 1px, transparent 0)' },
  { gradient: 'from-emerald-500/40 to-teal-700/40', accent: 'bg-emerald-600', shadow: 'shadow-emerald-500/20', pattern: 'radial-gradient(circle at 2px 2px, rgba(16,185,129,0.1) 1px, transparent 0)' },
  { gradient: 'from-rose-500/40 to-pink-700/40', accent: 'bg-rose-600', shadow: 'shadow-rose-500/20', pattern: 'radial-gradient(circle at 2px 2px, rgba(244,63,94,0.1) 1px, transparent 0)' },
  { gradient: 'from-amber-400/40 to-orange-600/40', accent: 'bg-amber-600', shadow: 'shadow-amber-500/20', pattern: 'radial-gradient(circle at 2px 2px, rgba(245,158,11,0.1) 1px, transparent 0)' },
  { gradient: 'from-purple-600/40 to-fuchsia-700/40', accent: 'bg-purple-600', shadow: 'shadow-purple-500/20', pattern: 'radial-gradient(circle at 2px 2px, rgba(147,51,234,0.1) 1px, transparent 0)' },
  { gradient: 'from-cyan-500/40 to-blue-600/40', accent: 'bg-cyan-600', shadow: 'shadow-cyan-500/20', pattern: 'radial-gradient(circle at 2px 2px, rgba(6,182,212,0.1) 1px, transparent 0)' },
];

const GroupCard: React.FC<GroupCardProps> = ({ group, onClick }) => {
  const [copied, setCopied] = useState(false);

  // Stable theme selection
  const themeIndex = Math.abs(parseInt(group.id.slice(-4)) || 0) % UNIQUE_THEMES.length;
  const theme = UNIQUE_THEMES[themeIndex];

  const copyId = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(group.id);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div 
      onClick={() => onClick(group)}
      className={`group relative bg-gradient-to-br ${theme.gradient} dark:bg-slate-900/60 backdrop-blur-md border border-slate-200/30 dark:border-slate-800/50 rounded-[1.75rem] p-3 flex flex-col gap-2 hover:border-blue-500/50 transition-all duration-500 cursor-pointer shadow-xl hover:shadow-2xl active:scale-[0.98] overflow-hidden`}
      style={{ backgroundImage: theme.pattern, backgroundSize: '15px 15px' }}
    >
      {/* Slimmer Accent Line */}
      <div className={`absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-transparent via-white/50 to-transparent opacity-30 group-hover:opacity-100 transition-opacity`} />

      <div className="flex items-center gap-3">
        <div className={`w-10 h-10 rounded-xl overflow-hidden bg-white/40 dark:bg-slate-800 flex-shrink-0 group-hover:scale-110 transition-transform duration-500 border border-white/20 shadow-md`}>
          <img src={group.image} alt={group.name} className="w-full h-full object-cover" loading="lazy" />
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="text-[11px] font-black text-slate-900 dark:text-white truncate uppercase tracking-tight leading-tight mb-0.5">{group.name}</h3>
          <div className="flex items-center gap-1">
            <Icons.Users size={9} strokeWidth={4} className="text-slate-900 dark:text-white/60" />
            <span className="text-[8px] font-black text-slate-900/60 dark:text-slate-400 uppercase tracking-widest">{group.memberCount} MEMBERS</span>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between pt-2 mt-1 border-t border-white/10 dark:border-slate-800">
        <button onClick={copyId} className="flex items-center gap-1.5 px-2 py-1 bg-white/20 dark:bg-slate-800/50 rounded-lg hover:bg-white/40 transition-all max-w-[100px] overflow-hidden backdrop-blur-sm">
          <span className="text-[7px] font-black text-slate-800 dark:text-slate-400 uppercase tracking-widest truncate">ID: {group.id}</span>
          <Icons.Copy size={9} className={copied ? 'text-emerald-700' : 'text-slate-600 dark:text-slate-400'} />
        </button>
        <div className={`w-7 h-7 ${theme.accent} text-white rounded-lg flex items-center justify-center group-hover:scale-110 transition-all shadow-lg active:scale-90`}>
          <Icons.Link size={12} strokeWidth={3} />
        </div>
      </div>
    </div>
  );
};

