                   >
                     {isAddingGroup ? 'Connecting...' : 'Inject Batch'}
                   </button>
                 </div>
              </div>

              <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-200 dark:border-slate-800 p-6 shadow-xl">
                 <h2 className="text-sm font-black uppercase tracking-tight mb-4 opacity-50">Recent Logs</h2>
                 <div className="space-y-3">
                   {joinEvents.slice(0, 3).map((e, i) => (
                     <div key={i} className={`flex items-center justify-between p-4 rounded-2xl border ${ROW_COLORS[i % ROW_COLORS.length]}`}>
