              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {filteredGroups.map(g => (
                  <GroupCard key={g.id} group={g} onClick={() => setSelectedGroup(g)} />
                ))}
              </div>
            </div>
          )}

          {activeTab === 'analysis' && (
            <div className="space-y-6 animate-in slide-in-from-bottom-8 duration-500">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                 <div className="bg-indigo-600 p-6 rounded-[2.5rem] border-b-4 border-indigo-900 shadow-[0_20px_40px_rgba(79,70,229,0.3)] text-white group relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-white/10 rounded-full translate-x-12 -translate-y-12 group-hover:scale-150 transition-transform" />
