                    <p className="text-[10px] font-black uppercase tracking-[0.2em] mb-1">Live Audit</p>
                    <p className="text-4xl font-black">ACTIVE</p>
                    <p className="text-[9px] font-bold mt-2 opacity-70">Streaming encrypted updates...</p>
