                       <button onClick={handleExport} className="p-2 bg-blue-600 text-white rounded-lg shadow-sm active:scale-90"><Icons.DownloadCloud size={14}/></button>
                       <button onClick={() => importFileRef.current?.click()} className="p-2 bg-emerald-600 text-white rounded-lg shadow-sm active:scale-90"><Icons.UploadCloud size={14}/></button>
                       <input type="file" ref={importFileRef} onChange={handleImport} accept=".json" className="hidden" />
                    </div>
                 </div>
                 <div className="overflow-y-auto max-h-[50vh] custom-scrollbar">
                   <table className="w-full text-left">
                      <thead className="sticky top-0 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md z-10 border-b border-slate-100 dark:border-slate-800">
