const UNIQUE_THEMES = [
  { 
    gradient: 'from-blue-600/30 to-indigo-700/30', 
    accent: 'bg-blue-600', 
    border: 'border-blue-500/30',
    pattern: 'radial-gradient(circle at 2px 2px, rgba(59,130,246,0.15) 1px, transparent 0)' 
  },
