    accent: 'bg-purple-600', 
    border: 'border-purple-500/30',
    pattern: 'radial-gradient(circle at 2px 2px, rgba(147,51,234,0.15) 1px, transparent 0)' 
  },
  { 
    gradient: 'from-cyan-500/30 to-blue-600/30', 
    accent: 'bg-cyan-600', 
    border: 'border-cyan-500/30',
    pattern: 'radial-gradient(circle at 2px 2px, rgba(6,182,212,0.15) 1px, transparent 0)' 
  },
];

const GroupCard: React.FC<GroupCardProps> = ({ group, onClick }) => {
  const [copied, setCopied] = useState(false);

  // Stable theme based on ID
  const themeIndex = Math.abs(parseInt(group.id.slice(-4)) || 0) % UNIQUE_THEMES.length;
  const theme = UNIQUE_THEMES[themeIndex];

  const copyId = (e: React.MouseEvent) => {
    e.stopPropagation();
    navigator.clipboard.writeText(group.id);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div 
      onClick={() => onClick(group)}
      className={`group relative bg-gradient-to-br ${theme.gradient} dark:bg-slate-900/40 backdrop-blur-lg border ${theme.border} rounded-[2rem] p-4 flex flex-col gap-3 hover:-translate-y-1 transition-all duration-500 cursor-pointer shadow-xl hover:shadow-2xl active:scale-[0.98] active:translate-y-0 overflow-hidden`}
      style={{ backgroundImage: theme.pattern, backgroundSize: '12px 12px' }}
    >
      {/* 3D Highlight Shine */}
      <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700" />

      <div className="flex items-center gap-4 relative z-10">
        <div className="w-11 h-11 rounded-2xl overflow-hidden bg-white/50 dark:bg-slate-800/50 flex-shrink-0 group-hover:scale-110 transition-transform duration-500 border border-white/20 shadow-lg">
          <img src={group.image} alt={group.name} className="w-full h-full object-cover" loading="lazy" />
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="text-[12px] font-black text-slate-900 dark:text-white truncate uppercase tracking-tight leading-tight mb-1">{group.name}</h3>
          <div className="flex items-center gap-1">
            <Icons.Users size={10} strokeWidth={4} className="text-slate-900 dark:text-slate-100" />
            <span className="text-[9px] font-black text-slate-900/60 dark:text-slate-400 uppercase tracking-widest">{group.memberCount} BATCHED</span>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between pt-3 mt-1 border-t border-black/5 dark:border-white/5 relative z-10">
        <button onClick={copyId} className="flex items-center gap-2 px-3 py-1.5 bg-white/30 dark:bg-slate-800/40 rounded-xl hover:bg-white/50 transition-all shadow-sm">
          <span className="text-[8px] font-black text-slate-800 dark:text-slate-400 uppercase tracking-widest truncate max-w-[80px]">ID: {group.id}</span>
          <Icons.Copy size={10} className={copied ? 'text-emerald-700' : 'text-slate-600 dark:text-slate-400'} />
        </button>
        <div className={`w-8 h-8 ${theme.accent} text-white rounded-xl flex items-center justify-center group-hover:scale-110 transition-all shadow-lg active:scale-90`}>
          <Icons.Link size={14} strokeWidth={3} />
        </div>
      </div>
    </div>
  );
};

