  return (
    <div 
      onClick={() => onClick(group)}
      className={`group relative bg-gradient-to-br ${theme.gradient} dark:bg-slate-900/60 backdrop-blur-md border ${theme.border} rounded-2xl p-2.5 flex flex-col gap-2 hover:-translate-y-1 transition-all duration-500 cursor-pointer shadow-lg hover:shadow-2xl active:scale-[0.97] active:translate-y-0 overflow-hidden border-b-2 border-r-2`}
