          <div className="flex items-center gap-1">
            <span className="text-[7.5px] font-black text-slate-900/50 dark:text-slate-400 uppercase tracking-widest leading-none">{group.memberCount} MEMBERS</span>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between pt-1.5 mt-0.5 border-t border-black/5 dark:border-white/5 relative z-10">
        <button onClick={copyId} className="flex items-center gap-1 px-2 py-1 bg-white/30 dark:bg-slate-800/40 rounded-lg hover:bg-white/50 transition-all shadow-sm">
          <span className="text-[6.5px] font-black text-slate-800 dark:text-slate-400 uppercase tracking-widest truncate max-w-[60px]">ID: {group.id}</span>
          <Icons.Copy size={8} className={copied ? 'text-emerald-700' : 'text-slate-600 dark:text-slate-400'} />
        </button>
        <div className={`w-6 h-6 ${theme.accent} text-white rounded-lg flex items-center justify-center group-hover:scale-110 transition-all shadow-md active:scale-90`}>
          <Icons.Link size={10} strokeWidth={4} />
        </div>
      </div>
    </div>
  );
