          {activeTab === 'settings' && (
            <div className="max-w-xl space-y-6 animate-in slide-in-from-left-6 duration-500">
               <div className="bg-indigo-700/10 p-8 rounded-[3rem] border-2 border-indigo-500/20 shadow-xl">
